local config = {
  ui_story_5068_50680101_1_dialog_content = "<color=#e8d9bb><size=50>Menabrak!!!</size></color>",
  ui_story_5068_50680101_2_dialog_content = "(... Kenapa...)",
  ui_story_5068_50680101_3_dialog_content = "Aduh!",
  ui_story_5068_50680101_4_dialog_content = "Kenapa orang gila ini menggigit semua orang yang dilihatnya?! Untungnya aku bereaksi cepat!",
  ui_story_5068_50680101_5_dialog_content = "Berani-beraninya kalian mendekati diam-diam?! Kami bukan sasaran yang mudah! Bunuh mereka, sekarang!",
  ui_story_5068_50680101_6_dialog_content = "Mari kita lihat siapa di antara kita yang akhirnya mati.",
  ui_story_5068_50680101_7_dialog_content = "(... Bagaimana bisa semuanya berakhir seperti ini?)",
  ui_story_5068_50680101_8_dialog_content = "Ugh!",
  ui_story_5068_50680101_9_dialog_content = "Apa ini?! Gila! Semua orang, siapkan senjatamu! Cepat!!!",
  ui_story_5068_50680101_10_dialog_content = "<color=#e8d9bb>Brak! Brak!</color>",
  ui_story_5068_50680101_11_dialog_content = "Ahhh!",
  ui_story_5068_50680101_12_dialog_content = "Jangan biarkan mereka semua lolos!!!",
  ui_story_5068_50680101_13_dialog_content = "<color=#e8d9bb><size=45>Bam! Bam! Bam!</size></color>",
  ui_story_5068_50680101_14_dialog_content = "Apa... Apa sebenarnya yang terjadi di sini?!",
  ui_story_5068_50680101_15_dialog_content = "Nona Sheol!!!",
  ui_story_5068_50680101_16_dialog_content = "Kamu bilang pekerjaan ini sama sekali tidak berbahaya—!!",
  ui_story_5068_50680101_17_dialog_content = "<color=#e8d9bb>Satu hari yang lalu</color>",
  ui_story_5068_50680101_18_dialog_content = "Wah, tempat ini sangat megah sekarang! Itu berkat Cloudrover Guild—atau mungkin ini semua berkat Anda, Lady Sheol?",
  ui_story_5068_50680101_19_dialog_content = "Sudah lama aku tidak ke sini, tapi tempat ini berkembang pesat sekali. Baru saja aku hampir tersesat.",
  ui_story_5068_50680101_20_dialog_content = "Heheh, apakah benar-benar sehebat itu? Saya yakin itu tidak ada apa-apanya dibandingkan dengan Colossus megah milikmu.",
  ui_story_5068_50680101_21_dialog_content = "Aku lihat kamu datang sendirian hari ini... Di mana gadis-gadis muda yang biasanya ada di sampingmu? Jangan bilang mereka benar-benar tersesat di Cloudrover Guild?",
  ui_story_5068_50680101_22_dialog_content = "Yah, pekerjaan ini diklasifikasikan sebagai \"risiko sangat rendah\", jadi meskipun aku sama sekali tidak bisa bertarung, aku pikir...",
  ui_story_5068_50680101_23_dialog_content = "A-Ahem! Lagipula, aku tidak ingin terus mengganggu teman-temanku dengan hal-hal seperti ini! Mereka juga butuh istirahat!",
  ui_story_5068_50680101_24_dialog_content = "Aku mengerti. Kata-katamu membuatku tidak punya pilihan selain menilai ulang kesanku tentangmu.",
  ui_story_5068_50680101_25_dialog_content = "Melakukan sesuatu sendiri bukanlah hal yang buruk, tetapi jangan lupa bahwa selalu ada saat-saat di mana kita perlu mengandalkan orang lain.",
  ui_story_5068_50680101_26_dialog_content = "Terima kasih atas kepedulianmu, tapi jangan khawatir. Aku tahu batasan diriku lebih baik daripada orang lain, itulah sebabnya aku selalu berhati-hati saat bekerja sendiri.",
  ui_story_5068_50680101_27_dialog_content = "Aku tidak perlu khawatir jika kamu yang membantuku. Namun, ada satu hal yang harus jelas: bayaranmu akan ditentukan oleh berapa banyak kepala yang kamu bawakan untukku.",
  ui_story_5068_50680101_28_dialog_content = "Apa?!?",
  ui_story_5068_50680101_29_dialog_content = "Heheh, reaksimu selalu paling menghibur. Tapi cukup bercanda untuk sekarang, mari lanjutkan ke urusan yang sebenarnya.",
  ui_story_5068_50680101_30_dialog_content = "Sebenarnya, pekerjaan ini tidak bisa dilakukan tanpa kamu, itulah mengapa saya tidak berani menempatkanmu dalam bahaya.",
  ui_story_5068_50680101_31_dialog_content = "Ayo lihat ini.",
  ui_story_5068_50680101_32_dialog_content = "Ada apa?",
  ui_story_5068_50680101_33_dialog_content = "Santai saja dan periksalah dengan teliti.",
  ui_story_5068_50680101_34_dialog_content = "Aku bisa melihat sesuatu dengan samar di sana. Apakah itu... bola kabut hitam?",
  ui_story_5068_50680101_35_dialog_content = "Tidak... Ini bukan kabut biasa. Aku bisa merasakan sesuatu di dalamnya... Kehadiran yang unik.",
  ui_story_5068_50680101_36_option_content = "Force Boost!",
  ui_story_5068_50680101_37_dialog_content = "Tunggu, ini...?!",
  ui_story_5068_50680101_38_dialog_content = "Dulu ada Lumina di dalam kabut ini!",
  ui_story_5068_50680101_39_dialog_content = "Dulu?",
  ui_story_5068_50680101_40_dialog_content = "Ya! Dulu ada Lumina di dalam kabut ini, tapi sekarang sudah hilang sama sekali... Semua kecuali beberapa jejak, yang hanya bisa aku rasakan dengan menggunakan kekuatanku.",
  ui_story_5068_50680101_41_dialog_content = "... Apakah kamu melihat sesuatu yang lain?",
  ui_story_5068_50680101_42_dialog_content = "Tidak.",
  ui_story_5068_50680101_43_dialog_content = "Kamu yakin? Aku perlu kamu benar-benar yakin tentang ini.",
  ui_story_5068_50680101_44_dialog_content = "Apakah ini alasan Anda membutuhkan bantuan saya? Untuk menyelidiki kabut hitam aneh ini?",
  ui_story_5068_50680101_45_dialog_content = "Memang, tapi ini hanya satu bagian dari pekerjaan. Tepatnya, titik awal.",
  ui_story_5068_50680101_46_dialog_content = "Aku tahu itu tidak akan sesederhana itu.",
  ui_story_5068_50680101_47_dialog_content = "Dalam beberapa hari terakhir, penyakit yang sangat berbahaya telah menyebar di seluruh Umbraton... atau begitu lah yang saya pikirkan.",
  ui_story_5068_50680101_48_dialog_content = "Wow, aku rasa belum pernah dengar kamu terdengar begitu tidak yakin.",
  ui_story_5068_50680101_49_dialog_content = "Begitu ya? Bagaimanapun... \"menyebar\" mungkin bukan kata yang paling tepat untuk menggambarkannya.",
  ui_story_5068_50680101_50_dialog_content = "Penyakit ini menyerang dalam wabah yang sering dan terkonsentrasi, tetapi tampaknya tidak mengikuti pola tertentu. Area yang terkena dampak tersebar secara acak di seluruh Umbraton, seperti tetesan hujan yang jatuh dari langit. Hal ini membuat pelacakan penyakit menjadi sangat sulit dan frustasi.",
  ui_story_5068_50680101_51_dialog_content = "Jadi, itu tidak menular?",
  ui_story_5068_50680101_52_dialog_content = "Aku tidak bisa yakin, tetapi temuan awal saya menunjukkan hal tersebut. Namun, ini bukan aspek paling mengkhawatirkan dari penyakit ini.",
  ui_story_5068_50680101_53_dialog_content = "Apa ya kira-kira?",
  ui_story_5068_50680101_54_dialog_content = "Gejalanya.",
  ui_story_5068_50680101_55_dialog_content = "Ada apa dengan bunganya?",
  ui_story_5068_50680101_56_dialog_content = "Semua orang tahu bahwa berbagai penyakit memiliki gejala yang berbeda. Misalnya, seseorang yang menderita flu akan menunjukkan gejala yang berbeda dibandingkan dengan seseorang yang menderita sakit perut.",
  ui_story_5068_50680101_57_dialog_content = "Tentu saja, beberapa penyakit juga memiliki gejala yang mirip, seperti flu biasa dan pneumonia. Namun, hal ini tidak berlaku untuk penyakit misterius Umbraton.",
  ui_story_5068_50680101_58_dialog_content = "Orang-orang yang baru-baru ini terkena dampaknya semuanya menunjukkan gejala yang berbeda-beda...",
  ui_story_5068_50680101_59_dialog_content = "Beberapa merasakan sakit yang menyiksa di seluruh tubuh mereka, beberapa telah kehilangan suara mereka sepenuhnya, dan beberapa ambruk karena kelelahan akibat mania yang tak terkendali... Dan ini hanyalah beberapa dari banyak gejala yang tak terjelaskan yang baru-baru ini dilaporkan.",
  ui_story_5068_50680101_60_dialog_content = "Lalu, bukankah mungkin mereka menderita penyakit yang berbeda?",
  ui_story_5068_50680101_61_dialog_content = "Tak bisa kusangkal kemungkinan itu, tapi menurutmu tidak aneh?",
  ui_story_5068_50680101_62_dialog_content = "Berdasarkan temuan sebelumnya, orang-orang ini sama sekali tidak menunjukkan gejala sebelum jatuh sakit. Jika hanya satu atau dua orang, kita bisa menyebutnya kebetulan.",
  ui_story_5068_50680101_63_dialog_content = "Tapi bagaimana jika hal itu berlaku untuk mayoritas kasus? Karena lebih dari sembilan puluh persen pasien dalam keadaan sehat sempurna suatu hari dan kemudian sakit parah di hari berikutnya.",
  ui_story_5068_50680101_64_dialog_content = "Mungkinkah itu benar-benar hanya kebetulan?",
  ui_story_5068_50680101_65_dialog_content = "Jadi maksudmu...",
  ui_story_5068_50680101_66_dialog_content = "Ini.",
  ui_story_5068_50680101_67_dialog_content = "Maaf, Nona Sheol, tapi aku kurang mengerti...",
  ui_story_5068_50680101_68_dialog_content = "Ini adalah satu hal yang dimiliki setiap pasien secara bersamaan.",
  ui_story_5068_50680101_69_dialog_content = "Terlepas dari gejala atau lokasi, ada satu hal yang menghubungkan kasus-kasus yang tampaknya terisolasi ini.",
  ui_story_5068_50680101_70_dialog_content = "Maksudmu... kabut hitam ini?",
  ui_story_5068_50680101_71_dialog_content = "Tepat sekali. Mayoritas orang di setiap area yang terinfeksi melaporkan melihat kabut hitam ini pada suatu saat.",
  ui_story_5068_50680101_72_dialog_content = "Tentu saja, bawahan saya mempertaruhkan nyawa dalam bahaya yang mengancam jiwa untuk mendapatkan spesimen ini.",
  ui_story_5068_50680101_73_dialog_content = "Bahaya mengancam nyawa?!",
  ui_story_5068_50680101_74_dialog_content = "Hati-hati... Saya tidak tahu apa yang akan terjadi jika kabut ini bocor dari wadahnya.",
  ui_story_5068_50680101_75_dialog_content = "Tolong jangan menghilangkan detail penting seperti ini saat kamu meminta bantuan lain kali—",
  ui_story_5068_50680101_76_dialog_content = "Pokoknya... Kamu nggak mengharapkan aku menganalisis komposisi kabut hitam itu, kan?",
  ui_story_5068_50680101_77_dialog_content = "Jika itu masalahnya, maaf jika mengecewakan Anda, tetapi kemampuan psikisku hanya bisa melakukan sejauh ini.",
  ui_story_5068_50680101_78_dialog_content = "Tenanglah, menganalisis kabut hitam bukanlah alasan mengapa saya memanggil kalian ke sini hari ini.",
  ui_story_5068_50680101_79_dialog_content = "Saya hanya membutuhkan bantuan Anda untuk menemukan asal-usul kabut ini.",
  ui_story_5068_50680101_80_dialog_content = "Apakah kamu curiga... bahwa seseorang <color=#FFB400>sengaja</color> melepaskan kabut hitam di Umbraton?",
  ui_story_5068_50680101_81_dialog_content = "Saya masih belum bisa mengatakan dengan pasti, itulah mengapa saya memerlukan bantuan Anda.",
  ui_story_5068_50680101_82_dialog_content = "Pekerjaan ini sepertinya tidak terlalu aman bagi saya...",
  ui_story_5068_50680101_83_dialog_content = "Aku hanya perlu kamu melaporkan temuan mencurigakan kepadaku. Tidak perlu menggali terlalu dalam, apalagi berinteraksi dengan orang lain.",
  ui_story_5068_50680101_84_dialog_content = "Caelestite yang legendaris seharusnya tidak kesulitan dengan sesuatu yang sederhana ini.",
  ui_story_5068_50680101_85_dialog_content = "Jika itu masalahnya, saya seharusnya bisa menghindari sebagian besar situasi berbahaya dengan menggunakan kekuatanku. Tapi tetap saja...",
  ui_story_5068_50680101_86_dialog_content = "Saya siap memberikan kompensasi yang cukup besar untuk kesulitan Anda. Jika pekerjaan memakan waktu lebih lama dari yang diharapkan, saya juga akan membayar Anda sesuai.",
  ui_story_5068_50680101_87_dialog_content = "Ah, itu bukan yang saya maksud... Masih ada satu hal yang belum saya mengerti.",
  ui_story_5068_50680101_88_dialog_content = "Kabut hitam tampaknya tidak mempengaruhi Cloudrover Guild secara signifikan, jadi mengapa Anda begitu berusaha keras untuk menyelidikinya?",
  ui_story_5068_50680101_89_dialog_content = "Atau mungkin, tanpa sepengetahuanku, kamu tiba-tiba menjadi sangat bersemangat tentang amal?",
  ui_story_5068_50680101_90_dialog_content = "... Apakah itu benar-benar cara pandanganmu tentang saya? Kamu masih memiliki jalan panjang, pemuda.",
  ui_story_5068_50680101_91_dialog_content = "Berbisnis lebih dari sekadar membeli atau menjual. Ini bukan karena saya dermawan; saya hanya membayar biaya yang diperlukan untuk memastikan kelangsungan bisnis.",
  ui_story_5068_50680101_92_dialog_content = "Jadi, begitu, ya…",
  ui_story_5068_50680101_93_dialog_content = "Baik, itu mencakup semuanya. Sekarang terserah padamu, PlayerName.",
  ui_story_5068_50680101_94_dialog_content = "<color=#e8d9bb>Setelah kamu pergi...</color>",
  ui_story_5068_50680101_95_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_5068_50680101_96_dialog_content = "Ini aku.",
  ui_story_5068_50680101_97_dialog_content = "Nona Sheol! Aku akan segera ke sana!",
  ui_story_5068_50680101_98_dialog_content = "Oke.",
  ui_story_5068_50680201_1_dialog_content = "Aku berakhir di tempat yang suram ini saat mengejar kabut hitam itu... Aku ingin tahu apakah tempat ini termasuk dalam yurisdiksi Umbraton. Semoga saja begitu.",
  ui_story_5068_50680201_2_dialog_content = "<color=#e8d9bb>Heh... heh...</color>",
  ui_story_5068_50680201_3_dialog_content = "Aduh—aku baru saja merasa bulu kudukku merinding. Apakah ada yang benar-benar tinggal di rumah-rumah ini? Rasanya seperti sesuatu akan tiba-tiba melompat ke arahku...",
  ui_story_5068_50680201_4_option_content = "Sebaiknya aku kembali saja.",
  ui_story_5068_50680201_5_dialog_content = "Tidak, tidak, aku sudah sampai sejauh ini. Aku harus...",
  ui_story_5068_50680201_6_option_content = "Aku harus terus berjalan!",
  ui_story_5068_50680201_7_dialog_content = "Aku hanya perlu mencari tahu darimana asal kabut hitam itu dan melaporkannya kepada Lady Sheol. Aku tidak perlu khawatir tentang apa yang terjadi setelah itu.",
  ui_story_5068_50680201_8_dialog_content = "Lagipula, aku tak bisa menyerah di tengah jalan! Aku harus lebih kuat!",
  ui_story_5068_50680201_9_option_content = "Force Boost",
  ui_story_5068_50680201_10_dialog_content = "Hmm... Sepertinya aku semakin dekat dengan sumber kabut hitam ini.",
  ui_story_5068_50680201_11_dialog_content = "Saya benar-benar tidak menyangka semuanya berjalan lancar. Sepertinya Lady Sheol memang tidak berbohong tentang tingkat bahaya pekerjaan ini.",
  ui_story_5068_50680201_12_dialog_content = "Tolong! Ada orang di sana? Tolong!",
  ui_story_5068_50680201_13_dialog_content = "Hah? Apakah aku salah dengar, atau memang ada seseorang yang baru saja meminta tolong?",
  ui_story_5068_50680201_14_dialog_content = "Kamu, kamu, kamu! Menjauhlah! Tolong! Seseorang, TOLONG—!",
  ui_story_5068_50680201_15_dialog_content = "Mengaum-!",
  ui_story_5068_50680201_16_dialog_content = "Ahhhh—!",
  ui_story_5068_50680201_17_dialog_content = "Oh tidak! Tidak ada waktu—",
  ui_story_5068_50680201_18_dialog_content = "Minggir!!!",
  ui_story_5068_50680201_19_dialog_content = "Hah?",
  ui_story_5068_50680201_20_dialog_content = "Bagaimana Eclipsites bisa mencapai tempat ini?!",
  ui_story_5068_50680202_1_dialog_content = "(Luar biasa! Dia menghabisi setiap Eclipsite sebelum saya sempat bereaksi!)",
  ui_story_5068_50680202_2_dialog_content = "Setidaknya untuk saat ini, tidak ada lagi Eclipsites. Kamu baik-baik saja?",
  ui_story_5068_50680202_3_dialog_content = "... Aku baik-baik saja, jangan khawatir. Hampir saja. Terima kasih sudah menyelamatkanku, <color=#FFB400>Nona Asisten</color>.",
  ui_story_5068_50680202_4_dialog_content = "Tidak masalah. Saya tidak percaya Eclipsite berhasil menyelinap masuk ke sini meskipun ini masih bagian dari Umbraton. Sungguh sial!",
  ui_story_5068_50680202_5_dialog_content = "Gimana kamu bisa ketemu sama mereka?",
  ui_story_5068_50680202_6_dialog_content = "A-Aku tidak begitu yakin. Baru saja selesai bekerja, dan dalam perjalanan pulang, kabut datang tiba-tiba, dan semuanya menjadi gelap gulita, lalu...",
  ui_story_5068_50680202_7_dialog_content = "(... \"Kabut\"? \"Semuanya menjadi gelap gulita\"? Apakah ini yang kupikirkan?!)",
  ui_story_5068_50680202_8_dialog_content = "Kemudian tiba-tiba aku merasa sakit dan berpikir untuk pergi ke <color=#FFB400>dokter</color> untuk memeriksanya, tapi...",
  ui_story_5068_50680202_9_dialog_content = "Tapi kemudian kamu bertemu dengan hal-hal itu... Hari ini memang bukan harimu, ya?",
  ui_story_5068_50680202_10_dialog_content = "Begitulah keadaannya. Orang-orang seperti kita tidak punya pilihan lain selain tinggal di permukiman kumuh terpencil ini.",
  ui_story_5068_50680202_11_dialog_content = "Ketika ada sesuatu yang salah di sini... tidak ada yang peduli sama sekali. Jika saya tidak cukup beruntung untuk mendapatkan bantuan Anda, mungkin saya akan...",
  ui_story_5068_50680202_12_dialog_content = "Hei, hei, berhenti menangis! Kamu baik-baik saja, 'kan? Aku juga berhasil keluar tanpa terluka, jadi semuanya baik-baik saja!",
  ui_story_5068_50680202_13_dialog_content = "Masih bisa berdiri?",
  ui_story_5068_50680202_14_dialog_content = "Huh? Sepertinya kakiku mulai lemas...",
  ui_story_5068_50680202_15_dialog_content = "Huh...",
  ui_story_5068_50680202_16_dialog_content = "Maafkan aku, aku benar-benar tidak berguna. Ini bukan masalah besar, tapi aku...",
  ui_story_5068_50680202_17_dialog_content = "Nah, itu bukan yang saya maksud. Semua orang merasa takut saat melihat Eclipsite, jadi jangan terlalu keras pada diri sendiri.",
  ui_story_5068_50680202_18_dialog_content = "Hanya saja... <color=#FFB400>dokter</color> akan memiliki satu pasien lagi hari ini.",
  ui_story_5068_50680202_19_dialog_content = "Sini, berikan tanganmu dan aku akan membantumu berdiri!",
  ui_story_5068_50680202_20_dialog_content = "Terima kasih, Nona Asisten. Aku benar-benar minta maaf; kamu menyelamatkanku, tapi aku sudah menimbulkan begitu banyak masalah... Sebenarnya, aku bisa mandiri sekarang...",
  ui_story_5068_50680202_21_dialog_content = "Apa, kamu kira bisa keluar dari sini sendirian? Beri aku jeda!",
  ui_story_5068_50680202_22_dialog_content = "Bagaimana jika lebih banyak Eclipsite muncul? Apa yang akan kamu lakukan saat itu?",
  ui_story_5068_50680202_23_dialog_content = "Lagipula, aku baru saja menyelesaikan beberapa urusan untuk dokter dan dalam perjalanan kembali ke klinik. Jika kamu memiliki cukup energi untuk bicara omong kosong, maka berdirilah dan ikut denganku.",
  ui_story_5068_50680202_24_dialog_content = "Terima kasih…",
  ui_story_5068_50680202_25_dialog_content = "... Simpan itu untuk saat dokter mengobati kamu, sekarang ayo bergerak!",
  ui_story_5068_50680202_26_dialog_content = "Tunggu... Aku tidak salah lihat, kan? Wanita itu...",
  ui_story_5068_50680202_27_dialog_content = "Tubuhnya tampaknya tertutup oleh sesuatu yang mirip kabut hitam!",
  ui_story_5068_50680202_28_dialog_content = "Ini buruk, aku harus menyusul mereka!",
  ui_story_5068_50680301_1_dialog_content = "Aku tahu itu. Kehadiran kabut hitam sangat intens di sini!",
  ui_story_5068_50680301_2_dialog_content = "Rumah ini sama sekali tidak mencolok, menjadikannya tempat persembunyian yang sempurna... Aku benar-benar tidak percaya bisa menyelesaikan pekerjaanku begitu mudah.",
  ui_story_5068_50680301_3_dialog_content = "Sekarang yang harus kulakukan adalah melaporkan ke Nona Sheol, dan—",
  ui_story_5068_50680301_4_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5068_50680301_5_dialog_content = "...",
  ui_story_5068_50680301_6_dialog_content = "...",
  ui_story_5068_50680301_7_dialog_content = "Uh... H-Halo?",
  ui_story_5068_50680301_8_dialog_content = "Siapa kamu? Dan kenapa kamu berkeliaran di sini?",
  ui_story_5068_50680301_9_dialog_content = "Ah, aku...",
  ui_story_5068_50680301_10_dialog_content = "Karena... Perutku... Rasanya sakit...",
  ui_story_5068_50680301_11_dialog_content = "Kudengar ini adalah klinik...",
  ui_story_5068_50680301_12_dialog_content = "...",
  ui_story_5068_50680301_13_dialog_content = "Perutku... Sungguh sakit sekali...",
  ui_story_5068_50680301_14_dialog_content = "...",
  ui_story_5068_50680301_15_dialog_content = "(Tatapan dingin itu... Seperti dia menatap langsung ke dalam jiwaku. Jangan bilang... Apakah dia sudah melihat menembus diriku?!)",
  ui_story_5068_50680301_16_dialog_content = "... Ah... Yah... Sepertinya aku di tempat yang salah... B-Bisakah kamu tunjukkan arah ke klinik?",
  ui_story_5068_50680301_17_dialog_content = "A-aku bisa mencarinya sendiri...",
  ui_story_5068_50680301_18_dialog_content = "Maaf mengganggu...",
  ui_story_5068_50680301_19_dialog_content = "Tunggu!",
  ui_story_5068_50680301_20_dialog_content = "(Oh tidak, jig sudah terbongkar! Lebih baik aku segera lari!)",
  ui_story_5068_50680301_21_dialog_content = "Kamu tidak dengar aku?! Aku bilang tunggu!",
  ui_story_5068_50680301_22_dialog_content = "Hah? Apakah dia akan menyerangku?!",
  ui_story_5068_50680302_1_dialog_content = "Groar—",
  ui_story_5068_50680302_2_dialog_content = "Fiuh... Jadi selama ini ada Eclipsite di belakangku? Awalnya aku baik-baik saja, tapi serangannya barusan cukup menakutkan hingga membuatku merasa mual...",
  ui_story_5068_50680302_3_dialog_content = "\"Baik\"? Bukankah kamu bilang perutmu sakit?",
  ui_story_5068_50680302_4_dialog_content = "—!!!",
  ui_story_5068_50680302_5_dialog_content = "Sekarang kamu menyebutkannya, rasanya mulai sakit lagi... Eclipsite pasti membuatku sangat ketakutan sampai aku lupa akan rasa sakitnya.",
  ui_story_5068_50680302_6_dialog_content = "Urgh... Perutku... Rasanya sangat sakit...",
  ui_story_5068_50680302_7_dialog_content = "Orang aneh banget sih... Ayo masuk, lah.",
  ui_story_5068_50680302_8_dialog_content = "Kamu di tempat yang tepat. Ini adalah klinik.",
  ui_story_5068_50680302_9_dialog_content = "... Kau seharusnya baik-baik saja sekarang. Pulanglah dan istirahat yang cukup, serta jangan terlalu memaksakan diri bekerja selama dua hari ke depan.",
  ui_story_5068_50680302_10_dialog_content = "Terima kasih, <color=#FFB400>Dokter</color>. Saya merasa jauh lebih baik sekarang. Tapi...",
  ui_story_5068_50680302_11_dialog_content = "Apa itu? Apakah kamu masih merasa sakit?",
  ui_story_5068_50680302_12_dialog_content = "Tidak, tidak, tidak. Keterampilan medis Anda luar biasa, dan saya merasa baik-baik saja sekarang. Hanya saja... tagihan medis...",
  ui_story_5068_50680302_13_dialog_content = "Jangan khawatir jika kamu tidak bisa membayar upahku sekarang. Cukup catat di tagihanmu dan bayar aku nanti seperti biasa.",
  ui_story_5068_50680302_14_dialog_content = "Semua orang di sini saling mengenal, jadi cukup kembali saat Anda sudah punya uangnya.",
  ui_story_5068_50680302_15_dialog_content = "Terima kasih banyak! Saya sangat menghargainya! Saya selalu pakai kredit, dan ini sungguh memalukan...",
  ui_story_5068_50680302_16_dialog_content = "Jangan terlalu stres tentang itu. Tidak pernah baik untuk membiarkan masalah medis tidak diobati, jadi temui saya kapanpun Anda perlu, oke?",
  ui_story_5068_50680302_17_dialog_content = "Yup! Oh... Sepertinya ada pasien baru. Saya tidak akan mengambil lebih banyak waktu Anda, Dokter.",
  ui_story_5068_50680302_18_dialog_content = "(Sumber kabut hitam ini... dokter?)",
  ui_story_5068_50680302_19_dialog_content = "(Rasanya sangat mirip, tapi... ada sesuatu yang terasa sangat berbeda juga. Apa ya itu?)",
  ui_story_5068_50680302_20_dialog_content = "Halo, apa masalahnya?",
  ui_story_5068_50680302_21_dialog_content = "(Jika itu benar-benar dia... apa yang mungkin dia inginkan?)",
  ui_story_5068_50680302_22_dialog_content = "(Apakah dia melakukannya dengan sengaja? Bisakah dia membuat orang sakit agar memiliki lebih banyak pasien?)",
  ui_story_5068_50680302_23_dialog_content = "(Tidak, itu tidak mungkin. Baru saja aku melihat dia mengesampingkan tagihan medis gadis itu untuk sementara, dan sepertinya ini bukan pertama kalinya juga.)",
  ui_story_5068_50680302_24_dialog_content = "Dokter mengajukan pertanyaan kepada kamu, sekarang berhenti menatapnya seperti itu! Biar aku peringatkan, jika kamu melihat sesuatu yang tidak seharusnya, bahkan dia pun tidak bisa memperbaiki apa yang terjadi pada matamu!",
  ui_story_5068_50680302_25_dialog_content = "Cukup, kamu menakut-nakuti pasien kita. Lalu... Apa sebenarnya yang salah dengannya?",
  ui_story_5068_50680302_26_dialog_content = "Tadi dia mengeluh perutnya sakit...",
  ui_story_5068_50680302_27_dialog_content = "Ya... Benar, itu perutku.",
  ui_story_5068_50680302_28_dialog_content = "Itu mengingatkanku, siapa yang memberitahumu tentang klinik itu pada awalnya?",
  ui_story_5068_50680302_29_dialog_content = "Ah... H-Hanya orang asing yang ramah. Dia melihat betapa kesakitan saya, jadi dia memberi tahu saya tentang klinik terdekat dan cara menemukannya.",
  ui_story_5068_50680302_30_dialog_content = "—!",
  ui_story_5068_50680302_31_dialog_content = "...",
  ui_story_5068_50680302_32_dialog_content = "(Eh, ada apa ini? Apakah aku mengatakan sesuatu yang seharusnya tidak kukatakan...?)",
  ui_story_5068_50680302_33_dialog_content = "Uhhhhh... Ugh, ahhhh!",
  ui_story_5068_50680302_34_dialog_content = "Sakit! AHHH! Rasanya aku mati!",
  ui_story_5068_50680302_35_dialog_content = "Ini adalah-",
  ui_story_5068_50680302_36_dialog_content = "Dia baru saja mulai pulih beberapa saat lalu, jadi bagaimana bisa begini? Jika aku tidak segera merawatnya...",
  ui_story_5068_50680302_37_dialog_content = "Aku merasa sangat sakit... Dokter, apakah aku akan mati? Tolong, aku tidak ingin mati...",
  ui_story_5068_50680302_38_dialog_content = "Aaaaaahhh!!!",
  ui_story_5068_50680302_39_dialog_content = "Berhenti memikirkan hal-hal seperti itu! Aku akan merawatmu segera, jadi jangan takut. Semuanya akan baik-baik saja...",
  ui_story_5068_50680302_40_dialog_content = "(Itu—)",
  ui_story_5068_50680302_41_dialog_content = "Hah?",
  ui_story_5068_50680302_42_dialog_content = "Hal-hal hanya masuk ke satu telinga dan keluar dari telinga yang lain untukmu, bukan? Bukankah aku sudah bilang untuk menjaga pandanganmu sendiri?!",
  ui_story_5068_50680302_43_dialog_content = "Maaf! Aku tidak bermaksud melihat!",
  ui_story_5068_50680302_44_dialog_content = "(... Jika tidak salah, dokter ini menggunakan Lumina untuk menyembuhkan pasiennya. Kabut hanya keluar saat dia sedang mengobati mereka.)",
  ui_story_5068_50680302_45_dialog_content = "(Tapi ini berbeda dari yang diberikan Nona Sheol padaku. Kabutnya penuh dengan Lumina, sementara spesimen Nona Sheol sama sekali tidak ada.)",
  ui_story_5068_50680302_46_dialog_content = "(Apakah ini berarti saya salah? Tidak, masih terlalu dini untuk memastikan! Mungkin Lumina hanya ada saat pengobatannya, dan kemudian habis setelah selesai. Setelah itu...)",
  ui_story_5068_50680302_47_dialog_content = "(Tanpa ada Lumina yang tersisa, itu berubah menjadi kabut hitam berbahaya! Kemungkinan dokter tidak tahu cara menanganinya, jadi dia membuangnya secara diam-diam.)",
  ui_story_5068_50680302_48_dialog_content = "(Tapi ini hanya asumsi saya sendiri; apakah benar atau tidak, terserah Lady Sheol untuk mencari tahu. Bisa jadi saya salah besar tentang semua ini.)",
  ui_story_5068_50680302_49_dialog_content = "Kamu baik-baik saja sekarang. Cobalah untuk beristirahat, dan kamu akan sembuh saat bangun nanti.",
  ui_story_5068_50680302_50_dialog_content = "Hmm...",
  ui_story_5068_50680302_51_dialog_content = "Fyuh!",
  ui_story_5068_50680302_52_dialog_content = "(Dia tampak lega melihat pasiennya dalam kondisi stabil. Aku rasa dia tidak berpura-pura juga.)",
  ui_story_5068_50680302_53_dialog_content = "Kamu sudah menangani terlalu banyak pasien hari ini, Dokter. Istirahatlah sejenak, dan saya akan \"mengurus\" pasien terakhir ini.",
  ui_story_5068_50680302_54_dialog_content = "Tak apa, aku bisa mengurusnya. Tapi... kamu mungkin benar tentang terlalu banyak pasien. Kita sudah cukup menerima pasien baru untuk hari ini, jadi tolong tutup pintunya.",
  ui_story_5068_50680302_55_dialog_content = "Tentu.",
  ui_story_5068_50680302_56_dialog_content = "(?!)",
  ui_story_5068_50680302_57_dialog_content = "Asistennya mengatakan bahwa kamu sedang mengalami sakit perut, benar kah itu?",
  ui_story_5068_50680302_58_dialog_content = "Apakah ini penyakit kronis?",
  ui_story_5068_50680302_59_dialog_content = "Hmm…",
  ui_story_5068_50680302_60_dialog_content = "Atau mungkin kamu makan sesuatu yang kurang bersih?",
  ui_story_5068_50680302_61_dialog_content = "Um…",
  ui_story_5068_50680302_62_dialog_content = "Hmm... Sepertinya kamu tidak ingin memberitahu saya, tapi tidak apa-apa...",
  ui_story_5068_50680302_63_dialog_content = "Aku punya banyak obat yang sangat efektif untuk mengatasi sakit perut, terlepas dari penyebabnya.",
  ui_story_5068_50680302_64_dialog_content = "Lihat, 'kan?",
  ui_story_5068_50680302_65_dialog_content = "Dengan hanya satu suntikan, tidak ada rasa sakit yang akan mengganggu Anda lagi. Anda bahkan tidak akan ingat rasa sakit yang pernah Anda rasakan sebelumnya.",
  ui_story_5068_50680302_66_dialog_content = "Tunggu sebentar!",
  ui_story_5068_50680302_67_dialog_content = "Aku... tiba-tiba merasa jauh lebih baik!",
  ui_story_5068_50680302_68_dialog_content = "...",
  ui_story_5068_50680302_69_dialog_content = "M-Maaf mengganggu Anda, Dokter! Saya pasti akan kembali menemui Anda jika rasa sakit saya kembali!",
  ui_story_5068_50680302_70_dialog_content = "Dah—",
  ui_story_5068_50680302_71_dialog_content = "Siapa yang bilang kamu bisa pergi?",
  ui_story_5068_50680302_72_dialog_content = "(Sepertinya kabur bukan pilihan lagi...)",
  ui_story_5068_50680302_73_dialog_content = "Kamu... tidak datang ke sini untuk mencari perawatan, kan?",
  ui_story_5068_50680401_1_dialog_content = "Kamu... tidak datang ke sini untuk mencari perawatan, kan?",
  ui_story_5068_50680401_2_dialog_content = "A-aku melakukannya, sumpah! Hanya saja, tiba-tiba aku merasa jauh lebih baik sekarang!",
  ui_story_5068_50680401_3_dialog_content = "Gila, kan? Mungkin... Mungkin itu hanya sesuatu yang lewat begitu saja?",
  ui_story_5068_50680401_4_dialog_content = "Apakah kamu menganggap kami orang bodoh atau apa? Berhentilah pura-pura!",
  ui_story_5068_50680401_5_dialog_content = "Kamu tipe orang yang harus belajar dengan cara yang sulit, bukan? Aku tidak keberatan memberimu pelajaran, tapi peringatan dulu...",
  ui_story_5068_50680401_6_dialog_content = "Ini mungkin <color=#FFB400>benar-benar</color> menyakitkan!",
  ui_story_5068_50680401_7_dialog_content = "A-Apa yang akan kamu lakukan padaku?!",
  ui_story_5068_50680401_8_dialog_content = "Baiklah... Sudah cukup, kalian berdua.",
  ui_story_5068_50680401_9_dialog_content = "Kamu sepertinya tidak memiliki niat jahat, mengingat kamu tidak mencoba menyerang kami setelah sekian lama... Benar, kan?",
  ui_story_5068_50680401_10_dialog_content = "... Benar!",
  ui_story_5068_50680401_11_dialog_content = "Jangan ini lagi, Dokter.",
  ui_story_5068_50680401_12_dialog_content = "Kamu orang yang berhati lembut sekali. Aku tidak berpikir itu hal yang buruk, kalau tidak, aku tidak akan... Pokoknya, jika kamu terus mempercayai orang lain dengan mudah, maka cepat atau lambat—",
  ui_story_5068_50680401_13_dialog_content = "Aku tahu kamu khawatir tentangku, tapi aku tahu apa yang sedang kulakukan. Percayalah padaku.",
  ui_story_5068_50680401_14_dialog_content = "Lagipula, tempat ini milik kita. Selama kamu ada di sisiku, aku tak perlu khawatir.",
  ui_story_5068_50680401_15_dialog_content = "...",
  ui_story_5068_50680401_16_dialog_content = "Nah, sekarang bisakah Anda memberi tahu kami mengapa Anda berpura-pura sakit?",
  ui_story_5068_50680401_17_dialog_content = "Tapi tadi perutku benar-benar sakit...",
  ui_story_5068_50680401_18_dialog_content = "Ugh, berhenti saja! Kamu sudah mengacaukan penyamaranmu sendiri sejak lama, atau belum menyadarinya?!",
  ui_story_5068_50680401_19_dialog_content = "Apakah akting saya benar-benar seburuk itu...?",
  ui_story_5068_50680401_20_dialog_content = "Tak butuh banyak usaha untuk membuatmu mengakuinya... Kamu pasti orang yang cukup jujur.",
  ui_story_5068_50680401_21_dialog_content = "Jika aktingmu lebih baik, kami akan lebih mencurigai kamu. Sejujurnya, bagian paling mencolok dari aktingmu adalah satu pernyataan saja.",
  ui_story_5068_50680401_22_dialog_content = "Ah... H-Hanya orang asing yang ramah. Dia melihat betapa kesakitan saya, jadi dia memberi tahu saya tentang klinik terdekat dan cara menemukannya.",
  ui_story_5068_50680401_23_dialog_content = "Klinik saya tidak terlalu besar, dan cukup tersembunyi. Selain itu, kami memiliki aturan khusus di sini—",
  ui_story_5068_50680401_24_dialog_content = "Siapa pun yang mengunjungi klinik harus diperkenalkan secara pribadi oleh seseorang yang kami kenal.",
  ui_story_5068_50680401_25_dialog_content = "Semua pasien saya tahu bahwa saya tidak menerima pasien dengan latar belakang yang tidak diketahui, yang berarti mereka tidak akan pernah merekomendasikan saya kepada orang yang tidak dikenal oleh mereka.",
  ui_story_5068_50680401_26_dialog_content = "Begitu kamu mengatakan itu, kami berdua langsung tahu bahwa kamu berbohong pada kami.",
  ui_story_5068_50680401_27_dialog_content = "Oh, begitu…",
  ui_story_5068_50680401_28_dialog_content = "Asisten saya dan saya harus menjaga profil rendah karena alasan yang tidak bisa kami ungkapkan.",
  ui_story_5068_50680401_29_dialog_content = "Aku sudah memberitahumu lebih dari yang diperlukan... Jadi, bisakah kamu memberitahu kami mengapa kamu di sini?",
  ui_story_5068_50680401_30_dialog_content = "Sebenarnya... aku diberi tugas untuk menyelidiki penyakit aneh yang belakangan ini mewabah di Umbraton. Dan penyelidikanku membawaku ke tempat ini.",
  ui_story_5068_50680401_31_dialog_content = "Awalnya saya pikir saya memiliki petunjuk penting, tetapi pada akhirnya saya rasa saya salah orang...",
  ui_story_5068_50680401_32_dialog_content = "...",
  ui_story_5068_50680401_33_dialog_content = "...",
  ui_story_5068_50680401_34_dialog_content = "Masih mengarang cerita, ya?!",
  ui_story_5068_50680401_35_dialog_content = "T-Tidak, sumpah ini yang sebenarnya!",
  ui_story_5068_50680401_36_dialog_content = "Tidak perlu terus membuang waktu Anda pada orang ini, Dokter. Lagipula, dia baru saja melihat metode pengobatan Anda tadi.",
  ui_story_5068_50680401_37_dialog_content = "Apakah... Apakah begitu? Kalau begitu, yang bisa saya katakan adalah maaf.",
  ui_story_5068_50680401_38_dialog_content = "(Oh tidak, sepertinya aku benar-benar dalam masalah sekarang... Apa yang akan mereka lakukan padaku?!)",
  ui_story_5068_50680401_39_option_content = "Force Boost!",
  ui_story_5068_50680401_40_dialog_content = "(Maaf sekali, tapi untuk menjaga <color=#FFB400>Eleanor</color> dan diriku tetap aman, aku tidak punya pilihan lain selain melakukan ini.)",
  ui_story_5068_50680401_41_dialog_content = "(Anda pasti baru saja menerima pekerjaan ini baru-baru ini, kan? Jika begitu, suntikan ini akan membuat Anda melupakan semua yang terjadi dalam sebulan terakhir...)",
  ui_story_5068_50680401_42_dialog_content = "(Begitu kamu tertidur, aku akan menyuruh Eleanor mengantarmu ke tempat yang aman. Seharusnya kamu tidak menginjakkan kaki di klinik ini.)",
  ui_story_5068_50680401_43_dialog_content = "(<color=#FFB400>Rebecca</color> masih terlalu baik hati sebagai orang.)",
  ui_story_5068_50680401_44_dialog_content = "(Saya tahu pria ini tidak baik sejak dia masuk dan mulai mengoceh omong kosong. Kalau terserah saya, saya akan mengusirnya bersama sampah lainnya tanpa berpikir dua kali.)",
  ui_story_5068_50680401_45_dialog_content = "(Wanita Rebecca ini sepertinya tidak ingin menyakitiku, dan asistennya benar-benar mendengarkannya.)",
  ui_story_5068_50680401_46_dialog_content = "(Jika aku tidak pernah mengganggu mereka, mungkin dia tidak perlu melakukan ini padaku. Tapi mungkin... mungkin aku masih punya kesempatan untuk mendapatkan kepercayaannya?)",
  ui_story_5068_50680401_47_dialog_content = "(Saya hanya punya satu kesempatan untuk ini!)",
  ui_story_5068_50680401_48_dialog_content = "Tunggu! Apakah akhir-akhir ini kamu telah menangani banyak pasien dengan gejala misterius?",
  ui_story_5068_50680401_49_dialog_content = "Berhenti mencoba mengulur waktu!",
  ui_story_5068_50680401_50_dialog_content = "... Tidak apa-apa, biarkan dia bicara.",
  ui_story_5068_50680401_51_dialog_content = "Er, baiklah, saya tidak tahu mengapa kalian berdua begitu merahasiakan sesuatu, tetapi saya bisa melihat bahwa Anda benar-benar memikirkan kepentingan pasien Anda, Dokter.",
  ui_story_5068_50680401_52_dialog_content = "Mungkin kita bisa bekerja sama untuk menemukan akar penyebab penyakit-penyakit aneh ini?",
  ui_story_5068_50680401_53_dialog_content = "Hmm... Kamu menyebutkan bahwa pekerjaanmu melibatkan penyelidikan tentang penyakit aneh, kan? Apakah kamu sudah membuat kemajuan lain?",
  ui_story_5068_50680401_54_dialog_content = "Ini saja.",
  ui_story_5068_50680401_X54_dialog_content = "Pernahkah kamu melihat hal seperti ini sebelumnya, Dr. Rebecca? Sebagai dokter, kamu seharusnya lebih tahu tentang ini daripada saya.",
  ui_story_5068_50680401_55_dialog_content = "—!!!",
  ui_story_5068_50680401_56_dialog_content = "A-Apa yang kamu lakukan dengan ini?! Di mana kamu menemukannya?!",
  ui_story_5068_50680401_57_dialog_content = "Tunggu! Bagaimana kamu tahu nama Rebecca?!",
  ui_story_5068_50680401_58_dialog_content = "(Ah! Aku keceplosan!)",
  ui_story_5068_50680401_59_dialog_content = "Muntahkan sebelum aku paksa keluar dari mulutmu!",
  ui_story_5068_50680401_60_dialog_content = "Tunggu, jangan-jangan... kamu ini dari <color=#FFB400>Black Wolves</color>, ya?!",
  ui_story_5068_50680401_61_dialog_content = "Serigala Hitam? Siapa mereka?",
  ui_story_5068_50680401_62_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5068_50680401_63_dialog_content = "Ada yang bilang ini klinik? Tempat sampah seperti ini?",
  ui_story_5068_50680401_64_dialog_content = "Sedikit kumuh, tapi lihat barang-barang di dalamnya; ini memang sebuah klinik!",
  ui_story_5068_50680401_65_dialog_content = "Topeng-topeng itu... Apakah Black Wolves benar-benar di balik semua ini?",
  ui_story_5068_50680401_66_dialog_content = "Jangan coba-coba berbuat lucu! Teman-temanmu di sini sudah memberi tahu kami semuanya!",
  ui_story_5068_50680401_67_dialog_content = "Tunggu, berhenti! Saya sama sekali tidak kenal orang-orang ini! Kami tidak bekerja sama, sumpah!",
  ui_story_5068_50680401_68_dialog_content = "Ck. Dokter! Dokter, cepat keluar! Siapa dokter di sini?",
  ui_story_5068_50680401_69_dialog_content = "Aku dengar dokter di sini bisa mengobati penyakit yang disebabkan oleh kabut hitam. Keluarlah sekarang juga!",
  ui_story_5068_50680401_70_dialog_content = "Tidak ada dokter di sini! Tapi jika kamu mencari alasan untuk menemui salah satu, dengan senang hati aku akan memberikannya padamu!",
  ui_story_5068_50680401_71_dialog_content = "Enyahlah, dasar sampah!",
  ui_story_5068_50680401_72_dialog_content = "Aduh!",
  ui_story_5068_50680401_73_dialog_content = "Kenapa orang gila ini menggigit semua orang yang dilihatnya?! Untungnya aku bereaksi cepat!",
  ui_story_5068_50680401_74_dialog_content = "Berani-beraninya kalian mendekati diam-diam?! Kami bukan sasaran yang mudah! Bunuh mereka, sekarang!",
  ui_story_5068_50680401_75_dialog_content = "Mari kita lihat siapa di antara kita yang akhirnya mati.",
  ui_story_5068_50680401_76_dialog_content = "Ugh!",
  ui_story_5068_50680401_77_dialog_content = "Apa ini?! Gila! Semua orang, siapkan senjatamu! Cepat!!!",
  ui_story_5068_50680401_78_dialog_content = "<color=#e8d9bb>Brak! Brak!</color>",
  ui_story_5068_50680401_79_dialog_content = "Ahhh!",
  ui_story_5068_50680401_80_dialog_content = "Jangan biarkan mereka semua lolos!!!",
  ui_story_5068_50680401_81_dialog_content = "<size=45><color=#e8d9bb>Duk! Duk! Duk!</color></size>",
  ui_story_5068_50680401_82_dialog_content = "(Apa yang terjadi di sini... Bagaimana bisa semuanya jadi seperti ini?!)",
  ui_story_5068_50680401_83_dialog_content = "(Pintunya benar-benar terhalang. Aku tak bisa keluar meskipun aku ingin...)",
  ui_story_5068_50680401_84_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  ui_story_5068_50680401_85_dialog_content = "Ayo! Angkat teleponnya, Nona Sheol!!",
  ui_story_5068_50680502_1_dialog_content = "Kumpulan orang bodoh! Orang ini bersama kalian, bukan? Jika kalian tidak ingin ada yang terjadi padanya—",
  ui_story_5068_50680502_2_dialog_content = "Aku sudah bilang kita tidak bekerja sama...",
  ui_story_5068_50680502_3_dialog_content = "Apakah wanita ini kehilangan akal? Dia memilih pria acak dan mengklaim dia adalah salah satu Serigala Hitam kami. Apakah ada di antara kalian yang mengenal pria ini?",
  ui_story_5068_50680502_4_dialog_content = "Tidak. Apakah kamu mengenalnya?",
  ui_story_5068_50680502_5_dialog_content = "Kebetulan sekali; aku juga tidak mengenalnya.",
  ui_story_5068_50680502_6_dialog_content = "Hahahahaha!",
  ui_story_5068_50680502_7_dialog_content = "Itulah yang selama ini kucoba katakan! Kenapa kamu tidak mau percaya padaku?!",
  ui_story_5068_50680502_8_dialog_content = "Menahan saya sebagai sandera tidak akan menguntungkan kalian berdua, jadi bisakah kalian tolong lepaskan pisau dari leherku? Aku benar-benar bisa terluka...",
  ui_story_5068_50680502_9_dialog_content = "Diam! Meskipun kamu bukan sekutu dengan orang-orang ini, kamu tetap sampah di mataku!",
  ui_story_5068_50680502_10_dialog_content = "Biarkan dia pergi. Kita tidak ingin ada orang yang tidak bersalah terluka.",
  ui_story_5068_50680502_11_dialog_content = "Tidak bersalah adalah kata terakhir yang akan saya gunakan untuk menggambarkan orang ini.",
  ui_story_5068_50680502_12_dialog_content = "Tapi jika dokter juga mengatakan itu... Maka anggaplah ini hari keberuntunganmu.",
  ui_story_5068_50680502_13_dialog_content = "Biarkan saya jelaskan! Siapa pun yang berurusan dengan Serigala Hitam, pasti akan berakhir buruk!",
  ui_story_5068_50680502_14_dialog_content = "Tahu tidak, kami sebenarnya berpikir untuk mengambil alih seluruh lingkungan ini secara damai. Tapi sekarang, sepertinya menghancurkannya menjadi pilihan yang lebih baik!",
  ui_story_5068_50680502_15_dialog_content = "...",
  ui_story_5068_50680502_16_dialog_content = "Jadi, sebenarnya kalian orang bodoh ini sedang apa di sini?",
  ui_story_5068_50680502_17_dialog_content = "Tunggu sebentar! Aku kenal kamu! Kamu itu—",
  ui_story_5068_50680502_18_dialog_content = "Kamu Eleanor!",
  ui_story_5068_50680502_19_dialog_content = "...",
  ui_story_5068_50680502_20_dialog_content = "Benar! Sekarang aku ingat! Aku kenal kamu!",
  ui_story_5068_50680502_21_dialog_content = "Hah? El... apa? Tidak mengingatkan sama sekali.",
  ui_story_5068_50680502_22_dialog_content = "Eleanor! Maksudku—",
  ui_story_5068_50680502_23_dialog_content = "Eh…",
  ui_story_5068_50680502_24_dialog_content = "Aku benar-benar minta maaf...",
  ui_story_5068_50680502_25_dialog_content = "Tapi jika ini terus berlanjut, kau hanya akan membuat lebih banyak masalah bagi kita... Kau tidak memberiku pilihan lain...",
  ui_story_5068_50680502_26_dialog_content = "Uhh...",
  ui_story_5068_50680502_27_dialog_content = "Santai saja, aku janji tidak akan terlalu sakit...",
  ui_story_5068_50680502_28_dialog_content = "Apa!? Apa yang kaulakukan padanya?!",
  ui_story_5068_50680502_29_dialog_content = "Jangan khawatir, saya tidak berniat mengambil nyawa siapa pun.",
  ui_story_5068_50680502_30_dialog_content = "Seperti yang bisa kamu lihat, aku baru saja membuatnya pingsan.",
  ui_story_5068_50680502_31_dialog_content = "Ini, wanita ini, dia gila... Mundur... Bergerak, bergerak!",
  ui_story_5068_50680502_32_dialog_content = "Kembali dan laporkan kepada bos! Biarkan atasan—",
  ui_story_5068_50680502_33_dialog_content = "Ugh!!!",
  ui_story_5068_50680502_34_dialog_content = "Maaf, tapi saya tidak bisa membiarkan satu pun dari kalian melarikan diri.",
  ui_story_5068_50680502_35_dialog_content = "Jika salah satu dari kalian berhasil pergi dengan kenangan yang utuh... Ini akan menimbulkan lebih banyak masalah bagi saya.",
  ui_story_5068_50680502_36_dialog_content = "Maaf, Nona Rebecca. Sepertinya pria itu mengenaliku dari masa-masa pengembaraanku...",
  ui_story_5068_50680502_37_dialog_content = "Tak apa, Eleanor, aku tahu hari ini pasti akan tiba suatu saat nanti. Hanya masalah waktu saja.",
  ui_story_5068_50680502_38_dialog_content = "(Hanya butuh satu serangan saja...)",
  ui_story_5068_50680502_39_dialog_content = "(Tampaknya Rebecca tidak bertarung dengan kekuatan penuh melawan Serigala Hitam itu.)",
  ui_story_5068_50680502_40_dialog_content = "(Dia terlihat begitu lemah, tapi sebenarnya sangat kuat... Saya tidak berpikir dia hanya dokter biasa.)",
  ui_story_5068_50680502_41_dialog_content = "Untuk kamu, tenang saja karena aku tidak berniat melakukan hal yang sama padamu... Setidaknya tidak sekarang.",
  ui_story_5068_50680502_42_dialog_content = "Kamu juga tak perlu khawatir tentang orang-orang ini.",
  ui_story_5068_50680502_43_dialog_content = "Ingat suntikan yang akan saya berikan kepada Anda sebelumnya? Sebenarnya, itu bukan obat yang sebenarnya.",
  ui_story_5068_50680502_44_dialog_content = "Nona Rebecca? Tidakkah menurutmu kamu memberitahunya terlalu banyak?",
  ui_story_5068_50680502_45_dialog_content = "Jangan khawatir. Aku tahu apa yang sedang kulakukan.",
  ui_story_5068_50680502_46_dialog_content = "Serum dalam suntikan ini bukan obat, tetapi <color=#FFB400>racun</color>... Jenis yang sama yang baru saja saya berikan kepada orang-orang ini.",
  ui_story_5068_50680502_47_dialog_content = "Racun?!",
  ui_story_5068_50680502_48_dialog_content = "Ya, racun... Tapi tidak mematikan.",
  ui_story_5068_50680502_49_dialog_content = "Orang-orang ini... hanya tak sadarkan diri, tidak lebih.",
  ui_story_5068_50680502_50_dialog_content = "Ketika penjahat-penjahat ini bangun, mereka akan lupa siapa mereka dan apa yang sedang mereka lakukan!",
  ui_story_5068_50680502_51_dialog_content = "Maaf, anak kecil... Apakah kami menakuti kamu tadi?",
  ui_story_5068_50680502_52_dialog_content = "Aku tidak takut sama sekali!",
  ui_story_5068_50680502_53_dialog_content = "Lalu, apakah kamu merasa lebih baik?",
  ui_story_5068_50680502_54_dialog_content = "Aku merasa jauh lebih baik sekarang! Terima kasih, Dokter!",
  ui_story_5068_50680502_55_dialog_content = "Bagus... Sepertinya kamu baik-baik saja, yang berarti kamu bisa pulang sekarang.",
  ui_story_5068_50680502_56_dialog_content = "Klinik ini tidak terlalu aman saat ini, jadi tolong beri tahu semua orang untuk menjauh untuk sementara waktu.",
  ui_story_5068_50680502_57_dialog_content = "Dan ingat untuk merahasiakan semua yang terjadi di sini, mengerti?",
  ui_story_5068_50680502_58_dialog_content = "Mengerti! Siap laksanakan!",
  ui_story_5068_50680502_59_dialog_content = "Maka aku akan kembali dulu! Selamat tinggal, Dokter! Selamat tinggal, Nona Asisten!",
  ui_story_5068_50680502_60_dialog_content = "Eleanor... Bisakah kamu segera singkirkan orang-orang ini?",
  ui_story_5068_50680502_61_dialog_content = "—!",
  ui_story_5068_50680502_62_dialog_content = "Tolong jangan salah paham. Saya hanya ingin dia membawa mereka ke tempat yang aman dan jauh dari sini.",
  ui_story_5068_50680502_63_dialog_content = "Kenapa kau memberitahu semua ini padanya, Nona Rebecca? Cukup kalahkan dia saja agar aku bisa menyingkirkannya bersama yang lain!",
  ui_story_5068_50680502_64_dialog_content = "Saya telah berubah pikiran.",
  ui_story_5068_50680502_65_dialog_content = "... Aku tak mengerti.",
  ui_story_5068_50680502_66_dialog_content = "Aku gagal menyadarinya tadi... Mungkin karena kita bersembunyi di klinik kecil ini selama setahun terakhir?",
  ui_story_5068_50680502_67_dialog_content = "Permukiman kumuh dan klinik ini... Mereka memberi kita perlindungan, tapi juga menyempitkan pandangan kita sedikit.",
  ui_story_5068_50680502_68_dialog_content = "Aku tak menyangka masih ada Caelestite di dunia ini.",
  ui_story_5068_50680502_69_dialog_content = "...",
  ui_story_5068_50680502_70_dialog_content = "Caelestites? Apa itu?",
  ui_story_5068_50680502_71_dialog_content = "Kamu tidak menyadari? Seperti, ada sesuatu yang terasa tidak biasa saat kamu sedang bertarung?",
  ui_story_5068_50680502_72_dialog_content = "Kurasa memang rasanya sedikit berbeda...",
  ui_story_5068_50680502_73_dialog_content = "Rasanya seperti... seperti aku bisa melihat berbagai pola Lumina di sekelilingku! Ini membuat pertarungan menjadi lebih lancar dari biasanya!",
  ui_story_5068_50680502_74_dialog_content = "Lalu sepertinya itu bukan hanya imajinasiku.",
  ui_story_5068_50680502_75_dialog_content = "Dan jika dugaanku benar... Maka itu membuat kamu seorang Caelestite, bukan?",
  ui_story_5068_50680502_76_dialog_content = "Hanya Caelestite legendaris yang mampu menggunakan teknik khusus ini untuk membantu kita dalam pertempuran.",
  ui_story_5068_50680502_77_dialog_content = "Kamu tanpa sengaja menyebut namaku tadi, yang mungkin kamu ketahui melalui kemampuan yang sama, bukan?",
  ui_story_5068_50680502_78_dialog_content = "Sepertinya kamu tahu banyak tentang Caelestites.",
  ui_story_5068_50680502_79_dialog_content = "Hanya dari apa yang telah saya baca di buku tentang masa lalu. Saya sempat berpikir bahwa Caelestite itu semua...",
  ui_story_5068_50680502_80_dialog_content = "Maaf, aku hanya... tidak pernah menyangka akan bertemu Caelestite seperti ini.",
  ui_story_5068_50680502_81_dialog_content = "Nah, kamu benar. Namaku PlayerName, dan aku memang seorang Caelestite. Lalu, siapa kalian berdua?",
  ui_story_5068_50680502_82_dialog_content = "Hanya seorang <color=#FFB400>dokter tanpa nama</color> dan <color=#FFB400>asisten tanpa nama</color>-nya. Itu saja yang perlu kamu ketahui!",
  ui_story_5068_50680502_83_dialog_content = "Eleanor... PlayerName cukup baik untuk memperkenalkan dirinya, jadi kita harus melakukan hal yang sama untuknya.",
  ui_story_5068_50680502_84_dialog_content = "Nona Rebecca?!",
  ui_story_5068_50680502_85_dialog_content = "Itu namaku—Rebecca Svanedona. Dan ini Eleanor.",
  ui_story_5068_50680502_86_dialog_content = "Untuk beberapa alasan... Kami harus merahasiakan nama-nama kami.",
  ui_story_5068_50680502_87_dialog_content = "Namun, kamu bersedia untuk membagikannya denganku.",
  ui_story_5068_50680502_88_dialog_content = "Itu karena aku percaya kamu tidak bermaksud menyakiti kami.",
  ui_story_5068_50680502_89_dialog_content = "Dalam buku-buku yang saya baca, kaum Caelestite selalu digambarkan sebagai ras yang baik hati dan cinta damai...",
  ui_story_5068_50680502_90_dialog_content = "Juga... Kamu tampaknya tidak memiliki kemampuan bertarung, jadi jika kamu bertindak melawan kami, saya tidak akan kesulitan menaklukkanmu. Benar bukan?",
  ui_story_5068_50680502_91_dialog_content = "(Meskipun nadanya lembut, tidak ada sedikit pun belas kasihan dalam kata-katanya... Meskipun dia sudah memberitahu namanya, dia tetap sama jauhnya seperti sebelumnya.)",
  ui_story_5068_50680502_92_dialog_content = "Jadi orang ini lebih lemah dari yang terlihat? Bagus, itu satu hal yang lebih sedikit untuk dikhawatirkan.",
  ui_story_5068_50680502_93_dialog_content = "Aku pergi untuk membersihkan sampah yang berserakan di lantai kita.",
  ui_story_5068_50680502_94_dialog_content = "Berdasarkan apa yang mereka katakan sebelumnya, tempat ini tidak aman lagi. Mungkin saja...",
  ui_story_5068_50680502_95_dialog_content = "Bahwa kita harus meninggalkan tempat ini... Dan seluruh Umbraton juga.",
  ui_story_5068_50680502_96_dialog_content = "Kalau sampai pada titik itu—",
  ui_story_5068_50680502_97_dialog_content = "Jangan khawatir... Aku akan membuat rencana untuk skenario terburuk.",
  ui_story_5068_50680502_98_dialog_content = "Juga, kamu harus tinggal di ruang tersembunyi sampai aku kembali.",
  ui_story_5068_50680502_99_dialog_content = "Jangan biarkan siapa pun masuk selama aku pergi.",
  ui_story_5068_50680601_1_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5068_50680601_2_dialog_content = "... Baiklah, itu seharusnya yang terakhir dari mereka.",
  ui_story_5068_50680601_3_dialog_content = "*Wusss...*",
  ui_story_5068_50680601_4_dialog_content = "Hmm? Sudah bangun, ya?",
  ui_story_5068_50680601_5_dialog_content = "Kau... apa yang sedang kau lakukan?!",
  ui_story_5068_50680601_6_dialog_content = "Hah? Di mana tempat sampah ini? Teman-teman, bangun!",
  ui_story_5068_50680601_7_dialog_content = "…Hah?",
  ui_story_5068_50680601_8_dialog_content = "Apa... apa yang terjadi?!",
  ui_story_5068_50680601_9_dialog_content = "Semua orang, bangun! Hei, hei! Bangun sekarang!",
  ui_story_5068_50680601_10_dialog_content = "Kepalaku... terasa berputar. Kenapa aku tidak bisa mengingat apa-apa?",
  ui_story_5068_50680601_11_dialog_content = "... Orang ini di depan kita pasti tahu sesuatu.",
  ui_story_5068_50680601_12_dialog_content = "Bicara! Kenapa kamu menyelinap di sekitar kami tadi? Siapa dalang di balik ini?!",
  ui_story_5068_50680601_13_dialog_content = "Hah? Bagaimana mereka semua bisa bangun begitu cepat?",
  ui_story_5068_50680601_14_dialog_content = "Apakah Nona Rebecca memberi mereka dosis yang lebih rendah untuk menghindari efek samping jangka panjang? Seperti yang selalu saya katakan, dia orang yang terlalu baik...",
  ui_story_5068_50680601_15_dialog_content = "Apa yang dia gumamkan pada dirinya sendiri saat sendirian?",
  ui_story_5068_50680601_16_dialog_content = "Siapa peduli? Ayo tangkap dia!",
  ui_story_5068_50680601_17_dialog_content = "Hmph. Sayangnya, aku tidak selemah dokter itu, lho!",
  ui_story_5068_50680602_1_dialog_content = "—?!",
  ui_story_5068_50680602_2_dialog_content = "Aku bukan dokter, jadi maafkan jika dosisnya salah.",
  ui_story_5068_50680602_3_dialog_content = "Tapi aku janji, suntikan ini akan membuatmu melupakan segalanya dan menjalani kehidupan baru. Mimpi indah, kamu sampah.",
  ui_story_5068_50680602_4_dialog_content = "Hah?!",
  ui_story_5068_50680602_5_dialog_content = "Kamu yang terakhir.",
  ui_story_5068_50680602_6_dialog_content = "Tolong... Tolong biarkan aku pergi...",
  ui_story_5068_50680602_7_dialog_content = "Hah? Tunggu sebentar...",
  ui_story_5068_50680602_8_dialog_content = "Eleanor?",
  ui_story_5068_50680602_9_dialog_content = "Eleanor, itu kamu, kan?! Jangan, jangan berikan aku suntikan itu! Aku tahu aku akan mati jika kamu melakukannya!",
  ui_story_5068_50680602_10_dialog_content = "Ini bukan terserah kamu.",
  ui_story_5068_50680602_11_dialog_content = "Jangan! Aku memohon padamu, Eleanor! Demi masa lalu, tolong selamatkan temanmu!",
  ui_story_5068_50680602_12_dialog_content = "Aku sudah menjagamu dengan baik selama <color=#FFB400>bertahun-tahun</color> itu!",
  ui_story_5068_50680602_13_dialog_content = "Kamu tahu aturannya, jadi cukup jawab beberapa pertanyaan dari saya.",
  ui_story_5068_50680602_14_dialog_content = "Tentu saja! Apapun yang kamu inginkan! Janji akan membiarkan saya pergi, dan aku akan memberitahumu semua yang aku tahu!",
  ui_story_5068_50680602_15_dialog_content = "Untuk apa kamu dikirim keluar?",
  ui_story_5068_50680602_16_dialog_content = "... Apa yang harus saya lakukan hari ini? Saya...",
  ui_story_5068_50680602_17_dialog_content = "Tidak ingat, ya?",
  ui_story_5068_50680602_18_dialog_content = "N-Tidak, bukan itu! Beri aku waktu sebentar! Tidak, tiga puluh detik saja!",
  ui_story_5068_50680602_19_dialog_content = "... Aku ingat! Akhirnya aku ingat sekarang!",
  ui_story_5068_50680602_20_dialog_content = "Kami... Kami dikirim kesini untuk menguji sebuah yang baru dikembangkan...",
  ui_story_5068_50680602_21_dialog_content = "...",
  ui_story_5068_50680602_22_dialog_content = "Jika kamu tidak bisa memberitahuku, aku tidak akan memaksanya.",
  ui_story_5068_50680602_23_dialog_content = "Itu <color=#FFB400>kabut hitam</color>.",
  ui_story_5068_50680602_24_dialog_content = "Kami... Kami dikirim ke sini untuk menguji efek dari kabut hitam yang baru dikembangkan, dan juga...",
  ui_story_5068_50680602_25_dialog_content = "Untuk melacak dokter yang dapat mengobati efeknya—Sepertinya, <color=#FFB400>Direktur</color> sangat tertarik pada orang ini...",
  ui_story_5068_50680602_26_dialog_content = "Tes? Dari jenis kabut hitam baru?!",
  ui_story_5068_50680602_27_dialog_content = "Ya... Dan saat itulah kami mendengar tentang seorang dokter bawah tanah yang mencurigakan. Bahkan, saya cukup yakin kami sedang dalam perjalanan untuk mencari dokter itu... Jadi, apa yang kita lakukan di sini?",
  ui_story_5068_50680602_28_dialog_content = "Tunggu!",
  ui_story_5068_50680602_29_dialog_content = "Apa yang kamu lakukan di sini juga? Dan apa yang kamu—",
  ui_story_5068_50680602_30_dialog_content = "Maaf... Kakak.",
  ui_story_5068_50680602_31_dialog_content = "Kamu sekarang ingat terlalu banyak.",
  ui_story_5068_50680602_32_dialog_content = "<color=#e8d9bb>Gemerisik, gemerisik...</color>",
  ui_story_5068_50680602_33_dialog_content = "Hoot—Hoot—",
  ui_story_5068_50680701_1_dialog_content = "<color=#e8d9bb>Ketuk-tip... Ketuk-tip...</color>",
  ui_story_5068_50680701_2_dialog_content = "Silakan tunggu sebentar.",
  ui_story_5068_50680701_3_dialog_content = "<color=#e8d9bb>Klik, klik.</color>",
  ui_story_5068_50680701_4_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5068_50680701_5_dialog_content = "Di sana. Jika kamu ingin tahu lebih banyak tentang kabut hitam, silakan ikut denganku.",
  ui_story_5068_50680701_6_dialog_content = "Tapi sebelumnya, aku harus meminta... Agar kamu merahasiakan semua yang kamu lihat dan dengar di ruangan tersembunyi ini.",
  ui_story_5068_50680701_7_dialog_content = "Tentu saja, aku janji.",
  ui_story_5068_50680701_8_dialog_content = "Tolong perhatikan langkahmu...",
  ui_story_5068_50680701_9_dialog_content = "Kita sudah sampai.",
  ui_story_5068_50680701_10_dialog_content = "—!!",
  ui_story_5068_50680701_11_dialog_content = "Di sana... Ada begitu banyak guci dan botol di sini!",
  ui_story_5068_50680701_12_dialog_content = "Saya telah mengumpulkan mereka sejak lama tanpa menyadarinya. Sebelum saya sadari, ruangan itu penuh dengan spesimen.",
  ui_story_5068_50680701_13_dialog_content = "Jangan bilang ini semua...",
  ui_story_5068_50680701_14_dialog_content = "Beberapa ada dan beberapa tidak. Bahkan ada sejumlah di antaranya yang memiliki efek yang sama sekali berbeda.",
  ui_story_5068_50680701_15_dialog_content = "Botol-botol dan toples ini berisi hasil penelitianku. Dengan menggunakan kekuatanku pada <color=#FFB400>berbagai jenis Lumina</color>, aku dapat menghasilkan berbagai macam serum dengan beragam efek.",
  ui_story_5068_50680701_16_dialog_content = "<color=#FFB400>Berbagai jenis Lumina</color>?",
  ui_story_5068_50680701_17_dialog_content = "Seperti yang mungkin Anda ketahui sekarang, klinik ini beroperasi di daerah kumuh—Tidak semua orang yang datang ke sini dapat membayar pengobatan atau obat mereka dengan uang.",
  ui_story_5068_50680701_18_dialog_content = "Jadi, untuk pasien-pasien yang memiliki Lumina kuat dan dompet kosong, saya menawarkan opsi untuk membayar layanan saya dengan Lumina mereka.",
  ui_story_5068_50680701_19_dialog_content = "Apakah Anda familiar dengan situasi seperti ini? Ketika berbicara tentang penelitian, tidak ada yang lebih penting daripada memiliki cukup spesimen dan bahan yang tersedia.",
  ui_story_5068_50680701_20_dialog_content = "Jangan khawatir, saya tidak pernah memaksa siapa pun untuk mematuhi pekerjaan saya. Tolong percayai saya ketika saya mengatakan bahwa semua Lumina ini diberikan dengan sukarela oleh pasien saya atau anggota keluarga mereka.",
  ui_story_5068_50680701_21_dialog_content = "Lumina yang saya kumpulkan setiap kali juga sangat kecil, dan tidak akan menimbulkan efek negatif jangka panjang bagi Aurorian.",
  ui_story_5068_50680701_22_dialog_content = "Tapi sebenarnya apa yang sedang kamu teliti sehingga memerlukan Lumina sebanyak itu?",
  ui_story_5068_50680701_23_dialog_content = "Kalau untuk membuat dan menjual lebih banyak barang seperti racun kehilangan ingatan itu... Aku tidak bisa tidak merasa khawatir tentang ini.",
  ui_story_5068_50680701_24_dialog_content = "Aku minta maaf telah memberimu kesan seperti itu. Kamu pasti berpikir... bahwa aku sedang melakukan sesuatu yang buruk, 'kan?",
  ui_story_5068_50680701_25_dialog_content = "Yang saya tahu adalah bahwa Anda adalah dokter yang baik setiap kali Anda bersama pasien Anda. Tidak bisa dipungkiri itu.",
  ui_story_5068_50680701_26_dialog_content = "Tapi aku masih penasaran untuk mengetahui tujuan dari \"penelitian\" mu.",
  ui_story_5068_50680701_27_dialog_content = "Tujuan dari penelitian saya...",
  ui_story_5068_50680701_28_dialog_content = "Sebagai seorang Caelestite, kamu seharusnya bisa menggunakan kekuatan khususmu untuk membaca pikiranku, bukan?",
  ui_story_5068_50680701_29_dialog_content = "\"Kekuatan khusus\" saya sebenarnya adalah jenis kemampuan psikis. Saya hanya bisa menggunakannya dalam keadaan berbahaya.",
  ui_story_5068_50680701_30_dialog_content = "Kemampuan psikis... Saya mengerti. Apakah mereka bisa digunakan untuk hal lain? Seperti melumpuhkan orang lain, misalnya?",
  ui_story_5068_50680701_31_dialog_content = "Tidak seperti itu, tidak. Selain membiarkan saya mengemudikan Colossus dan mengarahkan yang lain dalam pertempuran... Mereka benar-benar tidak bisa digunakan untuk hal lain.",
  ui_story_5068_50680701_32_dialog_content = "Colossus-mu? Ya, saya ingat sesuatu tentang Caelestites memiliki kendaraan dengan nama itu.",
  ui_story_5068_50680701_33_dialog_content = "Soroz bukan hanya kendaraan; dia adalah teman terdekat dan paling penting bagi saya.",
  ui_story_5068_50680701_34_dialog_content = "\"Soroz\"? Apakah itu yang kamu sebut Colossus-mu? Nama yang terdengar mengesankan...",
  ui_story_5068_50680701_35_dialog_content = "Jika kamu punya waktu, aku ingin memperkenalkanmu ke Soroz suatu hari nanti. Banyak teman kami yang suka datang ke sini untuk bersantai bersama.",
  ui_story_5068_50680701_36_dialog_content = "Oh... Mungkin suatu hari nanti, pasti...",
  ui_story_5068_50680701_37_dialog_content = "Terima kasih telah berbagi banyak tentang dirimu dan kaum Caelestite... Kurasa aku juga harus berbagi beberapa rahasia tentang diriku.",
  ui_story_5068_50680701_38_dialog_content = "Untuk permulaan, kabut hitam.",
  ui_story_5068_50680701_39_dialog_content = "Kabut hitam ini... adalah keluargaku.",
  ui_story_5068_50680701_40_dialog_content = "... Keluargamu?",
  ui_story_5068_50680701_41_dialog_content = "Maksud kamu, kamu menggunakan Lumina keluargamu untuk membuatnya...?",
  ui_story_5068_50680701_42_dialog_content = "Tidak. Kabut hitam ini adalah metode unik <color=#FFB400>Keluarga Svanedona</color> untuk... Eksis.",
  ui_story_5068_50680701_43_dialog_content = "Mungkin kamu belum tahu, tetapi hingga setahun yang lalu, Keluarga Svanedona merupakan salah satu keluarga paling terkemuka dan kaya di seluruh Umbraton.",
  ui_story_5068_50680701_44_dialog_content = "Keluarga ini memiliki kemampuan unik yang diwariskan dari generasi ke generasi: kekuatan untuk membuat <color=#FFB400>serum</color> penyembuhan dengan Lumina mereka.",
  ui_story_5068_50680701_45_dialog_content = "Dan kebetulan saya adalah salah satu anggota mereka.",
  ui_story_5068_50680701_46_dialog_content = "Selain membuat serum medis, saya juga mampu memproduksi jenis <color=#FFB400>racun</color> yang sangat berbahaya. Apakah itu gen resesif atau hadiah dari yang ilahi, siapa yang tahu, meskipun keluarga saya lebih menyukai penjelasan yang terakhir.",
  ui_story_5068_50680701_47_dialog_content = "Di masa lalu, saya sama sekali tidak tahu tentang kegunaan racun ini atau implikasinya. Bagaimanapun, saya selalu lebih suka menggunakan kekuatan saya untuk menyembuhkan orang, tetapi kemudian...",
  ui_story_5068_50680701_48_dialog_content = "...",
  ui_story_5068_50680701_49_dialog_content = "Apa yang terjadi? Di mana saya?",
  ui_story_5068_50680701_50_dialog_content = "Rebecca? Rebecca! Apakah kamu di sana?",
  ui_story_5068_50680701_51_dialog_content = "Aku di sini, PlayerName. Tolong jangan takut, aku hanya menggunakan kabut untuk merekam kembali kenangan dari hari itu...",
  ui_story_5068_50680701_52_dialog_content = "Lihat...",
  ui_story_5068_50680701_53_dialog_content = "Orang yang ada di lantai itu adalah Paman Albertku. Dia sangat suka memelukku saat aku kecil, tapi aku tidak tahan dengan rasa gatal dari jenggotnya.",
  ui_story_5068_50680701_54_dialog_content = "Gadis kecil yang duduk di sana adalah sepupuku Jessica. Dia selalu menjadi gadis yang imut; aku ingat dia selalu membawa boneka ke mana pun dia pergi, dan boneka itu sama imutnya dengan dia. Kakak perempuanku Isa juga sangat menyayanginya.",
  ui_story_5068_50680701_55_dialog_content = "Isa... saudariku juga suka membelikan aku barang-barang mahal, meskipun sebenarnya aku tidak memerlukan kebanyakan dari mereka. Hari itu, aku bahkan tidak sempat melihat wajahnya untuk terakhir kalinya.",
  ui_story_5068_50680701_56_dialog_content = "Dan di sana... adalah ibuku Lillian. Aku sangat merindukannya. Semur yang dia buat, kehangatan pelukannya, dan senyum di wajahnya saat dia bilang dia mencintaiku.",
  ui_story_5068_50680701_57_dialog_content = "Tapi sekarang mereka bukan lagi bagian dari dunia ini.",
  ui_story_5068_50680701_58_dialog_content = "Jika Eleanor tidak menyelamatkanku saat itu, mungkin aku akan berubah menjadi kabut hitam seperti mereka.",
  ui_story_5068_50680701_59_dialog_content = "Kabut hitam itu... Tapi bukankah kamu bilang itu adalah bentuk eksistensi unik mereka?",
  ui_story_5068_50680701_60_dialog_content = "Benar. Ketika anggota Keluarga Svanedona meninggal dan Lumina benar-benar meninggalkan tubuh mereka, serum penyembuhan yang mereka hasilkan berubah menjadi zat beracun.",
  ui_story_5068_50680701_61_dialog_content = "Dan jika racun itu bersentuhan dengan api yang cukup panas...",
  ui_story_5068_50680701_62_dialog_content = "Menjadi kabut hitam yang dapat menutupi langit.",
  ui_story_5068_50680701_63_dialog_content = "Kadang-kadang aku bertanya-tanya mengapa aku terlahir dengan kemampuan untuk menghasilkan racun ini...",
  ui_story_5068_50680701_64_dialog_content = "Ketika keluargaku diserang oleh <color=#FFB400>Srigala Hitam</color>, dengan sangat menyakitkan aku menyadari betapa lemahnya kekuatanku untuk melindungi mereka.",
  ui_story_5068_50680701_65_dialog_content = "Itu adalah momen terendah dan paling putus asa dalam hidup saya.",
  ui_story_5068_50680701_66_dialog_content = "Jadi, kalian berdua selama ini bersembunyi dari Serigala Hitam, ya...",
  ui_story_5068_50680701_67_dialog_content = "Izinkan saya menjawab pertanyaan sebelumnya. Selama setahun terakhir, saya telah meneliti cara menggunakan racun saya dengan benar...",
  ui_story_5068_50680701_68_dialog_content = "Saya hanya punya satu tujuan: melindungi orang yang saya sayangi.",
  ui_story_5068_50680701_69_dialog_content = "Dan itu adalah Eleanor, ya?",
  ui_story_5068_50680701_70_dialog_content = "Ya... Dia adalah satu-satunya yang tersisa untukku sekarang.",
  ui_story_5068_50680701_71_dialog_content = "Tapi, kabut hitam di tanganmu itu...",
  ui_story_5068_50680701_72_dialog_content = "Saya yakin itu dibuat oleh anggota Keluarga Svanedona yang mengalami ajal mendadak. Lebih lagi, itu dibuat baru-baru ini saja!",
  ui_story_5068_50680701_73_dialog_content = "Dengan kata lain...",
  ui_story_5068_50680701_74_dialog_content = "Aku punya usulan untukmu, PlayerName...",
  ui_story_5068_50680701_75_dialog_content = "Aku tahu apa yang kamu pikirkan. Ada kemungkinan beberapa anggota keluargamu selamat dari serangan tahun lalu, dan saat ini Black Wolves sedang memanfaatkannya...",
  ui_story_5068_50680701_76_dialog_content = "Sepertinya penyelidikan saya akhirnya membuat kemajuan.",
  ui_story_5068_50680701_77_dialog_content = "Jangan khawatir, meskipun tugas saya adalah menyelidiki kabut hitam, saya pasti akan membantu kamu mencari tanda-tanda keberadaan keluargamu.",
  ui_story_5068_50680701_78_dialog_content = "Terima kasih, PlayerName...",
  ui_story_5068_50680801_1_dialog_content = "Hoot—Hoot—",
  ui_story_5068_50680801_2_dialog_content = "Teliti area di mana Tim B melakukan percobaan mereka! Kehilangan mereka bukanlah kecelakaan!",
  ui_story_5068_50680801_3_dialog_content = "Jangan lewatkan satu batu pun! Tak ada yang beristirahat sampai kita berhasil menemukan pelaku di balik ini!",
  ui_story_5068_50680801_4_dialog_content = "Ya, Direktur!",
  ui_story_5068_50680801_5_dialog_content = "Apakah itu kamu, Rebecca? Bahkan setelah setahun... Apakah kamu masih mengintai di Umbraton? Apakah kamu benar-benar berpikir bisa meremehkanku seperti ini? Atau mungkin...",
  ui_story_5068_50680801_6_dialog_content = "Hmm?",
  ui_story_5068_50680801_7_dialog_content = "<color=#e8d9bb>Ketuk-tip... Ketuk-tip...</color>",
  ui_story_5068_50680801_8_dialog_content = "Tiga... tidak, lima dari mereka... Mungkin bahkan lebih. Mereka terus mengikutiku, dan aku tidak bisa mengusir mereka.",
  ui_story_5068_50680801_9_dialog_content = "Sepertinya salah satu badut itu berhasil memanggil bala bantuan setelah semua...",
  ui_story_5068_50680801_10_dialog_content = "Maju sini, pengecut! Keluar dan bertarung!",
  ui_story_5068_50680802_1_dialog_content = "Tunggu... Berhenti! Hentikan, kalian semua!",
  ui_story_5068_50680802_2_dialog_content = "Kamu pikir aku akan berhenti hanya karena kamu minta?!",
  ui_story_5068_50680802_3_dialog_content = "Buka matamu, Eleanor! Ini aku—Isa! Jangan bilang kamu lupa tentang aku?!",
  ui_story_5068_50680802_4_dialog_content = "Isa...?",
  ui_story_5068_50680802_5_dialog_content = "Kamu... Kamu masih hidup?!",
  ui_story_5068_50680802_6_dialog_content = "Tidak lama lagi, jika kamu tidak berhenti menyerangku!",
  ui_story_5068_50680802_7_dialog_content = "Eleanor? Apa yang terjadi di sini? Saya mendengar suara pertarungan, jadi saya...",
  ui_story_5068_50680802_8_dialog_content = "—!!!",
  ui_story_5068_50680802_9_dialog_content = "Ini... Ini benar-benar kamu...",
  ui_story_5068_50680802_10_dialog_content = "Rebecca—!",
  ui_story_5068_50680802_11_dialog_content = "Aku sudah mencarimu ke mana-mana selama setahun terakhir ini!",
  ui_story_5068_50680802_12_dialog_content = "Syukurlah... Syukurlah kamu masih hidup! Aku sangat senang akhirnya menemukanmu!!!",
  ui_story_5068_50680802_13_dialog_content = "... <color=#FFB400>Isa</color>?!",
  ui_story_5068_50680802_14_dialog_content = "Tidak... Aku pasti sedang bermimpi...",
  ui_story_5068_50680802_15_dialog_content = "Ini bukan mimpi, Rebecca!",
  ui_story_5068_50680802_16_dialog_content = "Tapi aku pikir aku kehilanganmu juga hari itu...",
  ui_story_5068_50680802_17_dialog_content = "Nah, seperti yang bisa kamu lihat, aku baik-baik saja! Kamu, di sisi lain... Kamu 'kan sudah mengalami banyak hal, bukan?",
  ui_story_5068_50680802_18_dialog_content = "(Isa? Bukankah itu kakak perempuan Rebecca? Apakah ini benar-benar kebetulan?)",
  ui_story_5068_50680802_19_dialog_content = "(Juga... Apakah saya membayangkan sesuatu? Sepertinya racun yang mengelilingi Rebecca melemah saat Isa semakin mendekatinya.)",
  ui_story_5068_50680802_20_dialog_content = "Kamu pasti PlayerName, 'kan?",
  ui_story_5068_50680802_21_dialog_content = "Terima kasih atas informasi yang kamu berikan, akhirnya saya bisa menemukan adik saya di sini... Saya benar-benar tidak bisa cukup berterima kasih!",
  ui_story_5068_50680802_22_dialog_content = "Tapi aku tidak ingat memberimu—Tunggu, apakah itu bisa jadi Nona Sheol?!",
  ui_story_5068_50680802_23_dialog_content = "Yep! Nona Sheol menerima pesan dan rekaman Anda sebelumnya, tetapi dia belum bisa menghubungi Anda sejak itu.",
  ui_story_5068_50680802_24_dialog_content = "Wow, nggak bercanda! Terminalku penuh dengan pesan darinya! Aku pasti terlalu sibuk dalam kekacauan ini sampai lupa untuk memeriksa...",
  ui_story_5068_50680802_25_dialog_content = "Jadi kamu adalah asisten yang dikirim oleh Nona Sheol ke sini?!",
  ui_story_5068_50680802_26_dialog_content = "Benar! Saat ini saya bekerja untuk Lady Sheol dan Cloudrover Guild.",
  ui_story_5068_50680802_27_dialog_content = "Beberapa waktu lalu, saya mengetahui bahwa Serigala Hitam sedang mencari seorang gadis yang bisa mengobati efek racun kabut hitam...",
  ui_story_5068_50680802_28_dialog_content = "Yang membuatku berasumsi bahwa adikku masih hidup di suatu tempat. Saat itulah aku meminta Lady Sheol untuk membantuku mengawasi.",
  ui_story_5068_50680802_29_dialog_content = "Aku sudah membantu dia menagih utang beberapa hari ini, tapi ketika aku mendengar tentang kabut hitam, aku segera kembali secepat mungkin.",
  ui_story_5068_50680802_30_dialog_content = "Begitu tiba, Lady Sheol memberitahuku bahwa seseorang bernama PlayerName telah menghubungi seorang dokter bawah tanah, dan kemungkinan besar itu adalah adikku Rebecca. Bahkan jika bukan dia, orang tersebut masih erat kaitannya dengan Keluarga Svanedona...",
  ui_story_5068_50680802_31_dialog_content = "Jadi, saya mengumpulkan tim saya dan langsung bergegas ke sini!",
  ui_story_5068_50680802_32_dialog_content = "Tim... Anda?",
  ui_story_5068_50680802_33_dialog_content = "Hehe! Persekutuan Cloudrover cukup baik untuk—",
  ui_story_5068_50680802_34_dialog_content = "Kita harus melanjutkan percakapan ini di dalam klinik. Di luar sini tidak aman saat ini, dan juga ada masalah tentang apa yang terjadi sebelumnya...",
  ui_story_5068_50680802_35_dialog_content = "Tidak aman, katamu? Lalu apa yang terjadi sebelumnya?",
  ui_story_5068_50680802_36_dialog_content = "Semuanya baik-baik saja sekarang, Isa. Ayo kita masuk ke dalam.",
  ui_story_5068_50680802_37_dialog_content = "Hah? Oke, tentu!",
  ui_story_5068_50680802_38_dialog_content = "Hei! Awasi klinik dan sekitarnya dengan ketat! Tidak ada yang masuk kecuali saya memberi perintah!",
  ui_story_5068_50680802_39_dialog_content = "Paham!",
  ui_story_5068_50680901_1_dialog_content = "... Kalau saja aku tidak bersikap keras kepala seperti anak kecil pada ayah kita hari itu, aku tak akan pernah keluar rumah dengan marah.",
  ui_story_5068_50680901_2_dialog_content = "Tapi saat aku pergi, rumah kami diserang...",
  ui_story_5068_50680901_3_dialog_content = "Aku benar-benar tidak tahu harus berbuat apa sendirian. Aku mencoba menghubungi beberapa kenalan lama kami, tapi malah aku dijual oleh beberapa pengkhianat busuk!",
  ui_story_5068_50680901_4_dialog_content = "Terjual habis...?!",
  ui_story_5068_50680901_5_dialog_content = "Mengingat kembali, itu adalah kesalahanku karena terlalu ceroboh. Saat aku akhirnya menyadari, aku sudah dikelilingi... Mereka menyiksaku setelah itu, tapi untungnya Lady Sheol muncul suatu hari.",
  ui_story_5068_50680901_6_dialog_content = "Dia adalah orang yang luar biasa! Tidak hanya menyelamatkanku, dia juga memberiku pekerjaan... Itulah mengapa aku ingin membayar balik kebaikannya dengan bekerja sekeras mungkin untuknya!",
  ui_story_5068_50680901_7_dialog_content = "Aku tidak tahu kamu mengalami begitu banyak hal hanya dalam waktu setahun...",
  ui_story_5068_50680901_8_dialog_content = "Ha ha ha! Semua itu sudah di masa lalu, jadi jangan khawatir tentang itu. Lagipula, bukankah aku sudah bilang aku baik-baik saja sekarang?",
  ui_story_5068_50680901_9_dialog_content = "Bagi saya, rasanya seperti—Bagaimana ya? Oh, benar! Saya harus menciptakan keberuntungan saya sendiri!",
  ui_story_5068_50680901_10_dialog_content = "Tapi mari kita bicarakan tentang kamu, Rebecca! Bagaimana kamu bisa berakhir di tempat seperti ini?",
  ui_story_5068_50680901_11_dialog_content = "Semuanya benar-benar kumuh di sekitar sini. Apa yang sedang dilakukan adik perempuan paling imut di dunia ini berlarian di kawasan kumuh?",
  ui_story_5068_50680901_12_dialog_content = "Eleanor! Sebagai pelayan Rebecca, bukankah kamu seharusnya merawatnya dengan lebih baik?",
  ui_story_5068_50680901_13_dialog_content = "Tentu saja aku sudah merawatnya dengan baik! Bagaimana mungkin aku bisa melakukan sebaliknya?!",
  ui_story_5068_50680901_14_dialog_content = "Rebecca adalah orang paling penting di dunia bagiku. Bahkan jika itu menghabiskan nyawaku, aku akan—",
  ui_story_5068_50680901_15_dialog_content = "Lalu mengapa Anda belum menemukan tempat yang lebih baik untuknya tinggal? Tempat ini benar-benar tidak dapat diterima!",
  ui_story_5068_50680901_16_dialog_content = "Isa, aku tahu kamu hanya khawatir tentangku... Tapi tolong jangan menyalahkan dia.",
  ui_story_5068_50680901_17_dialog_content = "Dia bukan lagi pelayan dari Keluarga Svanedona, dan... kami juga bukan lagi putri dari bangsawan.",
  ui_story_5068_50680901_18_dialog_content = "Jika bukan karena Eleanor, aku mungkin sudah... Pokoknya, dia menyelamatkanku dan telah berusaha keras melindungiku dari Serigala Hitam selama setahun terakhir.",
  ui_story_5068_50680901_19_dialog_content = "Tidak mudah bagi dia untuk menemukan klinik \"kumuh\" ini dan memperbaikinya juga.",
  ui_story_5068_50680901_20_dialog_content = "Mungkin bukan yang paling mewah, tetapi ini melindungi kita dari cuaca buruk.",
  ui_story_5068_50680901_21_dialog_content = "Kami hidup sebagai dokter dan asisten di sini, dan saya sangat menghargai kehidupan baru yang telah kami bangun bersama.",
  ui_story_5068_50680901_22_dialog_content = "Nona Rebecca...",
  ui_story_5068_50680901_23_dialog_content = "Lagipula, tinggal di sini tidak terlalu buruk.",
  ui_story_5068_50680901_24_dialog_content = "Ketika kami tidak memiliki banyak pasien, kami menanam bunga dan membuat kerajinan tangan seperti dulu...",
  ui_story_5068_50680901_25_dialog_content = "Lihat? Eleanor membuat anting-anting ini untukku dengan kedua tangannya sendiri!",
  ui_story_5068_50680901_26_dialog_content = "Mereka terlihat cukup biasa... Eh, maksudku, jika itu aku, aku akan membuatmu satu set yang terlihat lebih baik.",
  ui_story_5068_50680901_27_dialog_content = "Dulu aku sering membelikan barang untukmu. Jika ada yang tahu apa yang paling cocok untukmu, itu pasti aku!",
  ui_story_5068_50680901_28_dialog_content = "...",
  ui_story_5068_50680901_29_dialog_content = "Ya, ya, aku tahu. Kamu memang punya insting yang bagus untuk hal-hal seperti ini.",
  ui_story_5068_50680901_30_dialog_content = "*Batuk-batuk*",
  ui_story_5068_50680901_31_dialog_content = "Hmm? Apakah kamu memiliki sesuatu untuk dikatakan, PlayerName?",
  ui_story_5068_50680901_32_dialog_content = "T-Tidak juga! Rasanya seperti Rebecca adalah kakak perempuan di sini...",
  ui_story_5068_50680901_33_dialog_content = "Hah? Mengapa semua orang terus mengatakan itu? Bahkan anggota keluarga kita dulu juga...",
  ui_story_5068_50680901_34_dialog_content = "... Isa, apakah kamu pikir ada anggota keluarga kita yang masih di luar sana?",
  ui_story_5068_50680901_35_dialog_content = "Aku juga mau menanyakan pertanyaan yang sama. Sepertinya kita berdua sama-sama tidak tahu, ya?",
  ui_story_5068_50680901_36_dialog_content = "Lady Sheol memberiku identitas palsu, jadi Serigala Hitam tidak bisa menemukanku... Aku hanya mendengar mereka mencoba mengejarmu, bukan anggota keluarga kita yang lain.",
  ui_story_5068_50680901_37_dialog_content = "Aku berpikir bahwa semua orang hilang dalam serangan tahun lalu. Baru setelah PlayerName menunjukkan botol kabut hitam itu, aku menyadari bahwa seseorang dalam keluarga kita baru-baru ini...",
  ui_story_5068_50680901_38_dialog_content = "Masih... itu juga berarti mungkin ada Svanedona lain di luar sana, kan?",
  ui_story_5068_50680901_39_dialog_content = "Juga mungkin mereka sedang melarikan diri dari Serigala Hitam, seperti kita. Beberapa di antara mereka mungkin tertangkap dan dieksploitasi juga...",
  ui_story_5068_50680901_40_dialog_content = "Jangan khawatir, Rebecca. Aku berjanji akan membantumu mencari mereka, apapun yang terjadi!",
  ui_story_5068_50680901_41_dialog_content = "Sebelum kita melanjutkan penyelidikan, saya sarankan kita pindah lokasi sesegera mungkin. Klinik ini sudah tidak aman lagi.",
  ui_story_5068_50680901_42_dialog_content = "Serigala Hitam... Bahkan setelah menyerang seluruh keluarga kita setahun yang lalu, mereka masih belum menyerah dalam perburuan? Apa yang sebenarnya mereka inginkan dari kita?",
  ui_story_5068_50680901_43_dialog_content = "Jika Lady Sheol tidak menghentikanku, aku sudah pergi untuk menyelesaikan masalah dengan mereka!",
  ui_story_5068_50680901_44_dialog_content = "Mungkin saya tidak mengenal \"Lady Sheol\" yang kamu sebutkan, tapi saya rasa dia memiliki ide yang benar. Menghadapi Serigala Hitam sendirian sangat berbahaya.",
  ui_story_5068_50680901_45_dialog_content = "Tapi bagaimana sekarang? Aku punya kamu, serta banyak orang di Cloudrover Guild yang membantu aku. Lebih cepat atau lambat, aku akan menagih utang yang Black Wolves berhutang kepada Keluarga Svanedona!",
  ui_story_5068_50680901_46_dialog_content = "Benar sekali! Jika kamu membutuhkan tempat baru untuk bersembunyi dari Black Wolves, kenapa tidak ikut ke Cloudrover Guild bersamaku?",
  ui_story_5068_50680901_47_dialog_content = "Saya rasa itu ide yang bagus!",
  ui_story_5068_50680901_48_dialog_content = "Lady Sheol lah yang mempekerjakan saya untuk ini, dan semua orang di sini erat kaitannya dengan kabut hitam. Saya yakin dia akan menawarkan perlindungan terbaik yang bisa dibeli oleh gilda untuk Anda.",
  ui_story_5068_50680901_49_dialog_content = "Namun…",
  ui_story_5068_50680901_50_dialog_content = "Hmm? Ada yang sedang kamu pikirkan, Rebecca?",
  ui_story_5068_50680901_51_dialog_content = "Aku yakin dia khawatir menyeret Lady Sheol dan Cloudrover Guild ke dalam masalah kita... Serta kamu, Isa.",
  ui_story_5068_50680901_52_dialog_content = "Apa? Tapi kita kan keluarga! Saya tidak akan pernah marah karena hal seperti itu, dan begitu juga dengan Nona Sheol! Dia orang baik, saya yakin dia tidak keberatan!",
  ui_story_5068_50680901_53_dialog_content = "Tidak peduli seberapa kejam Serigala Hitam itu, mereka akan gila jika membuat musuh dengan Cloudrover Guild. Saat waktu yang tepat, kita bisa menggunakan kekuatan guild untuk menghancurkan mereka dan membalas dendam keluarga kita!",
  ui_story_5068_50680901_54_dialog_content = "Balas dendam... Tidak pernah semudah itu. Aku hanya ingin terus hidup dalam damai... bersama kamu dan Eleanor di sisiku.",
  ui_story_5068_50680901_55_dialog_content = "Aku tahu, Rebecca, tetapi dunia tidak sesederhana itu.",
  ui_story_5068_50680901_56_dialog_content = "Aku tahu kamu tidak ingin menyakiti siapa pun, tapi itu tidak penting bagi mereka! Orang-orang akan menemukan berbagai alasan untuk menyakitimu!",
  ui_story_5068_50680901_57_dialog_content = "Aku tak pernah ingin menunjukkan kekejaman dunia ini padamu, tetapi terlepas dari apa yang kita inginkan, kita harus menghadapi kenyataan secara langsung saat ini!",
  ui_story_5068_50680901_58_dialog_content = "Ini benar-benar tidak masuk akal, bukan?",
  ui_story_5068_50680901_59_dialog_content = "Tapi memang begitu adanya: yang kuat memangsa yang lemah, dan hanya yang terkuat yang bertahan. Jika kita tidak membuat langkah pertama—",
  ui_story_5068_50680901_60_dialog_content = "Cukup sudah! Tidak perlu terus mengganggunya tentang hal ini lagi!",
  ui_story_5068_50680901_61_dialog_content = "Dia selalu menjadi orang yang baik hati dan lembut. Selama dia tetap seperti ini, aku akan mengurus segalanya sendiri!",
  ui_story_5068_50680901_62_dialog_content = "Kamu? Tapi ada batasnya yang bisa kamu lakukan! Beberapa hal harus diputuskan oleh dia dan tidak ada orang lain! Kamu tidak bisa berharap selalu ada di sisinya setiap menit setiap hari!",
  ui_story_5068_50680901_63_dialog_content = "Aku bisa dan aku pasti! Itulah yang telah kulakukan selama setahun terakhir ini!",
  ui_story_5068_50680901_64_dialog_content = "Tenanglah, semuanya! Sekarang bukan waktunya untuk berdebat...",
  ui_story_5068_50680901_65_dialog_content = "Saya masih berpikir Isa memiliki ide yang tepat, Rebecca—Jika kamu khawatir tentang keamananmu, Cloudrover Guild adalah tempat yang baik untuk mendirikan perkemahan.",
  ui_story_5068_50680901_66_dialog_content = "Bagaimana menurutmu, Eleanor?",
  ui_story_5068_50680901_67_dialog_content = "Aku akan mengikuti keputusanmu, Nona Rebecca.",
  ui_story_5068_50680901_68_dialog_content = "Saya mengerti... Tidak ada waktu untuk ragu, jadi sepertinya kita harus mengandalkan Cloudrover Guild untuk sementara waktu.",
  ui_story_5068_50680901_69_dialog_content = "Bagus! Sekarang setelah kita memutuskan, mari kita bergerak segera!",
  ui_story_5068_50680901_70_dialog_content = "Sebentar saja, aku perlu mengumpulkan beberapa barang. Bantu aku, Eleanor.",
  ui_story_5068_50680901_71_dialog_content = "Ya, Nona Rebecca.",
  ui_story_5068_50680901_72_dialog_content = "Kalau begitu, biar aku—",
  ui_story_5068_50680901_73_dialog_content = "Eleanor sudah lebih dari cukup membantu, Isa. Dia mengenal hal-hal yang saya butuhkan, jadi tolong... Cukup buat dirimu nyaman untuk saat ini.",
  ui_story_5068_50680901_74_dialog_content = "Eleanor lagi... Hmph. Apa yang bisa dia ketahui tentang Rebecca yang tidak diketahui oleh saudarinya sendiri?!",
  ui_story_5068_50680901_75_dialog_content = "Hai! Siapa kamu dan apa urusanmu di sini?!",
  ui_story_5068_50680901_76_dialog_content = "Hah? Ada apa dengan keributan mendadak di luar?",
  ui_story_5068_50680901_77_dialog_content = "Hey! Apa yang sedang terjadi di luar sana?!",
  ui_story_5068_50680901_78_dialog_content = "*batuk-batuk* Argh—Ini... Ini kabut hitam! Ada yang melepaskannya ke udara!",
  ui_story_5068_50680901_79_dialog_content = "Ini buruk! Ayo kita lihat!",
  ui_story_5068_50680901_80_dialog_content = "Siapa yang bisa melepaskan kabut hitam sebanyak ini di sini...",
  ui_story_5068_50680901_81_dialog_content = "Apakah itu Serigala Hitam?!",
  ui_story_5068_50680901_82_dialog_content = "*batuk-batuk* Rasanya mengerikan...!",
  ui_story_5068_50680901_83_dialog_content = "Ke sini, semuanya! Cepat!",
  ui_story_5068_50680901_84_dialog_content = "Rebecca? Kapan kamu keluar?",
  ui_story_5068_50680901_85_dialog_content = "Aku baru saja mendengar keributan di luar. Nah, serum ini seharusnya dapat mengurangi efek kabut hitam dengan sangat baik. Semuanya, kemari dan ambil beberapa untuk diri kalian sendiri!",
  ui_story_5068_50680901_86_dialog_content = "Target terlihat!",
  ui_story_5068_50680901_87_dialog_content = "…!!",
  ui_story_5068_50680901_88_dialog_content = "Pergi! Tak akan kubiarkan kalian menyentuh sedikit pun Nona Rebecca!",
  ui_story_5068_50680902_1_dialog_content = "Apa kalian semua baik-baik saja?",
  ui_story_5068_50680902_2_dialog_content = "Berkat serum Anda, saya merasa jauh lebih baik.",
  ui_story_5068_50680902_3_dialog_content = "Kabut hitam ini... Sepertinya jauh lebih kuat daripada yang diberikan Lady Sheol padaku sebelumnya.",
  ui_story_5068_50680902_4_dialog_content = "...",
  ui_story_5068_50680902_5_dialog_content = "Ini tidak baik, Isa!",
  ui_story_5068_50680902_6_dialog_content = "Apa yang terjadi sekarang?",
  ui_story_5068_50680902_7_dialog_content = "Lihat ke luar... Sejumlah penghuni kumuh mulai mengelilingi tempat ini!",
  ui_story_5068_50680902_8_dialog_content = "Penduduk kumuh? Tapi apa yang mereka lakukan di sini?",
  ui_story_5068_50680902_9_dialog_content = "Oh tidak...!",
  ui_story_5068_50680902_10_dialog_content = "Tahan! Kamu tidak boleh masuk ke dalam!",
  ui_story_5068_50680902_11_dialog_content = "Siapa... Siapa kalian? Di mana dokternya? *batuk, batuk* Kami butuh bantuannya... Semua kabut hitam ini tiba-tiba muncul, dan semua orang...",
  ui_story_5068_50680902_12_dialog_content = "Aduh... Sakit sekali... Di mana dokternya...?",
  ui_story_5068_50680902_13_dialog_content = "Ada begitu banyak orang, dan beberapa di antaranya sudah tersingkir...",
  ui_story_5068_50680902_14_dialog_content = "Eleanor! Semua orang! Aku... aku butuh bantuan kalian!",
  ui_story_5068_50680902_15_dialog_content = "Ya, Nona Rebecca!",
  ui_story_5068_50680902_16_dialog_content = "Hah?",
  ui_story_5068_50680902_17_dialog_content = "Berhenti mengeluh! Kalian dengar kan, sekarang ayo bantu!",
  ui_story_5068_50680902_18_dialog_content = "Tolong jangan panik, semuanya! Jaga jarak satu sama lain dan hindari menginjak orang yang tidak sadar!",
  ui_story_5068_50680902_19_dialog_content = "... Mereka semua datang mencari bantuan. Aku menolak untuk menelantarkan mereka!",
  ui_story_5068_50680902_20_dialog_content = "Rebecca? Apa yang sedang...",
  ui_story_5068_50680902_21_dialog_content = "Tidak ada waktu, jadi saya harus menangani mereka semua sekaligus...",
  ui_story_5068_50680902_22_dialog_content = "Tunggu, kamu akan merawat sebanyak ini orang secara bersamaan? Bisakah tubuhmu menanganinya?!",
  ui_story_5068_50680902_23_dialog_content = "Haaaa—!!",
  ui_story_5068_50680902_24_dialog_content = "*uhuk-uhuk* Jadi... lebih mudah bernapas...",
  ui_story_5068_50680902_25_dialog_content = "Dokter... dia menyelamatkan kita lagi...",
  ui_story_5068_50680902_26_dialog_content = "...",
  ui_story_5068_50680902_27_dialog_content = "Nona Rebecca!!!",
  ui_story_5068_50680902_28_dialog_content = "Hai! Berhenti menakutiku seperti ini! Rebecca?!",
  ui_story_5068_50680902_29_dialog_content = "Apakah... Semua orang baik-baik saja sekarang? Aku sedikit... kehabisan napas. Eleanor, tolong periksa mereka untukku...",
  ui_story_5068_50680902_30_dialog_content = "Rebecca, Aku—",
  ui_story_5068_50680902_31_dialog_content = "Pergilah!",
  ui_story_5068_50680902_32_dialog_content = "...",
  ui_story_5068_50680902_33_dialog_content = "Hai! Rebecca? Rebecca?!",
  ui_story_5068_50680902_34_dialog_content = "Berhenti menggoyangkan dia! Dia telah menghabiskan terlalu banyak Lumina, jadi dia sangat lemah sekarang. Kita perlu menemukan tempat yang aman untuk dia pulih!",
  ui_story_5068_50680902_35_dialog_content = "A... Aku baik-baik saja. Eleanor, yang lainnya—",
  ui_story_5068_50680902_36_dialog_content = "Mereka baik-baik saja untuk saat ini, Nona Rebecca. Berkat pengobatan Anda, yang mereka butuhkan hanyalah istirahat untuk pulih sepenuhnya.",
  ui_story_5068_50680902_37_dialog_content = "... Benarkah? Syukurlah.",
  ui_story_5068_50680902_38_dialog_content = "Apakah Serigala Hitam benar-benar kehilangan akal mereka?! Bagaimana mereka bisa melakukan sesuatu yang begitu mengerikan?!",
  ui_story_5068_50680902_39_dialog_content = "Mereka mungkin memiliki tujuan lain dalam pikiran.",
  ui_story_5068_50680902_40_dialog_content = "... Mereka mencoba memaksa Nona Rebecca keluar dari persembunyiannya!",
  ui_story_5068_50680902_41_dialog_content = "Argh... Tempat ini benar-benar terganggu sekarang!",
  ui_story_5068_50680902_42_dialog_content = "Mari kita menuju ke Cloudrover Guild. Saya tidak bisa memikirkan tempat yang lebih aman untuk pergi saat ini.",
  ui_story_5068_50680902_43_dialog_content = "Mengerti! Aku akan membawa Rebecca!",
  ui_story_5068_50680902_44_dialog_content = "Tidak, serahkan itu padaku.",
  ui_story_5068_50680902_45_dialog_content = "Kamu... baik! Tapi hati-hati!",
  ui_story_5068_50680902_46_dialog_content = "...",
  ui_story_5068_50680902_47_dialog_content = "Untuk kalian, tetap di sini dan kendalikan situasi. Setelah orang-orang ini pulih, segera kirim mereka pulang!",
  ui_story_5068_50680902_48_dialog_content = "Ya!",
  ui_story_5068_50681001_1_dialog_content = "Direktur...",
  ui_story_5068_50681001_2_dialog_content = "Kami telah mengkonfirmasi keberadaan Rebecca di area di mana Tim B menghilang, tapi...",
  ui_story_5068_50681001_3_dialog_content = "Aku sudah mengajarmu untuk tidak berbasa-basi, sekarang katakan saja.",
  ui_story_5068_50681001_4_dialog_content = "Hanya saja serangan bisa racunnya membuat kita sulit untuk mendekatinya... Apalagi menangkapnya hidup-hidup.",
  ui_story_5068_50681001_5_dialog_content = "... Dia memang memiliki bakat jika berhasil mengendalikan racunnya hanya dalam satu tahun.",
  ui_story_5068_50681001_6_dialog_content = "Tapi Anda masih jauh lebih kuat daripada dia, Direktur. Bagaimanapun, Anda menciptakan kabut hitam yang <color=#FFB400>khusus untuk mengimbangi racunnya</color>!",
  ui_story_5068_50681001_7_dialog_content = "Itu bukan urusanmu.",
  ui_story_5068_50681001_8_dialog_content = "M-Maafkan saya, Direktur! Aku akan tutup mulut saja...",
  ui_story_5068_50681001_9_dialog_content = "Jadi, di mana Rebecca sekarang?",
  ui_story_5068_50681001_10_dialog_content = "Kami menemukannya di Klinik Bawah Tanahnya, tetapi dia memiliki beberapa sekutu di sisinya. Mereka sedang membawanya ke Cloudrover Guild saat ini.",
  ui_story_5068_50681001_11_dialog_content = "Tapi masalahnya, ini belum saat yang tepat untuk menghadapi mereka.",
  ui_story_5068_50681001_12_dialog_content = "Persekutuan Cloudrover?",
  ui_story_5068_50681001_13_dialog_content = "Memang itu membuat segalanya lebih sulit, tetapi kita masih memiliki pilihan lain.",
  ui_story_5068_50681001_14_dialog_content = "Baiklah, kita seharusnya aman sekarang setelah berhasil sampai di Persekutuan Cloudrover.",
  ui_story_5068_50681001_15_dialog_content = "Kamu merasa lebih baik sekarang, Rebecca?",
  ui_story_5068_50681001_16_dialog_content = "Ya... Maaf telah merepotkan semua orang tadi.",
  ui_story_5068_50681001_17_dialog_content = "Kamu tidak perlu begitu sopan padaku! Persekutuan Cloudrover ada di wilayah kita, jadi santai saja dan bersantailah sementara kami mengurus sisanya!",
  ui_story_5068_50681001_18_dialog_content = "Sepertinya ruangan ini masih kekurangan beberapa persediaan, tapi jangan khawatir! Aku akan pergi membeli beberapa untukmu!",
  ui_story_5068_50681001_19_dialog_content = "Tunggu, Isa... Terlalu berbahaya untuk pergi sekarang, bukan?",
  ui_story_5068_50681001_20_dialog_content = "Seperti yang saya katakan, ini adalah Cloudrover Guild, jadi Black Wolves harus benar-benar bodoh untuk memulai pertarungan dengan kita di sini. Jangan khawatir, saya akan kembali sebelum kamu menyadarinya!",
  ui_story_5068_50681001_21_dialog_content = "PlayerName... Kamu tampak kurang sehat... Apakah kamu merasa baik-baik saja?",
  ui_story_5068_50681001_22_dialog_content = "Aku baik-baik saja. Ternyata pekerjaan ini jauh lebih rumit daripada yang kuduga, itu saja...",
  ui_story_5068_50681001_23_dialog_content = "Tapi jangan khawatir, aku hanya butuh waktu untuk berpikir. Silakan lanjutkan dan istirahat sejenak.",
  ui_story_5068_50681001_24_dialog_content = "Maaf karena... membuat begitu banyak masalah untukmu...",
  ui_story_5068_50681001_25_dialog_content = "Hmm…",
  ui_story_5068_50681001_26_dialog_content = "...!!!",
  ui_story_5068_50681001_27_dialog_content = "Eleanor... Cepat...",
  ui_story_5068_50681001_28_dialog_content = "PlayerName, kamu bisa pergi sekarang.",
  ui_story_5068_50681001_29_dialog_content = "H-hah? T-Tapi Rebecca itu...",
  ui_story_5068_50681001_30_dialog_content = "Aku bilang pergi! Rebecca butuh istirahatnya sekarang!",
  ui_story_5068_50681001_31_dialog_content = "Astaga, aku hampir lupa bertanya! Hei, Rebecca, apa sebenarnya yang kamu minta aku untuk—",
  ui_story_5068_50681001_32_dialog_content = "Eh…",
  ui_story_5068_50681001_33_dialog_content = "R-Rebecca...? Ap-Apa yang terjadi di sini?!",
  ui_story_5068_50681001_34_dialog_content = "Isa... Tolong... Jangan lihat...",
  ui_story_5068_50681001_35_dialog_content = "Eh…",
  ui_story_5068_50681001_36_dialog_content = "Apa ini... racunnya?!",
  ui_story_5068_50681001_37_dialog_content = "Tapi... kenapa ada racun yang keluar dari kulitmu? Ini... Ini mulai berubah menjadi merah terang! Kita perlu mengelapkannya dari kulitmu segera!",
  ui_story_5068_50681001_38_dialog_content = "Jangan sentuh dia!",
  ui_story_5068_50681001_39_dialog_content = "Jangan sentuh dia?! Adikku sedang kesakitan, sekarang lepaskan aku! Bagaimana kamu bisa berdiri di sana dan hanya menonton?!",
  ui_story_5068_50681001_40_dialog_content = "Aku juga tidak ingin melihat Rebecca menderita! Tapi sekarang ini...",
  ui_story_5068_50681001_41_dialog_content = "Tidak ada yang bisa kita lakukan untuk membantunya.",
  ui_story_5068_50681001_42_dialog_content = "Rebecca menghasilkan serum terlalu banyak sebelumnya. Satu-satunya cara untuk membuatnya stabil kembali adalah dengan mengeluarkan racun sebanyak ini.",
  ui_story_5068_50681001_43_dialog_content = "Jika keseimbangan antara keduanya rusak... Kemungkinan dia akan kehilangan akal sehatnya.",
  ui_story_5068_50681001_44_dialog_content = "Lebih jauh lagi, racun ini sangat berbahaya bagi kebanyakan orang. Aku yakin dia tidak ingin siapa pun yang bersentuhan dengan racun ini!",
  ui_story_5068_50681001_45_dialog_content = "Anu…",
  ui_story_5068_50681001_46_dialog_content = "Rebecca...",
  ui_story_5068_50681001_47_dialog_content = "Tapi dia tidak pernah melakukan ini sebelumnya! Aku kakaknya, jadi bagaimana bisa aku tidak tahu tentang ini?!",
  ui_story_5068_50681001_48_dialog_content = "Ini adalah sesuatu yang dia putuskan untuk dipikul sendiri. Dia juga punya alasan tersendiri dalam melakukannya.",
  ui_story_5068_50681001_49_dialog_content = "Aku tidak peduli alasan dia! Kamu tidak bisa membiarkan Rebecca menyakiti dirinya seperti ini!",
  ui_story_5068_50681001_50_dialog_content = "V-Veronica...",
  ui_story_5068_50681001_51_dialog_content = "Aku... Aku memilih ini untuk diriku sendiri, Isa. Ini adalah beban yang harus aku tanggung... Jadi jangan salahkan orang lain.",
  ui_story_5068_50681001_52_dialog_content = "Aku tidak ingin... kamu terlalu khawatir. Tapi kamu masih... mengetahuinya.",
  ui_story_5068_50681001_53_dialog_content = "Rebecca! Apakah... Apakah kamu merasa lebih baik?",
  ui_story_5068_50681001_54_dialog_content = "Ya... Setelah berhasil mengeluarkan semua ini dari pikiranku... Aku merasa jauh lebih baik.",
  ui_story_5068_50681001_55_dialog_content = "Apakah ini yang kamu simpan di semua toples itu di ruang tersembunyi kamu? Jika iya, berarti kamu sudah mengalami ini berkali-kali...",
  ui_story_5068_50681001_56_dialog_content = "Toples apa? Dan ruangan tersembunyi?! Jika kamu tidak ingin aku khawatir, maka ceritakan semuanya padaku!",
  ui_story_5068_50681001_57_dialog_content = "Ini... sebenarnya bukan masalah besar. Hanya saja... Sejak <color=#FFB400>hari itu</color>, saya memutuskan untuk melakukan penelitian tentang racun saya.",
  ui_story_5068_50681001_58_dialog_content = "Mungkin karena aku mulai terlambat, atau mungkin aku terlalu terburu-buru, tapi... Penelitianku menghasilkan efek samping ini.",
  ui_story_5068_50681001_59_dialog_content = "Tapi aku tak akan berhenti.",
  ui_story_5068_50681001_60_dialog_content = "Dulu... Saya tidak bisa menggunakan \"bakat\" saya untuk membantu siapa pun. Yang bisa saya lakukan hanyalah lari dan bersembunyi seperti pengecut...",
  ui_story_5068_50681001_61_dialog_content = "Itu bukan salahmu, Rebecca! Serigala Hitam yang patut disalahkan, bukan kamu!",
  ui_story_5068_50681001_62_dialog_content = "Tapi... Tapi jika aku sudah belajar mengendalikan racun ku lebih awal, mungkin aku bisa mencegah mereka masuk ke rumah kita...",
  ui_story_5068_50681001_63_dialog_content = "Bahkan sekarang, masih ada orang yang ingin saya lindungi.",
  ui_story_5068_50681001_64_dialog_content = "Dan jika melindungi mereka berarti menanggung sedikit lebih banyak rasa sakit... Maka itu adalah harga yang aku bersedia bayar.",
  ui_story_5068_50681001_65_dialog_content = "Tadi itu bukan hanya sedikit sakit. Kamu jelas menderita... Argh, apa gunanya aku sebagai kakak yang tidak berguna?!",
  ui_story_5068_50681001_66_dialog_content = "Kamu tidak seharusnya melakukan ini... Benar! Kamu tidak perlu melakukan ini lagi!",
  ui_story_5068_50681001_67_dialog_content = "Saya akan meminta Lady Sheol untuk menawarkan Anda pekerjaan di guild. Setelah dia kembali dari pertemuan bisnisnya, saya akan memberikan rekomendasi yang baik untuk Anda!",
  ui_story_5068_50681001_68_dialog_content = "Dengan cara itu, Anda dapat hidup dan bekerja dengan aman total! Anda tidak akan pernah harus takut akan nyawa Anda lagi, atau melukai diri sendiri dengan penelitian Anda lagi!",
  ui_story_5068_50681001_69_dialog_content = "Untuk detailnya, serahkan sisanya padaku saja!",
  ui_story_5068_50681001_70_dialog_content = "Isa... Meskipun sudah begitu lama, Anda masih menganggap saya sebagai anak kecil.",
  ui_story_5068_50681001_71_dialog_content = "Itulah yang dilakukan kakak perempuan! Jangan khawatir, aku tahu apa yang harus dilakukan!",
  ui_story_5068_50681001_72_dialog_content = "Aku akan pergi membelikanmu piyama yang bagus sementara kamu banyak istirahat. Sampai jumpa sebentar lagi!",
  ui_story_5068_50681001_73_dialog_content = "...",
  ui_story_5068_50681001_74_dialog_content = "Masih adakah yang mengganggu pikiran Anda, Nona Rebecca?",
  ui_story_5068_50681001_75_dialog_content = "Aku tidak bisa berhenti khawatir tentang pasien-pasien tadi. Kita pergi terburu-buru sehingga aku tidak bisa memeriksa mereka lebih dekat.",
  ui_story_5068_50681001_76_dialog_content = "Kita sudah tidak di klinik lagi, jadi jika ada yang terjadi pada mereka...",
  ui_story_5068_50681001_77_dialog_content = "Jangan khawatir, saya akan kembali dan memeriksa mereka. Kita meninggalkan beberapa perbekalan medis, jadi saya bisa membagikannya juga.",
  ui_story_5068_50681001_78_dialog_content = "Kamu pergi sekarang? Tapi bagaimana jika Black Wolves masih berkeliaran di sekitar klinik?",
  ui_story_5068_50681001_79_dialog_content = "Kamu tidak meremehkan saya, kan, PlayerName?",
  ui_story_5068_50681001_80_dialog_content = "Bagaimanapun, saya masih tidak nyaman meninggalkan Anda sendirian di Cloudrover Guild, Nona Rebecca.",
  ui_story_5068_50681001_81_dialog_content = "Tempat ini sepertinya cukup aman. Lagipula, PlayerName masih di sini dan adikku seharusnya segera kembali.",
  ui_story_5068_50681001_82_dialog_content = "Aku merasa jauh lebih baik sekarang, tetapi hal yang sama tidak bisa dikatakan untuk pasien kita. Mereka membutuhkan kita saat ini.",
  ui_story_5068_50681001_83_dialog_content = "Mengerti. Aku tidak akan lama, tetapi tolong jaga dirimu dengan baik selama aku pergi.",
  ui_story_5068_50681001_84_dialog_content = "Rebecca sepertinya mempercayai kamu, PlayerName, jadi saya akan melakukan hal yang sama.",
  ui_story_5068_50681001_85_dialog_content = "Oke.",
  ui_story_5068_50681001_86_dialog_content = "Maaf, PlayerName... Aku tidak menakutimu barusan, kan?",
  ui_story_5068_50681001_87_dialog_content = "Sama sekali tidak. Tolong jangan merasa begitu.",
  ui_story_5068_50681001_88_dialog_content = "Hanya saja... bisakah kamu berjanji sesuatu padaku?",
  ui_story_5068_50681001_89_dialog_content = "Ada apa?",
  ui_story_5068_50681001_90_dialog_content = "Tidak peduli apa yang terjadi, tolong jangan pernah menyakiti diri sendiri lagi.",
  ui_story_5068_50681001_91_dialog_content = "PlayerName…",
  ui_story_5068_50681001_92_dialog_content = "Mari kita lihat... Dia pasti membutuhkan perlengkapan mandi, serta handuk... Ah, aku akan membelikannya banyak handuk!",
  ui_story_5068_50681001_93_dialog_content = "Wow, aku yakin Rebecca akan terlihat sangat imut dengan ini! Sekarang aku hanya perlu...",
  ui_story_5068_50681001_94_dialog_content = "?!",
  ui_story_5068_50681001_95_dialog_content = "*batuk, batuk* Siapa itu? Dan berani-beraninya kau membuat masalah... di wilayah Cloudrover Guild?!",
  ui_story_5068_50681001_96_dialog_content = "<color=#e8d9bb>Puf—</color>",
  ui_story_5068_50681001_97_dialog_content = "Hah...?!",
  ui_story_5068_50681001_98_dialog_content = "Serigala Hitam...",
  ui_story_5068_50681101_1_dialog_content = "Tunggu... Di mana aku?",
  ui_story_5068_50681101_2_dialog_content = "Dan aku diikat begini?! Tsk, Serigala Hitam itu selalu menggunakan trik rendahan seperti ini.",
  ui_story_5068_50681101_3_dialog_content = "Namun, cara mereka mengikatku... Heh, leluhurmu pasti sangat malu.",
  ui_story_5068_50681101_4_dialog_content = "...",
  ui_story_5068_50681101_5_dialog_content = "Apa masalahnya sekarang? Tidak bisa bicara dengan gadis itu bahkan setelah kamu menculiknya?!",
  ui_story_5068_50681101_6_dialog_content = "Beritahu siapa pun yang bertanggung jawab untuk keluar sini! Aku punya dendam yang harus diselesaikan dengan mereka!",
  ui_story_5068_50681101_7_dialog_content = "Isa Svanedona, putri tertua dari Keluarga Svanedona yang kebetulan sedang belajar di luar negeri pada saat itu.",
  ui_story_5068_50681101_8_dialog_content = "Aku penasaran kabut hitam apa yang akan dihasilkan tubuhmu saat terbakar... Apakah itu akan menyebabkan orang merasakan sakit yang tak tertahankan? Atau mungkin itu akan membuat mereka mengalami kejang yang tak terkendali?",
  ui_story_5068_50681101_9_dialog_content = "Heheheh. Sayang sekali kamu tidak mewarisi bakat keluargamu.",
  ui_story_5068_50681101_10_dialog_content = "Tutup mulutmu! Keluargaku memang sudah tiada, tapi aku masih di sini, dan aku akan membalas dendam lebih cepat atau lambat!",
  ui_story_5068_50681101_11_dialog_content = "Sungguh? Karena sepertinya kamu tidak pandai dalam hal lain selain berbicara besar. Di sisi lain, kakakmu...",
  ui_story_5068_50681101_12_dialog_content = "Apa yang kau inginkan darinya?! Aku tak akan biarkan Serigala Hitam menyakiti keluargaku lagi!",
  ui_story_5068_50681101_13_dialog_content = "Apa yang aku inginkan? Heh... Yang aku inginkan hanyalah menyelesaikan apa yang sudah kumulai.",
  ui_story_5068_50681101_14_dialog_content = "Aku mengingatkan kamu, jangan dekat-dekat dengan adikku... Atau...",
  ui_story_5068_50681101_15_dialog_content = "Atau apa? Tunggu, biar aku tebak... Kamu akan melepaskan diri dari ikatanmu dan membunuhku di tempatku berdiri?",
  ui_story_5068_50681101_16_dialog_content = "Argh...! Diam!",
  ui_story_5068_50681102_1_dialog_content = "J-Jika kamu ingin mendekati adikku... Kamu harus membunuhku terlebih dahulu...",
  ui_story_5068_50681102_2_dialog_content = "Membunuhmu? Tolong, aku tidak cukup bodoh untuk menghadapi Cloudrover Guild secara langsung.",
  ui_story_5068_50681102_3_dialog_content = "Mungkin kamu tidak cukup bodoh... Tapi kamu masih cukup bodoh... Hahaha...",
  ui_story_5068_50681102_4_dialog_content = "Cukup dari kamu!",
  ui_story_5068_50681102_5_dialog_content = "Ketika Anda menghadapi kekuatan yang luar biasa, yang dapat Anda lakukan hanyalah menyerah dan mati... Setelah bertahun-tahun berjuang, itulah satu-satunya kebenaran yang telah saya pelajari.",
  ui_story_5068_50681102_6_dialog_content = "Dan sekarang, aku akan mengajarkan pelajaran yang sama kepadamu... Kamu harus merasa bersyukur.",
  ui_story_5068_50681102_7_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5068_50681102_8_dialog_content = "Itu kamu, Isa?",
  ui_story_5068_50681102_9_dialog_content = "Tidak... Aneh, tidak ada orang di pintu.",
  ui_story_5068_50681102_10_dialog_content = "Hah? Ada surat di tanah... Dan tertulis \"Untuk Rebecca\"!",
  ui_story_5068_50681102_11_dialog_content = "Untukku? Biar kulihat...",
  ui_story_5068_50681102_12_dialog_content = "Tidak... Ini tak mungkin!",
  ui_story_5068_50681102_13_dialog_content = "Ini Isa... Dia ditangkap oleh Black Wolves! Tapi dia bilang mereka tidak akan melakukan apa-apa padanya di wilayah Cloudrover Guild!",
  ui_story_5068_50681102_14_dialog_content = "Jika Black Wolves bersedia mengabaikan peraturan Umbraton... Ini berarti mereka siap untuk bertarung secara terbuka sekarang.",
  ui_story_5068_50681102_15_dialog_content = "Eleanor masih belum kembali... apakah sesuatu juga terjadi padanya?",
  ui_story_5068_50681102_16_dialog_content = "Kita akan khawatirkan itu nanti. Apa lagi isi surat itu?",
  ui_story_5068_50681102_17_dialog_content = "Tulisan ini mengatakan jika kita ingin dia tetap tak terluka, aku harus datang ke tempat persembunyian mereka dalam satu jam ke depan... Ada juga alamat yang tertulis di sini.",
  ui_story_5068_50681102_18_dialog_content = "Jadi sebenarnya mereka mengejar kamu sejak awal. Kamu akan jatuh ke dalam perangkap mereka jika kamu pergi ke sana sekarang!",
  ui_story_5068_50681102_19_dialog_content = "Tapi mereka menculik Isa... Aku tidak punya pilihan!",
  ui_story_5068_50681102_20_dialog_content = "Bagaimana mungkin aku meninggalkannya saat kita baru saja menemukan satu sama lain setelah sekian lama? Tidak hanya itu, mungkin masih ada lebih banyak anggota keluarga saya di sana...",
  ui_story_5068_50681102_21_dialog_content = "Tapi aku sudah berjanji untuk mencari cara membantumu...",
  ui_story_5068_50681102_22_dialog_content = "Tidak ada waktu lagi... Selama setahun terakhir, yang kulakukan hanyalah berlari dan bersembunyi di klinik bawah tanahku.",
  ui_story_5068_50681102_23_dialog_content = "Saya tidak tahu apakah ada yang selamat dari keluarga saya, atau mereka ditangkap dan disiksa... Kebodohan saya lah yang menyebabkan semua ini.",
  ui_story_5068_50681102_24_dialog_content = "Meskipun begitu, aku masih saja melarikan diri. Aku... Aku bahkan meminta kamu untuk memikirkan jawaban untukku.",
  ui_story_5068_50681102_25_dialog_content = "Tujuan utama penelitian tentang racun saya adalah untuk menemukan cara melindungi orang yang saya sayangi, tetapi bukan hanya saya gagal, saya juga membahayakan nyawa adik saya...",
  ui_story_5068_50681102_26_dialog_content = "Aku tidak bisa terus melarikan diri. Tidak lagi.",
  ui_story_5068_50681102_27_dialog_content = "Jika orang yang kamu cintai diculik, kamu pasti akan berusaha sekuat tenaga untuk menyelamatkan mereka, bukan?",
  ui_story_5068_50681102_28_dialog_content = "... Aku tahu aku tidak akan bisa membujukmu untuk tidak melakukannya, tapi ini terlalu berbahaya hanya untuk kita berdua.",
  ui_story_5068_50681102_29_dialog_content = "Persekutuan Cloudrover... Umbraton... Bahkan geng-geng...",
  ui_story_5068_50681102_30_dialog_content = "Tunggu—aku tahu ada kelompok tentara bayaran di kota ini! Mungkin mereka bisa membantu kita!",
  ui_story_5068_50681201_1_dialog_content = "Tak pernah terbayang kamu akan menerima pekerjaan yang melibatkan penyelamatan sandera, PlayerName.",
  ui_story_5068_50681201_2_dialog_content = "Ceritanya panjang... Tapi kita harus mengeluarkan Isa dari sana dengan selamat.",
  ui_story_5068_50681201_3_dialog_content = "Terima kasih sudah datang dalam waktu sesingkat itu, btw. Ini seharusnya sangat membantu kami!",
  ui_story_5068_50681201_4_dialog_content = "Jangan khawatir! Kapten Luke tidak bisa datang ke sini secara pribadi, tetapi kami akan memberikan segala yang kami punya!",
  ui_story_5068_50681201_5_dialog_content = "Kita berada di tempat persembunyian Serigala Hitam, jadi tetap waspada! Kabut hitam di sini sangat pekat, yang berarti mereka mungkin memproduksinya di suatu tempat di tempat ini!",
  ui_story_5068_50681201_6_dialog_content = "...",
  ui_story_5068_50681201_7_dialog_content = "<color=#e8d9bb>Krieeek...</color>",
  ui_story_5068_50681201_8_dialog_content = "Apakah kamu benar-benar berpikir Isa ada di sini? Yang aku lihat hanyalah sekelompok toples dan wadah.",
  ui_story_5068_50681201_9_dialog_content = "Aku bisa merasakan keberadaan Isa di dekat sini, tapi toples-toples ini...",
  ui_story_5068_50681201_10_dialog_content = "Ada nama-nama tertulis di atasnya...",
  ui_story_5068_50681201_11_dialog_content = "Om Albert, Jessica... Ibu dan Ayah... Aaron...",
  ui_story_5068_50681201_12_dialog_content = "Nama mereka ada di stoples racun ini, yang berarti mereka semua...",
  ui_story_5068_50681201_13_dialog_content = "Rebecca...",
  ui_story_5068_50681201_14_dialog_content = "Semua nama ini...",
  ui_story_5068_50681201_15_dialog_content = "Bahkan... Bahkan ada toples besar kosong dengan nama saya di atasnya.",
  ui_story_5068_50681201_16_dialog_content = "... T-Tapi saya tidak melihat satu pun dengan nama Isa! Itu berarti kita belum terlambat!",
  ui_story_5068_50681201_17_dialog_content = "Tidak, PlayerName. Kamu tahu... Isa tidak pernah mewarisi kemampuan keluarga kita.",
  ui_story_5068_50681201_18_dialog_content = "Yang berarti dia mungkin sudah...",
  ui_story_5068_50681201_19_dialog_content = "Jangan langsung menyimpulkan dulu. Kita harus menemukannya terlebih dahulu!",
  ui_story_5068_50681201_20_dialog_content = "Awas! Musuh sedang mendekat!",
  ui_story_5068_50681201_21_dialog_content = "<color=#e8d9bb>Tok, tok, tok…</color>",
  ui_story_5068_50681201_22_dialog_content = "Atas nama Black Wolves, selamat datang di markas operasi kami.",
  ui_story_5068_50681201_23_dialog_content = "... Ini Arte, Direktur Serigala Hitam!",
  ui_story_5068_50681201_24_dialog_content = "Heheh... Sudah beberapa waktu sejak terakhir kali tempat ini ramai.",
  ui_story_5068_50681201_25_dialog_content = "Tidak sopan membawa kerumunan ke pesta saat saya hanya mengundang kamu... Rebecca Svanedona.",
  ui_story_5068_50681201_26_dialog_content = "Sayang sekali. Jika kamu tiba sedikit lebih awal, mungkin kamu sempat melihatnya untuk terakhir kalinya... Ayahmu, bukan? Pria itu memiliki tekad yang luar biasa; dari semua subjek uji coba yang pernah ada, dia bertahan paling lama.",
  ui_story_5068_50681201_27_dialog_content = "Apa-apaan kau…!",
  ui_story_5068_50681201_28_dialog_content = "Awalnya saya hanya ingin melampiaskan kebencian saya pada Keluarga Svanedona, tetapi ketika saya menemukan rahasia Anda... saya tahu saya telah dipilih untuk sesuatu yang lebih besar.",
  ui_story_5068_50681201_29_dialog_content = "Kamu juga seharusnya tidak terlalu kesal padaku. Bagaimanapun, jika aku tidak memenjarakan mereka, mereka mungkin tidak akan hidup untuk melihat tahun depan. Setuju, kan?",
  ui_story_5068_50681201_30_dialog_content = "Lagipula, jika ada yang harus disalahkan... Itu karena mereka tidak menghasilkan racun mereka hingga setelah mereka mati. Aku tidak bisa membuat kabut hitamku tanpa itu.",
  ui_story_5068_50681201_31_dialog_content = "Tapi kau berbeda, Rebecca. Aku akan pastikan untuk menghargaimu selama mungkin—",
  ui_story_5068_50681201_32_dialog_content = "Aku tidak akan membiarkan kamu melakukan apapun padanya lagi!",
  ui_story_5068_50681201_33_dialog_content = "Oh? Sepertinya aku mengenalmu. Kau... Caelestite, bukan?",
  ui_story_5068_50681201_34_dialog_content = "Cih... Kalau saja kita bisa bertemu dalam keadaan yang berbeda.",
  ui_story_5068_50681201_35_dialog_content = "Aku pernah dengar tentang kekuatanmu sebelumnya... Mungkin kita akan punya kesempatan untuk bekerja sama di masa depan?",
  ui_story_5068_50681201_36_dialog_content = "Aku tak akan pernah bekerja dengan orang brengsek yang tidak berperikemanusiaan seperti kamu! Sekarang di mana Isa?!",
  ui_story_5068_50681201_37_dialog_content = "Perseteruan antara Black Wolves dan Keluarga Svanedona seharusnya tidak melibatkan Caelestite, jadi bisakah kamu untuk sementara waktu tidak ikut campur?",
  ui_story_5068_50681201_38_dialog_content = "Dalam mimpimu! Aku di sini untuk membantu temanku menyelamatkan keluarganya!",
  ui_story_5068_50681201_39_dialog_content = "Dan di sini aku mencoba menjadi tuan rumah yang baik. Sungguh konyol.",
  ui_story_5068_50681201_40_dialog_content = "Bawa dia keluar!",
  ui_story_5068_50681201_41_dialog_content = "...",
  ui_story_5068_50681201_42_dialog_content = "Isa!!",
  ui_story_5068_50681201_43_dialog_content = "Ugh... Rebecca? Apa yang kamu lakukan di sini?!",
  ui_story_5068_50681201_44_dialog_content = "Kamu seharusnya tidak datang ke sini! Bagaimana bisa kamu terjebak dalam perangkap yang begitu jelas?! Jangan khawatir tentang aku, lari saja sebelum terlambat!",
  ui_story_5068_50681201_45_dialog_content = "Lepaskan adikku!",
  ui_story_5068_50681201_46_dialog_content = "Tentu, saya akan sangat senang untuk melepaskannya. Tapi—",
  ui_story_5068_50681201_47_dialog_content = "Kamu harus tetap di tempatnya.",
  ui_story_5068_50681201_48_dialog_content = "Apa maumu?",
  ui_story_5068_50681201_49_dialog_content = "Apakah saya tidak cukup jelas? Rebecca harus tinggal bersama Black Wolves.",
  ui_story_5068_50681201_50_dialog_content = "Aku tak akan menyakiti sehelai rambut pun darinya; lagipula, dialah satu-satunya yang bisa membantu memajukan penelitianku tentang kabut hitam. Aku bahkan bersedia melupakan masa lalu.",
  ui_story_5068_50681201_51_dialog_content = "Aku juga bisa memperkenalkanmu kepada <color=#FFB400>wanita</color> yang merekomendasikan dia kepadaku pada awalnya.",
  ui_story_5068_50681201_52_dialog_content = "Tapi jika dia melanggar aturan meskipun hanya sekali... Heheheh, silakan mencoba, Rebecca.",
  ui_story_5068_50681201_53_dialog_content = "Ketahuilah bahwa kerja sama bukan hanya demi kepentingan terbaik Anda. Itu juga satu-satunya pilihan yang tersisa bagi Anda.",
  ui_story_5068_50681201_54_dialog_content = "Apa kamu bercanda? Membahas masa lalu dan seorang wanita... Rebecca jelas adalah korban di sini!",
  ui_story_5068_50681201_55_dialog_content = "Oh? Tidak masalah jika Caelestite tidak tahu apa-apa, tapi kamu Rebecca? Jangan bilang kamu menyembunyikan rahasia keluarga hanya untuk memanfaatkan kepercayaannya?",
  ui_story_5068_50681201_56_dialog_content = "Aku tidak tahu apa yang kamu bicarakan.",
  ui_story_5068_50681201_57_dialog_content = "Jika itu masalahnya, maka saudaramu gagal memberitahumu apa yang terjadi antara Black Wolves dan Keluarga Svanedona.",
  ui_story_5068_50681201_58_dialog_content = "Dulu, yang aku inginkan hanyalah mengajakmu bekerja bersamaku, tetapi Keluarga Svanedona meremehkan kami, Serigala Hitam. Mereka tidak hanya menolak kami, tetapi juga melukai banyak anggota kami.",
  ui_story_5068_50681201_59_dialog_content = "Pembohong! Serigala Hitam lah yang pertama kali bicara sembarangan! Pertarungan hanya dimulai karena kalian preman yang membuat langkah pertama!",
  ui_story_5068_50681201_60_dialog_content = "Buat dia diam.",
  ui_story_5068_50681201_61_dialog_content = "Ya!",
  ui_story_5068_50681201_62_dialog_content = "Mmm, mmm, mmm—",
  ui_story_5068_50681201_63_dialog_content = "Undang aku untuk bekerja bersamamu?",
  ui_story_5068_50681201_64_dialog_content = "Oh? Sepertinya saya benar, kamu tidak tahu apa yang sebenarnya terjadi.",
  ui_story_5068_50681201_65_dialog_content = "Setelah sekian lama, bahkan teman terdekatmu pun tidak memiliki keberanian untuk memberitahumu?",
  ui_story_5068_50681201_66_dialog_content = "Dia tahu betul apa yang terjadi saat itu. Bagaimanapun, dia dulu juga merupakan anggota Black Wolf.",
  ui_story_5068_50681201_67_dialog_content = "…!!",
  ui_story_5068_50681201_68_dialog_content = "Maksudmu... Eleanor?",
  ui_story_5068_50681301_1_dialog_content = "Maksudmu... Eleanor?",
  ui_story_5068_50681301_2_dialog_content = "Heheheh. Kaget?",
  ui_story_5068_50681301_3_dialog_content = "Eleanor ternyata merupakan salah satu anggota tertua dalam sejarah Black Wolves.",
  ui_story_5068_50681301_4_dialog_content = "Aku mengirimnya untuk menyusup ke dalam Keluarga Svanedona sudah lama... untuk mengumpulkan setiap informasi tentang mereka.",
  ui_story_5068_50681301_5_dialog_content = "Bahkan bisa dibilang, kehancuran seluruh keluarga itu semua berkat dirinya.",
  ui_story_5068_50681301_6_dialog_content = "Eleanor... T-Tidak... Itu mustahil!",
  ui_story_5068_50681301_7_dialog_content = "Hari keluarga kami diserang... Eleanor mempertaruhkan nyawanya untuk menyelamatkanku!",
  ui_story_5068_50681301_8_dialog_content = "Dia selalu ada di sisiku sejak saat itu, tidak peduli apa yang terjadi pada kami!",
  ui_story_5068_50681301_9_dialog_content = "Eleanor tidak mungkin menjadi salah satu dari kalian!",
  ui_story_5068_50681301_10_dialog_content = "Aku hanya menyampaikan fakta, tidak lebih. Mengkhianati orang lain adalah kebiasaan yang sulit dihentikan, Rebecca; kamu akan pintar jika mengingat hal itu.",
  ui_story_5068_50681301_11_dialog_content = "Saya terkejut pahlawan Black Wolves tidak ada bersama Anda hari ini. Tidak bahwa saya benar-benar peduli, karena Anda satu-satunya yang menarik perhatian saya, Rebecca Svanedona.",
  ui_story_5068_50681301_12_dialog_content = "...",
  ui_story_5068_50681301_13_dialog_content = "(Jika Eleanor belum tertangkap, berarti kemungkinan dia sekarang ada di klinik lagi...)",
  ui_story_5068_50681301_14_dialog_content = "(Tatapan di mata Rebecca... Apa yang mungkin dia pikirkan?)",
  ui_story_5068_50681301_15_dialog_content = "Tapi cukup tentang semua itu. Apakah kamu sudah punya jawaban untukku, Rebecca?",
  ui_story_5068_50681301_16_dialog_content = "Jangan—!!!",
  ui_story_5068_50681301_17_dialog_content = "Mmm, mmm, mmm...",
  ui_story_5068_50681301_18_dialog_content = "Isa!!!",
  ui_story_5068_50681301_19_dialog_content = "Bilah yang tergantung di atas kepala gadis itu bukan hanya untuk penampilan, lho?",
  ui_story_5068_50681301_20_dialog_content = "Pada akhirnya, satu-satunya yang aku inginkan adalah kekuatanmu itu.",
  ui_story_5068_50681301_21_dialog_content = "Kalau saja kamu bergabung dengan kami daripada bersembunyi seperti pengecut selama setahun ini, orang-orang dalam toples itu tak akan mati dengan cara yang memalukan.",
  ui_story_5068_50681301_22_dialog_content = "Tapi sekarang aku memberimu satu kesempatan terakhir. Jika kamu tidak ingin adikmu berakhir seperti mereka yang lain, akui bahwa ini semua salahmu! Akui bahwa kamu adalah putri dari bencana!",
  ui_story_5068_50681301_23_dialog_content = "Putri bencana...",
  ui_story_5068_50681301_24_dialog_content = "... Apakah ini benar-benar semua salahku? Kehancuran keluargaku... Racun berbahaya yang tak pernah berhenti mengalir dariku...",
  ui_story_5068_50681301_25_dialog_content = "Sejak aku lahir, aku tidak pernah bisa menyentuh hal-hal baik seperti orang normal...",
  ui_story_5068_50681301_26_dialog_content = "Jangan dengarkan dia, Rebecca! Lihat saja apa yang telah dia lakukan pada seluruh keluargamu! Kamu tidak punya alasan untuk menyerah kepadanya!",
  ui_story_5068_50681301_27_dialog_content = "Mungkin begitu, tapi pilihan apa lagi yang dia punya?",
  ui_story_5068_50681301_28_dialog_content = "Racun dalam tubuhnya akan menjadi akhir dari hidupnya suatu hari nanti. Daripada membiarkannya sia-sia, mengapa tidak membiarkan saya membuat sesuatu yang berguna darinya?",
  ui_story_5068_50681301_29_dialog_content = "...",
  ui_story_5068_50681301_30_dialog_content = "(Jika ini terus berlanjut, Rebecca mungkin benar-benar akan membuat pilihan itu...)",
  ui_story_5068_50681301_31_dialog_content = "(Sebagai seorang Caelestite, pasti ada sesuatu yang bisa aku lakukan!)",
  ui_story_5068_50681301_32_option_content = "Force Boost!",
  ui_story_5068_50681301_33_dialog_content = "(Rebecca! Rebecca!)",
  ui_story_5068_50681301_34_dialog_content = "(... PlayerName? Apakah ini... salah satu kekuatanmu juga?)",
  ui_story_5068_50681301_35_dialog_content = "(Tolong dengarkan saja aku! Tidak ada waktu untuk menjelaskan!)",
  ui_story_5068_50681301_36_dialog_content = "(Sungguh maaf keluargamu harus berakhir seperti ini... Tapi percayalah padaku saat aku bilang ini bukan salahmu sama sekali!)",
  ui_story_5068_50681301_37_dialog_content = "(Bagaimana bisa kamu menjadi \"putri bencana\" ketika kamu telah menyakiti dirimu sendiri hanya untuk menyelamatkan pasienmu? Jika ada yang harus dikatakan, kamu adalah malaikat pelindung dari Umbraton!)",
  ui_story_5068_50681301_38_dialog_content = "(Jika kamu tidak percaya padaku, coba gunakan kekuatanmu untuk menyelamatkan Isa sekarang juga!)",
  ui_story_5068_50681301_39_dialog_content = "(Kekuatanku... Apakah benar aku bisa menggunakannya untuk menyelamatkannya?)",
  ui_story_5068_50681301_40_dialog_content = "(Jika aku bertarung dengan kekuatan penuh—)",
  ui_story_5068_50681301_41_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5068_50681301_42_dialog_content = "D... Direktur...",
  ui_story_5068_50681301_43_dialog_content = "Kamu pasti bisa, Rebecca!",
  ui_story_5068_50681301_44_dialog_content = "Isa!!!",
  ui_story_5068_50681301_45_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_46_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5068_50681301_47_dialog_content = "Berhenti melawan saja. Itu sama berbahayanya dengan sia-sia.",
  ui_story_5068_50681301_48_dialog_content = "Bahkan kamu pun tidak bisa menyembuhkan luka tembakan di kepala, Rebecca.",
  ui_story_5068_50681301_49_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_50_dialog_content = "…!!",
  ui_story_5068_50681301_51_dialog_content = "Isa—Tidak!",
  ui_story_5068_50681301_52_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5068_50681301_53_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_5068_50681301_54_dialog_content = "Urgh—! Siapa yang melakukan itu?!",
  ui_story_5068_50681301_55_dialog_content = "Sekarang saatnya, saudara-saudara!",
  ui_story_5068_50681301_56_dialog_content = "Ya!",
  ui_story_5068_50681301_57_dialog_content = "...",
  ui_story_5068_50681301_58_dialog_content = "?!",
  ui_story_5068_50681301_59_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_5068_50681301_60_dialog_content = "Ini kamu! Berani-beraninya menembakkan senjata kepadaku, Eleanor—!!!",
  ui_story_5068_50681301_61_dialog_content = "Apa? Kamu dengar semuanya? Atau mungkin aku salah cerita?",
  ui_story_5068_50681301_62_dialog_content = "Cukup!!",
  ui_story_5068_50681301_63_dialog_content = "Maaf muncul begitu terlambat, Bu Rebecca. Apakah kamu baik-baik saja?",
  ui_story_5068_50681301_64_dialog_content = "Ketika aku kembali ke Cloudrover Guild, yang kutemukan hanyalah ruangan kosong dan catatan tebusan... Jadi aku segera datang ke sini secepatnya.",
  ui_story_5068_50681301_65_dialog_content = "Aku baik-baik saja, Eleanor, tapi tolong periksa Isa.",
  ui_story_5068_50681301_66_dialog_content = "Isa! Apakah kamu baik-baik saja?!",
  ui_story_5068_50681301_67_dialog_content = "Kami sedang mencari kamu ketika Eleanor memberi tahu kami bahwa kamu diculik, jadi kami bergegas ke sini bersamanya!",
  ui_story_5068_50681301_68_dialog_content = "... Aku baik-baik saja! Bahkan... Aku lebih dari baik-baik saja! Saatnya untukku membalas kebaikan Serigala Hitam atas keramahtamahannya, jadi bersiaplah untuk bertarung!",
  ui_story_5068_50681301_69_dialog_content = "Tapi kamu terlihat sangat terluka, Isa! Kita harus segera keluar dari sini selagi ada kesempatan!",
  ui_story_5068_50681301_70_dialog_content = "PlayerName benar... Aku akan membuat jalan keluar dari sini!",
  ui_story_5068_50681301_71_dialog_content = "Aku bersamamu, Nona Rebecca!",
  ui_story_5068_50681301_72_dialog_content = "Baik, aku juga akan mendukung semua orang dalam pertempuran!",
  ui_story_5068_50681302_1_dialog_content = "Maafkan kami, Direktur... Kami membiarkan mereka lolos.",
  ui_story_5068_50681302_2_dialog_content = "...",
  ui_story_5068_50681302_3_dialog_content = "Direktur?",
  ui_story_5068_50681302_4_dialog_content = "Tak apa-apa. Aku tak keberatan bermain dengan mereka sedikit lebih lama, karena mereka sangat menikmati berjuang.",
  ui_story_5068_50681302_X4_dialog_content = "Aku bisa menghitung jumlah tempat yang bisa mereka kunjungi hanya dengan satu tangan. Mari kita siapkan hadiah sambutan yang bagus untuk mereka sebelum kita pergi ke sana...",
  ui_story_5068_50681302_X5_dialog_content = "Sudah saatnya kita mengeluarkan kartu as kita, sekarang persiapkan!",
  ui_story_5068_50681302_5_dialog_content = "Hari ini tak akan berbeda dari hari Keluarga Svanedona tewas... Semua ini karena kalian bodoh yang memaksaku melakukannya!",
  ui_story_5068_50681302_6_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5068_50681302_7_dialog_content = "Fiuh—Aku... Aku tidak pikir mereka mengejar kita lagi...",
  ui_story_5068_50681302_X7_dialog_content = "Harus kuakui, kalian tentara bayaran benar-benar bisa melindungi diri sendiri! Tapi, seharusnya kita khawatir tentang orang-orang yang melindungi pelarian kita, bukan...?",
  ui_story_5068_50681302_X8_dialog_content = "Kami semua profesional, tidak perlu khawatir tentang mereka. Mereka akan berkumpul kembali dengan kami dalam waktu dekat.",
  ui_story_5068_50681302_8_dialog_content = "Kita sudah berlari begitu lama... Apakah semua orang masih baik-baik saja?",
  ui_story_5068_50681302_9_dialog_content = "... Jangan berhenti dulu! Tempat ini tidak aman, dan Arte tidak akan membiarkan kita pergi begitu saja!",
  ui_story_5068_50681302_10_dialog_content = "...",
  ui_story_5068_50681302_11_dialog_content = "Bagaimana keadaanmu, Rebecca? Meskipun dengan lukaku, kamu masih terlihat lebih buruk daripada aku!",
  ui_story_5068_50681302_12_dialog_content = "Aku... aku akan baik-baik saja. Ayo kita pergi ke tempat yang aman dulu...",
  ui_story_5068_50681302_13_dialog_content = "Bertahanlah, Nona Rebecca!",
  ui_story_5068_50681302_14_dialog_content = "Ada beberapa gudang terbengkalai di depan. Kita bisa berhenti dan mengambil napas di sana!",
  ui_story_5068_50681302_15_dialog_content = "Aku dan anak buahku akan mengawasi, jadi silakan beristirahat. Kami tidak akan tinggal di sini lebih lama lagi.",
  ui_story_5068_50681302_16_dialog_content = "Biarkan aku membantu Anda duduk, Nona Rebecca...",
  ui_story_5068_50681302_17_dialog_content = "Tunggu! Jawab satu pertanyaan ini sekarang juga: siapa sebenarnya kamu—",
  ui_story_5068_50681302_18_dialog_content = "Isa!",
  ui_story_5068_50681302_19_dialog_content = "...",
  ui_story_5068_50681302_20_dialog_content = "Berhenti saja, Isa... Aku tidak ingin tahu.",
  ui_story_5068_50681302_21_dialog_content = "Eleanor sudah dua kali mempertaruhkan nyawanya untuk menyelamatkan saya dari Serigala Hitam... Itu saja yang perlu saya ketahui... Tidak lebih.",
  ui_story_5068_50681302_22_dialog_content = "Tapi ini juga salahnya! Dia alasan kita kehilangan keluarga kita!",
  ui_story_5068_50681302_23_dialog_content = "Itu bukan Eleanor yang saya kenal...",
  ui_story_5068_50681302_24_dialog_content = "Eleanor yang saya kenal merawat saya ketika saya pingsan... Dia mengobati luka pasien kami dan membuat sup untuk anak-anak di klinik kami. Dia—",
  ui_story_5068_50681302_25_dialog_content = "Nona Rebecca!",
  ui_story_5068_50681302_26_dialog_content = "Aku terharu karena kamu berpikir begitu baik tentangku... Tapi semakin kamu menyebutkan hal-hal ini, semakin besar rasa bersalah yang kurasakan.",
  ui_story_5068_50681302_27_dialog_content = "Aku... Aku punya pengakuan untuk dibuat—",
  ui_story_5068_50681302_28_dialog_content = "Tidak... Eleanor, tolong...",
  ui_story_5068_50681302_29_dialog_content = "Semuanya benar... Setiap katanya.",
  ui_story_5068_50681302_30_dialog_content = "Kau…?!",
  ui_story_5068_50681302_31_dialog_content = "Memang benar bahwa dulu saya merupakan anggota Black Wolves, dan saya diutus untuk menyusup ke dalam Keluarga Svanedona.",
  ui_story_5068_50681302_32_dialog_content = "Alasan saya mendekatimu adalah untuk menggali informasi darinya.",
  ui_story_5068_50681302_33_dialog_content = "Saya sangat menyesal, Nona Rebecca.",
  ui_story_5068_50681401_1_dialog_content = "Saya tidak bisa mengingat wajah kedua orang tua saya. Sepanjang yang bisa saya ingat, saya hidup dari hari ke hari, mencuri apa pun yang bisa saya dapatkan untuk memenuhi kebutuhan makan. Bahkan orang-orang di kawasan kumuh pun tidak tahan melihat saya.",
  ui_story_5068_50681401_2_dialog_content = "Saya berbaring di tumpukan sampah suatu hari, hampir mati kelaparan... Itulah saatnya Serigala Hitam membawa saya masuk.",
  ui_story_5068_50681401_3_dialog_content = "Dulu, Serigala Hitam sangat berbeda dari yang sekarang. Mereka seperti satu keluarga besar, dan aku bukan satu-satunya anak yang tak berdaya di antara mereka.",
  ui_story_5068_50681401_4_dialog_content = "Arte adalah orang yang memimpin perjuangan kita untuk bertahan hidup, dan mengajarkan kita untuk selalu menjaga satu sama lain.",
  ui_story_5068_50681401_5_dialog_content = "Perlahan tapi pasti, semakin banyak orang bergabung dengan Black Wolves. Tujuan Arte pun menjadi semakin ambisius, itulah mengapa kami mulai bertarung dengan geng-geng lain.",
  ui_story_5068_50681401_6_dialog_content = "Aku sangat marah ketika mendengar bahwa Keluarga Svanedona telah menyakiti saudara-saudaraku di Black Wolves. Aku pikir Svanedonas hanyalah penjahat yang mengintimidasi orang lemah... Bagaimanapun, siapa yang bisa memaafkan orang-orang yang menyakiti keluargaku sendiri?",
  ui_story_5068_50681401_7_dialog_content = "Tak lama kemudian, Arte memberi saya perintah untuk menyusup ke dalam Keluarga Svanedona dan mendekati Nona Rebecca. Saya harus menunggu waktu yang tepat untuk menculiknya...",
  ui_story_5068_50681401_8_dialog_content = "Tapi setelah menghabiskan hari demi hari bahagia bersamamu, ada sesuatu yang aneh mulai menghampiriku...",
  ui_story_5068_50681401_9_dialog_content = "Kamu memperlakukanku seperti keluarga. Kepercayaan dan kebaikanmu juga menyentuh hati anggota keluarga lainnya.",
  ui_story_5068_50681401_10_dialog_content = "...",
  ui_story_5068_50681401_11_dialog_content = "Bagi Serigala Hitam, terluka itu memalukan, tetapi berbeda dengan kamu dan keluargamu. Setiap kali aku terluka, kamu tidak pernah mengejek, tetapi selalu memberikan cinta dan kebaikan hati.",
  ui_story_5068_50681401_12_dialog_content = "Bagi saya, itulah arti sebenarnya menjadi sebuah keluarga.",
  ui_story_5068_50681401_13_dialog_content = "Sebelum aku tahu apa tujuan sebenarnya Arte, aku mencoba meyakinkan Arte untuk mendekatimu dengan cara yang lebih damai. Sayangnya, kita semua tahu bagaimana akhirnya.",
  ui_story_5068_50681401_14_dialog_content = "Saya bingung, dan tidak tahu harus berbuat apa—saya tidak bisa mengkhianati Black Wolves, tetapi saya juga tidak bisa memaksa diri untuk menyakiti Miss Rebecca dengan cara apa pun.",
  ui_story_5068_50681401_15_dialog_content = "Pada akhirnya, aku mengambil keputusan yang akan kusesali seumur hidupku—",
  ui_story_5068_50681401_16_dialog_content = "Aku kabur.",
  ui_story_5068_50681401_17_dialog_content = "Dan karena aku melarikan diri, Arte dan Serigala Hitam memiliki kesempatan untuk menyerang Keluarga Svanedona.",
  ui_story_5068_50681401_18_dialog_content = "Aku sangat berharap Miss Rebecca baik-baik saja. Ketika akhirnya aku kembali, aku menemukannya berhadapan langsung dengan Arte yang haus darah.",
  ui_story_5068_50681401_19_dialog_content = "Dia berteriak gila dengan suara keras, mengatakan hal-hal seperti, \"Bagaimana berani kalian meremehkan saya! Pada nasib Black Wolves!!!\" Dia adalah orang yang sama sekali berbeda dari Arte yang pernah saya kenal.",
  ui_story_5068_50681401_20_dialog_content = "Dia selalu sangat melindungi keluarganya di masa lalu. Aku tidak tahu apa yang terjadi hingga membuatnya berubah seperti itu; yang aku tahu adalah aku harus menyelamatkan Nona Rebecca dan membawanya keluar dari sana secepatnya.",
  ui_story_5068_50681401_21_dialog_content = "...",
  ui_story_5068_50681401_22_dialog_content = "Kamu pikir mengatakan semua ini akan membuat kami memaafkanmu? Rebecca dan aku kehilangan seluruh keluarga kami, pembunuh!",
  ui_story_5068_50681401_23_dialog_content = "...",
  ui_story_5068_50681401_24_dialog_content = "Rebecca, aku tahu aku tidak pantas mendapatkan pengampunanmu, apalagi kepercayaan dan kebaikan yang telah kau tunjukkan padaku selama setahun terakhir ini.",
  ui_story_5068_50681401_25_dialog_content = "Seorang seperti aku tidak pantas untuk hidup...",
  ui_story_5068_50681401_26_dialog_content = "Jadi tolong bunuh saja aku, Nona Rebecca!",
  ui_story_5068_50681401_27_dialog_content = "...",
  ui_story_5068_50681401_28_dialog_content = "Berani-beraninya kamu! Kamu tahu Rebecca tidak akan pernah melakukan hal seperti itu! Bahkan sekarang, kamu masih saja memanfaatkan kebaikannya, kamu—",
  ui_story_5068_50681401_29_dialog_content = "Eleanor, pernahkah kamu mempertimbangkan bagaimana kehidupan Rebecca jika dia membunuhmu?",
  ui_story_5068_50681401_30_dialog_content = "Tapi aku tidak pantas mendapatkan yang lebih baik!",
  ui_story_5068_50681401_31_dialog_content = "Jika itu bisa membuatnya merasa lebih baik, walau hanya sedikit saja...",
  ui_story_5068_50681401_32_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5068_50681401_33_dialog_content = "Apa yang terjadi di luar sana...?",
  ui_story_5068_50681401_34_dialog_content = "Ada yang mendekat! Kita harus segera keluar dari sini!",
  ui_story_5068_50681401_35_dialog_content = "Tidak... Bagaimana Serigala Hitam bisa mengejar kita begitu cepat?!",
  ui_story_5068_50681401_36_dialog_content = "Ayo, Nona Rebecca!",
  ui_story_5068_50681401_37_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5068_50681401_38_dialog_content = "Di sini!",
  ui_story_5068_50681401_39_dialog_content = "Itu lebih mudah dari yang saya harapkan. Sepertinya permainan kucing dan tikus kita sudah berakhir sekarang.",
  ui_story_5068_50681401_40_dialog_content = "Cukup dengan perjuangan sia-sia ini. Ikutlah dengan tenang, dan mungkin saja aku akan meninggalkan beberapa mayat untuk dikubur nantinya!",
  ui_story_5068_50681401_41_dialog_content = "Tak ada yang mau ikut dengan sampah seperti kalian! Tangkap dia, teman-teman!",
  ui_story_5068_50681401_42_dialog_content = "Baik!",
  ui_story_5068_50681401_43_dialog_content = "Awas! Dia membawa sesuatu yang berbahaya di tangannya!",
  ui_story_5068_50681402_1_dialog_content = "<color=#e8d9bb>Desis—</color>",
  ui_story_5068_50681402_2_dialog_content = "Uhuk, uhuk...",
  ui_story_5068_50681402_3_dialog_content = "Kabut hitam ini...",
  ui_story_5068_50681402_4_dialog_content = "Apa yang terjadi? Bukankah Rebecca kebal terhadap kabut hitam?!",
  ui_story_5068_50681402_5_dialog_content = "Aku sungguh kasihan padamu, Rebecca. Lahir dalam keluarga dengan kemampuan bawaan yang luar biasa... Aku heran bahwa tidak ada satupun dari kalian yang pernah berpikir untuk meneliti rahasia di balik kekuatan kalian.",
  ui_story_5068_50681402_6_dialog_content = "Tapi tidak apa-apa. Saya sudah melakukan banyak hal itu untuk Anda, dan dengan bangga saya mempersembahkan hasil penelitian saya—",
  ui_story_5068_50681402_7_dialog_content = "Kabut hitam yang mampu menetralisir racun Anda.",
  ui_story_5068_50681402_8_dialog_content = "Tapi... bagaimana...",
  ui_story_5068_50681402_9_dialog_content = "Heheh, tidakkah kamu merasa ada sesuatu yang spesial tentang kabut ini? Sesuatu yang sangat familiar, mungkin?",
  ui_story_5068_50681402_10_dialog_content = "Apa... Apa yang kamu coba katakan...?",
  ui_story_5068_50681402_11_dialog_content = "Mengingatkanmu pada pelukan hangat orang tuamu, 'kan?",
  ui_story_5068_50681402_12_dialog_content = "Apa sih yang dibicarakan wanita gila ini?!",
  ui_story_5068_50681402_13_dialog_content = "Tidak seperti anggota keluarga kamu yang pelit, saya sangat senang untuk berbagi formula kabut hitam ini dengan kamu.",
  ui_story_5068_50681402_14_dialog_content = "Kabut ini... dulunya adalah orang tua tercinta Anda.",
  ui_story_5068_50681402_15_dialog_content = "—?!",
  ui_story_5068_50681402_16_dialog_content = "Setelah setahun penuh penelitian, akhirnya saya mengungkap rahasia Keluarga Svanedona: orang tua dalam keluarga Anda memiliki efek netralisasi, bahkan korosif terhadap kemampuan anak-anak mereka.",
  ui_story_5068_50681402_17_dialog_content = "Ini semua berkat ini, Rebecca, aku bisa membuatmu berperilaku baik. Seharusnya aku berterima kasih pada orang tuamu karena telah menghemat banyak usaha untukku.",
  ui_story_5068_50681402_18_dialog_content = "Bagaimana bisa kau melakukan sesuatu yang begitu tidak berperasaan? Menggunakan keluarganya melawan dia...",
  ui_story_5068_50681402_19_dialog_content = "Arte! Apakah kamu... Apakah kamu kehilangan akal?! Tidakkah kamu ingat apa yang selalu kamu katakan kepada kami?! \"Orang terburuk di dunia adalah mereka yang dengan tidak tahu malu memangsa yang lemah!\"",
  ui_story_5068_50681402_20_dialog_content = "Lihat dirimu sekarang! Bahkan setahun yang lalu, aku masih merasa simpati padamu, karena kukira kamu hanya ingin balas dendam. Tapi sekarang aku melihat bahwa kamu adalah orang yang sama sekali berbeda!",
  ui_story_5068_50681402_21_dialog_content = "Apa yang membuatmu berubah seperti ini? Apakah karena kegembiraan akan kekuasaan dan pembunuhan?",
  ui_story_5068_50681402_22_dialog_content = "Atau mungkin kau memang selalu seperti ini? Apakah kau telah memanfaatkan kami sejak awal...?",
  ui_story_5068_50681402_23_dialog_content = "Heheh... Hahahaha! Apa yang kamu tahu?!",
  ui_story_5068_50681402_24_dialog_content = "Aku menemukanmu kelaparan di tempat sampah, seorang malang yang bahkan anjing pun meremehkan! Di mana kamu akan berada sekarang jika bukan karena aku?!",
  ui_story_5068_50681402_25_dialog_content = "Serigala Hitam tidak akan pernah bertahan selama ini jika aku tidak berbohong, menipu, dan mencuri setiap langkah yang kulalui!",
  ui_story_5068_50681402_26_dialog_content = "Apakah itu sebabnya kau menjadikan saudara-saudara kita di Black Wolves sebagai alat untuk keuntungan pribadimu?!",
  ui_story_5068_50681402_27_dialog_content = "Jika begitu, maka mengkhianati kamu adalah keputusan terpintar yang pernah aku buat dalam hidupku.",
  ui_story_5068_50681402_28_dialog_content = "Cukup!",
  ui_story_5068_50681402_29_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5068_50681402_30_dialog_content = "... Pengkhianat tak berhak mengkritik Black Wolves.",
  ui_story_5068_50681402_31_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5068_50681402_32_dialog_content = "Heh. Sepertinya kemampuan menembak Anda berkarat, Direktur.",
  ui_story_5068_50681402_33_dialog_content = "Cih.",
  ui_story_5068_50681402_34_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_5068_50681402_35_dialog_content = "Tidak... Berhenti... Argh...",
  ui_story_5068_50681402_36_dialog_content = "Tak ada gunanya berjuang sampai titik darah penghabisan, Rebecca.",
  ui_story_5068_50681402_37_dialog_content = "Mati atau hidup, aku masih bisa memanfaatkan kalian untuk melanjutkan penelitianku, jadi jangan bilang aku tidak pernah memberi kesempatan untuk bertahan hidup! Semua kalian akan mati di sini!",
  ui_story_5068_50681402_38_dialog_content = "... Awas, Nona Rebecca!",
  ui_story_5068_50681402_39_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5068_50681402_40_dialog_content = "<color=#e8d9bb>Menyembur!</color>",
  ui_story_5068_50681402_41_dialog_content = "<size=50>Eleanor?!</size>",
  ui_story_5068_50681402_42_dialog_content = "Tidak... Kenapa kalian hanya berdiri saja?! Musuh ada di depan kalian, segera tembak!",
  ui_story_5068_50681402_43_dialog_content = "Tembak!",
  ui_story_5068_50681402_44_dialog_content = "Ayo tangkap mereka!",
  ui_story_5068_50681402_45_dialog_content = "Siap, Pak!!!",
  ui_story_5068_50681402_46_dialog_content = "Eleanor... Bisakah kamu mendengarku...?",
  ui_story_5068_50681402_47_dialog_content = "Rebecca... Aku tak pernah menyangka akan mendengar kau... memanggil namaku lagi... Aku pikir kau akan meninggalkanku.",
  ui_story_5068_50681402_48_dialog_content = "Tapi jika aku bisa mati... di pelukanmu... maka aku tidak memiliki penyesalan...",
  ui_story_5068_50681402_49_dialog_content = "J-Jangan mengatakan hal seperti itu! Aku bisa menyembuhkanmu, beri aku waktu sebentar...",
  ui_story_5068_50681402_50_dialog_content = "Jangan... Sudah terlambat untukku... Jangan sia-siakan kekuatanmu... untuk seseorang sepertiku...",
  ui_story_5068_50681402_51_dialog_content = "Keluar saja dari sini... dan temukan tempat... di mana mereka tidak akan pernah menemukanmu...",
  ui_story_5068_50681402_52_dialog_content = "Jangan lupa, aku seorang dokter... Aku tidak akan pernah meninggalkan pasienku... terutama kamu.",
  ui_story_5068_50681402_53_dialog_content = "Argh! Aku masih belum bisa menggunakan kekuatan penuhku... Tapi bagaimana lagi cara untuk pulih...?",
  ui_story_5068_50681402_54_dialog_content = "Tunggu... Itu dia! Toples dan botol-botol di klinik! Saya hanya perlu kembali dan mengisi ulang racun serta serum saya, lalu saya bisa—",
  ui_story_5068_50681402_55_dialog_content = "Klinik... tidak aman...",
  ui_story_5068_50681402_56_dialog_content = "Tidak perlu... mempertaruhkan nyawa demi saya...",
  ui_story_5068_50681402_57_dialog_content = "Cukup... lari...",
  ui_story_5068_50681402_58_dialog_content = "Dia mengejarmu, Rebecca! Aku akan menyuruh timku melindungi Eleanor sementara kamu kabur!",
  ui_story_5068_50681402_59_dialog_content = "PlayerName, bawa Rebecca dan cari jalan keluar dari sini! Aku mengandalkanmu!",
  ui_story_5068_50681402_60_dialog_content = "Baiklah! Ayo pergi, Rebecca!",
  ui_story_5068_50681402_61_dialog_content = "Mau kabur, ya?",
  ui_story_5068_50681402_62_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5068_50681402_63_dialog_content = "Aku... Aku tidak akan membiarkanmu menghalangi Rebecca! Pertarunganmu... adalah denganku!",
  ui_story_5068_50681402_64_dialog_content = "Jangan memuji diri sendiri.",
  ui_story_5068_50681402_65_dialog_content = "<color=#e8d9bb>Dor, dor!!!</color>",
  ui_story_5068_50681402_66_dialog_content = "Argh…",
  ui_story_5068_50681402_67_dialog_content = "—!!!",
  ui_story_5068_50681402_68_dialog_content = "L... Lari...",
  ui_story_5068_50681402_69_dialog_content = "Eleanor...",
  ui_story_5068_50681402_70_dialog_content = "... Semuanya mundur! Keluar dari sini, Rebecca!",
  ui_story_5068_50681402_71_dialog_content = "Hraaagh—!!",
  ui_story_5068_50681402_72_dialog_content = "*Batuk-batuk*",
  ui_story_5068_50681402_73_dialog_content = "Beraninya kamu menggigitku!",
  ui_story_5068_50681402_74_dialog_content = "Awas, kalian yang lain! Beginilah cara kita menghadapi pengkhianat—",
  ui_story_5068_50681402_75_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor! Dor!</color>",
  ui_story_5068_50681402_76_dialog_content = "...",
  ui_story_5068_50681402_77_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_5068_50681402_78_dialog_content = "Ah—! Ayah? Ayah!!!",
  ui_story_5068_50681402_79_dialog_content = "Lari... Cepat...",
  ui_story_5068_50681402_80_dialog_content = "Rebecca... Lari!",
  ui_story_5068_50681402_81_dialog_content = "<color=#e8d9bb>砰砰砰砰砰砰！！！</color>",
  ui_story_5068_50681402_82_dialog_content = "Rebecca!",
  ui_story_5068_50681402_83_dialog_content = "Jangan menengok ke belakang, Rebecca! Apakah kamu mendengar?!",
  ui_story_5068_50681402_84_dialog_content = "... Jangan biarkan pengorbanan Eleanor sia-sia.",
  ui_story_5068_50681402_85_dialog_content = "Di mana Eleanor, Isa? Bukankah kamu berjanji untuk menyelamatkannya?",
  ui_story_5068_50681402_86_dialog_content = "Dia... sudah tak bisa diselamatkan lagi, Rebecca...",
  ui_story_5068_50681402_87_dialog_content = "Tapi bagaimana bisa? Aku bahkan belum mulai mengobatinya...",
  ui_story_5068_50681402_88_dialog_content = "N-Nggak... Aku nggak akan meninggalkan Eleanor seperti ini...",
  ui_story_5068_50681402_89_dialog_content = "Rebecca... Sudah terlambat sekarang.",
  ui_story_5068_50681402_90_dialog_content = "PlayerName... Kamu juga berpikir aku gagal sebagai dokter untuknya, ya...?",
  ui_story_5068_50681402_91_dialog_content = "Ini semua salahku karena tidak bisa menggunakan kekuatanku. Jika bukan karena aku, Eleanor masih...",
  ui_story_5068_50681402_92_dialog_content = "Semua kerja keras saya, semua penelitian saya, semuanya demi agar saya bisa menyembuhkan dan melindungi orang lain...",
  ui_story_5068_50681402_93_dialog_content = "Jadi kenapa... Kenapa aku masih begitu tidak berguna? Kenapa harus seperti ini?",
  ui_story_5068_50681402_94_dialog_content = "Tunggu, benar juga. Aku masih punya banyak botol racun dan serum. Jika aku bisa menggunakannya untuk mendapatkan kembali kekuatanku, aku bisa menyelamatkan Eleanor dan semua orang lainnya...!",
  ui_story_5068_50681402_95_dialog_content = "Hah? Kamu mau ke mana, Rebecca?!",
  ui_story_5068_50681501_1_dialog_content = "Tunggu, Rebecca! Kamu mau ke mana?!",
  ui_story_5068_50681501_2_dialog_content = "Kita sudah berusaha keras untuk melarikan diri, dan Black Wolves bisa muncul kapan saja. Kita harus segera kembali ke Cloudrover Guild!",
  ui_story_5068_50681501_3_dialog_content = "Aku harus... mengisi ulang racun... dan serumku...",
  ui_story_5068_50681501_4_dialog_content = "... Tolong jangan menakutiku seperti ini, Rebecca...",
  ui_story_5068_50681501_5_dialog_content = "Aku tahu kamu merasa sangat kesakitan setelah kehilangan Eleanor, tapi dia melakukan itu untuk menyelamatkanmu! Jadi tolong, lihatlah aku.",
  ui_story_5068_50681501_6_dialog_content = "Aku harus... mengisi ulang racun ku...",
  ui_story_5068_50681501_7_dialog_content = "Dia terus membicarakan tentang mengisi ulang racunnya... Sepertinya dia mencoba kembali ke klinik.",
  ui_story_5068_50681501_8_dialog_content = "Tapi, apakah dia... benar-benar akan baik-baik saja seperti ini?",
  ui_story_5068_50681501_9_dialog_content = "...",
  ui_story_5068_50681501_10_dialog_content = "Rebecca!",
  ui_story_5068_50681501_11_dialog_content = "<color=#e8d9bb>Beberapa jarak jauh</color>",
  ui_story_5068_50681501_12_dialog_content = "Direktur... Kamu yakin baik-baik saja?",
  ui_story_5068_50681501_13_dialog_content = "Kamu pikir luka-luka ini bisa menghentikanku? Apakah kamu lupa bagaimana kita berhasil bertahan selama ini?",
  ui_story_5068_50681501_14_dialog_content = "Katakan padaku, sudah siap belum?",
  ui_story_5068_50681501_15_dialog_content = "Ya, Direktur.",
  ui_story_5068_50681501_16_dialog_content = "Cukup sampai di sini. Aku sudah selesai menangani semua hal yang sia-sia ini. Aku akan mengambil apa yang kuinginkan setelah dia hancur.",
  ui_story_5068_50681501_17_dialog_content = "Aku bertanya-tanya... Apakah kembang api ku akan membuat tumpukan sampah ini menjadi lebih indah?",
  ui_story_5068_50681501_18_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5068_50681501_19_dialog_content = "Ahh—",
  ui_story_5068_50681501_20_dialog_content = "Rebecca! Isa!",
  ui_story_5068_50681501_21_dialog_content = "*batuk-batuk* ... Isa?!",
  ui_story_5068_50681501_22_dialog_content = "...",
  ui_story_5068_50681501_23_dialog_content = "Isa! Bangun...!",
  ui_story_5068_50681501_24_dialog_content = "Racunku... akan menyelamatkan semua orang...",
  ui_story_5068_50681501_25_dialog_content = "Berhenti, Rebecca! Klinik itu akan meledak! Jangan masuk ke sana!!!",
  ui_story_5068_50681501_26_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5068_50681501_27_dialog_content = "Meledak... Heheh...",
  ui_story_5068_50681501_28_dialog_content = "Eleanor... Pada akhirnya... Aku bahkan tak mampu menyelamatkan klinik kami...",
  ui_story_5068_50681501_29_dialog_content = "...? A-Anting-antingku! Di mana anting-anting yang Eleanor berikan padaku?!",
  ui_story_5068_50681501_30_dialog_content = "...",
  ui_story_5068_50681501_31_dialog_content = "Mereka pergi... semuanya hilang.",
  ui_story_5068_50681501_32_dialog_content = "Rebecca?!",
  ui_story_5068_50681501_33_dialog_content = "Kenapa? Kenapa harus seperti ini...?",
  ui_story_5068_50681501_34_dialog_content = "Keluargaku hilang, Eleanor hilang, rumah kita hilang, bahkan anting yang dibuatnya untukku juga hilang—Aku tidak punya apa-apa lagi.",
  ui_story_5068_50681501_35_dialog_content = "Itu tidak benar, Rebecca! Bagaimana dengan Isa? Kamu masih punya saudarimu!",
  ui_story_5068_50681501_36_dialog_content = "Ugh...",
  ui_story_5068_50681501_37_dialog_content = "Re... becca...",
  ui_story_5068_50681501_38_dialog_content = "... Syukurlah, dia masih hidup!",
  ui_story_5068_50681501_39_dialog_content = "Terlalu berbahaya di sana, Rebecca! Isa masih membutuhkan kamu, jadi tolong kembali!",
  ui_story_5068_50681501_40_dialog_content = "Isa... butuh aku...?",
  ui_story_5068_50681501_41_dialog_content = "A-Adikku masih membutuhkanku!",
  ui_story_5068_50681501_42_dialog_content = "(Apakah kamu yakin? Lagi pula, siapa yang mungkin membutuhkan seseorang yang hanya membawa rasa sakit dan penderitaan di mana pun dia pergi?)",
  ui_story_5068_50681501_43_dialog_content = "Itu aku... Akulah yang melakukan semua ini...",
  ui_story_5068_50681501_44_dialog_content = "(\"Kemampuan istimewa\" yang kau sebut itu penyebab semua penderitaan ini. Apakah kau benar-benar merasa pantas untuk terus hidup?)",
  ui_story_5068_50681501_45_dialog_content = "Betul... Kekuatanku lah yang membawa Serigala Hitam ke depan pintu keluarga kami. Karena aku, mereka semua...",
  ui_story_5068_50681501_46_dialog_content = "Tenagaku lah yang menciptakan kabut hitam yang membuat begitu banyak orang di pemukiman kumuh sakit...",
  ui_story_5068_50681501_47_dialog_content = "(Bagaimana dengan Eleanor? Kematian dia juga ada di tanganmu, dan jangan lupakan saudara perempuanmu yang sudah setengah mati.)",
  ui_story_5068_50681501_48_dialog_content = "(Kamu tidak benar-benar berpikir kamu bisa mengalahkan Serigala Hitam dengan kekuatan terkutuk seperti milikmu, bukan?)",
  ui_story_5068_50681501_49_dialog_content = "(Dan bahkan jika kamu melakukannya, siapa yang bisa menjamin tidak ada orang lain yang mencari kekuatanmu? Kamu sudah kehilangan Eleanor; siapa yang akan membayar harga di lain waktu? Orang-orang di pemukiman kumuh? Isa?)",
  ui_story_5068_50681501_50_dialog_content = "Tidak! Aku tak akan membiarkan itu terjadi... Tapi bagaimana... Bagaimana aku bisa melindungi mereka?",
  ui_story_5068_50681501_51_dialog_content = "(Heheh, jawabannya sederhana. Yang kamu perlu lakukan...)",
  ui_story_5068_50681501_52_dialog_content = "(Hilangkan keberadaanmu dari dunia ini. Setelah kamu pergi, semuanya akan baik-baik saja...)",
  ui_story_5068_50681501_53_dialog_content = "*batuk* Argh... Itu sakit!",
  ui_story_5068_50681501_54_dialog_content = "Kau sudah bangun, Isa!",
  ui_story_5068_50681501_55_dialog_content = "Bodoh... Berhenti mengkhawatirkan aku... Rebecca lah yang butuh... Argh—",
  ui_story_5068_50681501_56_dialog_content = "Berhenti bergerak! Kamu hanya akan kehilangan lebih banyak darah jika kamu melakukannya...",
  ui_story_5068_50681501_57_dialog_content = "Kamu harus menghentikannya... Sepertinya dia akan melakukan sesuatu yang ceroboh...",
  ui_story_5068_50681501_58_dialog_content = "A-Aku ini kakaknya... Aku tahu sifatnya, sekarang pergi hentikan dia...",
  ui_story_5068_50681501_59_dialog_content = "Ba-baik!",
  ui_story_5068_50681501_60_dialog_content = "Rebecca!",
  ui_story_5068_50681501_61_dialog_content = "Rebecca? Apa yang sedang...?",
  ui_story_5068_50681501_62_dialog_content = "... Jangan mendekat!",
  ui_story_5068_50681501_63_dialog_content = "Di sini berbahaya.",
  ui_story_5068_50681501_64_dialog_content = "Apa yang kau rencanakan?",
  ui_story_5068_50681501_65_dialog_content = "... Satu-satunya hal yang bisa kulakukan untuk menghentikan rasa sakit pada orang-orang di sekitarku.",
  ui_story_5068_50681501_66_dialog_content = "K-Kamu menyerap semua racun ini?!",
  ui_story_5068_50681501_67_dialog_content = "Tapi tubuhmu... Benarkah bisa menangani sebanyak itu?!",
  ui_story_5068_50681501_68_dialog_content = "Aku baik-baik saja... Jangan khawatir. Tidak sakit sama sekali...",
  ui_story_5068_50681501_69_dialog_content = "Um...!",
  ui_story_5068_50681501_70_dialog_content = "Hentikan, Rebecca! Kamu akan mati jika tidak!",
  ui_story_5068_50681501_71_dialog_content = "Benar... Aku melakukan ini demi kepentingan semua orang...",
  ui_story_5068_50681501_72_dialog_content = "PlayerName... Seharusnya aku sudah mati lama waktu lalu. Aku tidak tahu apa yang membuatku berpikir bahwa aku bisa melindungi siapa pun...",
  ui_story_5068_50681501_73_dialog_content = "Jangan bilang begitu! Kamu berjanji padaku bahwa kamu tidak akan menyakiti dirimu lagi!",
  ui_story_5068_50681501_74_dialog_content = "Heh, sepertinya aku ingkar janji... Ini adalah Umbraton, setelah semua. Kamu tidak bisa percaya semua yang kamu dengar di kota ini.",
  ui_story_5068_50681501_75_dialog_content = "Umbraton tidak ada hubungannya dengan ini, Rebecca! Kamu bukan orang seperti itu, jadi berhenti saja! Pikirkan tentang Isa! Akhirnya kamu punya kesempatan untuk bersama adikmu lagi!",
  ui_story_5068_50681501_76_dialog_content = "Urgh... Batuk, batuk...",
  ui_story_5068_50681501_77_dialog_content = "Isa... Maaf, tapi... Bisakah kamu... mengawasi dia untukku...?",
  ui_story_5068_50681501_78_dialog_content = "Tolong beritahu dia bahwa aku minta maaf... Dan ini adalah satu-satunya cara untuk menghentikan semuanya. Aku melakukan ini untuk dia juga.",
  ui_story_5068_50681501_79_dialog_content = "(Benar. Jika kamu ingin ini berakhir, teruslah menyerap racun ini! Serap semuanya!!!)",
  ui_story_5068_50681501_80_dialog_content = "PlayerName... Tolong... Bawa kakakku keluar dari sini.",
  ui_story_5068_50681501_81_dialog_content = "Rebecca...",
  ui_story_5068_50681501_82_dialog_content = "Pergi... Sekarang—!!",
  ui_story_5068_50681501_83_dialog_content = "Ahhhh—!!!",
  ui_story_5068_50681501_84_dialog_content = "Seharusnya cukup, Rebecca...",
  ui_story_5068_50681501_85_dialog_content = "Serahkan sisanya padaku.",
  ui_story_5068_50681501_86_dialog_content = "Direktur! Rebecca masih hidup, dan sepertinya dia telah menyerap sejumlah besar racun?",
  ui_story_5068_50681501_87_dialog_content = "Tapi bagaimana?! Darimana dia bisa menemukan racun sebanyak itu...?",
  ui_story_5068_50681501_88_dialog_content = "Ini dari guci-guci yang pecah itu... Tubuhnya mulai berubah karena menyerap begitu banyaknya!",
  ui_story_5068_50681501_89_dialog_content = "... Jadi, dia menggunakan racun dari toples-toples itu sebagai \"penawar\"?",
  ui_story_5068_50681501_90_dialog_content = "Saya rasa saya tidak akan bisa mengendalikannya setelah dia mengambil semua racun itu... Sepertinya—",
  ui_story_5068_50681501_91_dialog_content = "\"Sepertinya pilihan satu-satunya adalah kabur.\" Apakah itu yang ingin kamu katakan?",
  ui_story_5068_50681501_92_dialog_content = "Sheol...",
  ui_story_5068_50681501_93_dialog_content = "Periksa situasi di sekitar klinik dan laporkan kembali padaku! Tetap aman di luar sana!",
  ui_story_5068_50681501_94_dialog_content = "Ya, Nona Sheol!",
  ui_story_5068_50681501_95_dialog_content = "Jadi, kamu masih ingat aku ternyata, Arte dari Serigala Hitam.",
  ui_story_5068_50681501_96_dialog_content = "... Klinik yang bobrok seperti ini seharusnya tidak menarik minat kamu atau Cloudrover Guild. Mengapa kamu membawa orang-orangmu ke sini?",
  ui_story_5068_50681501_97_dialog_content = "\"Seharusnya tidak menarik bagi kita,\" kata kamu? Si Isa yang nakal itu terbaring terluka di tanah, dan PlayerName sepertinya juga dalam bahaya yang sangat besar.",
  ui_story_5068_50681501_98_dialog_content = "Katakan padaku, bagaimana aku harus menangani ini sesuai dengan aturan kita?",
  ui_story_5068_50681501_99_dialog_content = "Berdasarkan aturan, Cloudrover Guild tidak memiliki wewenang di permukiman kumuh ini.",
  ui_story_5068_50681501_100_dialog_content = "Maaf mengecewakan Anda, tetapi mulai hari ini, Cloudrover Guild bertanggung jawab atas klinik ini.",
  ui_story_5068_50681501_101_dialog_content = "Sekarang bagaimana Anda akan membayar kami atas apa yang telah Anda lakukan pada salah satu dokter kami?",
  ui_story_5068_50681501_102_dialog_content = "...",
  ui_story_5068_50681501_103_dialog_content = "Lady Sheol! Isa dan PlayerName aman untuk saat ini, tetapi situasi Rebecca tampaknya tidak terlalu baik! Sisanya dari orang-orang kita sudah mundur!",
  ui_story_5068_50681501_104_dialog_content = "Jangan bilang…",
  ui_story_5068_50681501_105_dialog_content = "Nona Sheol! Akhirnya kamu di sini!",
  ui_story_5068_50681501_106_dialog_content = "L-Lady Sheol! Ini Rebecca... Kamu harus menyelamatkannya—",
  ui_story_5068_50681501_107_dialog_content = "Mati—!!!",
  ui_story_5068_50681501_108_dialog_content = "... Kasihan gadis itu. Lihat saja apa yang telah mereka lakukan padanya.",
  ui_story_5068_50681501_109_dialog_content = "Direktur! Haruskah kita... mundur untuk sementara waktu?",
  ui_story_5068_50681501_110_dialog_content = "Tidak! Gunakan bom kabut hitam!",
  ui_story_5068_50681501_111_dialog_content = "<color=#e8d9bb>Desis—</color>",
  ui_story_5068_50681501_112_dialog_content = "Tidak bekerja?! Tapi bagaimana—",
  ui_story_5068_50681501_113_dialog_content = "ARTE!!!",
  ui_story_5068_50681501_114_dialog_content = "Aku punya pekerjaan baru untukmu, PlayerName! Arahkan pasukan kita dalam pertempuran!",
  ui_story_5068_50681501_115_dialog_content = "Rebecca butuh bantuan kita sekarang!",
  ui_story_5068_50681501_116_dialog_content = "... G-Mengerti!",
  ui_story_5068_50681502_1_dialog_content = "Lemparkan lebih banyak bom, kalian bodoh! Buang semua yang kita punya kepadanya!",
  ui_story_5068_50681502_2_dialog_content = "Tapi Direktur! Jika kita menggunakan sebanyak itu sekaligus, perlengkapan pelindung kita tidak akan menyelamatkan kita! Selain itu, semua orang sudah...",
  ui_story_5068_50681502_3_dialog_content = "Jangan tanya saya! Kita tidak bisa membiarkan wanita gila itu mengejar kita!",
  ui_story_5068_50681502_4_dialog_content = "*batuk-batuk* T-Terlambat, kita sudah menghirupnya... Argh...",
  ui_story_5068_50681502_5_dialog_content = "...",
  ui_story_5068_50681502_6_dialog_content = "Kamu di sana! Bawa beberapa pejuang kita dan jangan biarkan Arte kabur. Sisanya, bantu bersihkan kekacauan ini.",
  ui_story_5068_50681502_7_dialog_content = "Paham!",
  ui_story_5068_50681502_8_dialog_content = "Re... Rebecca...",
  ui_story_5068_50681502_9_dialog_content = "Ini aku... Isa... Tolong bangun...",
  ui_story_5068_50681502_10_dialog_content = "...",
  ui_story_5068_50681502_11_dialog_content = "Urgh... Di mana... aku...?",
  ui_story_5068_50681502_12_dialog_content = "Rebecca! Akhirnya kamu bangun!",
  ui_story_5068_50681502_13_dialog_content = "Syukurlah—Aku pikir aku kehilangan kamu lagi, Rebecca!",
  ui_story_5068_50681502_14_dialog_content = "—!!",
  ui_story_5068_50681502_15_dialog_content = "Tunggu, Rebecca! K-Kemana kamu pergi?!",
  ui_story_5068_50681502_16_dialog_content = "J-Jangan dekat-dekat denganku!",
  ui_story_5068_50681502_17_dialog_content = "Sepertinya barusan aku berubah menjadi sesuatu yang lain... Kabut ini, dan semua orang yang terluka ini... Apakah aku yang melakukannya?",
  ui_story_5068_50681502_18_dialog_content = "Yang aku inginkan hanyalah mengakhiri semuanya, tapi malah aku menyakiti semua orang lagi... Aku memang tidak ada harapan, bukan? Aku tidak ingin merepotkan semua orang lagi, jadi biarkan aku sendiri—",
  ui_story_5068_50681502_19_dialog_content = "Jangan bodoh, Rebecca!",
  ui_story_5068_50681502_20_dialog_content = "Isa?!",
  ui_story_5068_50681502_21_dialog_content = "Tidak! Lepaskan aku! Tubuhku—ini penuh dengan racun!",
  ui_story_5068_50681502_22_dialog_content = "Aku tak akan melepaskan! Bahkan jika aku mati sekalipun!",
  ui_story_5068_50681502_23_dialog_content = "Kamu tidak ingin membuat masalah lagi untuk semua orang? Sejak kapan aku menjadi semua orang?! Aku ini kakakmu! Kamu bisa membuat masalah sebanyak yang kamu mau untukku, dan aku tetap tidak keberatan!",
  ui_story_5068_50681502_24_dialog_content = "Memintaku untuk meninggalkanmu setelah mencarimu begitu lama... Itu satu hal yang tidak bisa aku lakukan!",
  ui_story_5068_50681502_25_dialog_content = "Mau tahu sesuatu? Aku menulis daftar semua hal yang ingin kulakukan bersamamu saat kita bertemu lagi! Dan percayalah, daftarnya panjang!",
  ui_story_5068_50681502_26_dialog_content = "Aku ingin terus membelikanmu banyak barang seperti sebelumnya, dan mendandanimu dengan pakaian cantik! Aku—",
  ui_story_5068_50681502_27_dialog_content = "Aku tak akan kehilanganmu lagi! Kamu juga tidak boleh meninggalkanku!",
  ui_story_5068_50681502_28_dialog_content = "Itu perintah dari kakakmu, jadi kamu harus mendengarkan! Kau dengar, Rebecca?!",
  ui_story_5068_50681502_29_dialog_content = "Aku... aku juga ingin itu, Isa. Aku ingin hidup seperti yang baru saja kamu deskripsikan, tapi sudah terlambat sekarang. Aku sudah menyerap terlalu banyak racun, dan sebentar lagi aku akan...",
  ui_story_5068_50681502_30_dialog_content = "Aku hanya ingin menemukan tempat yang sepi dan kosong di mana aku bisa mati sendirian.",
  ui_story_5068_50681502_31_dialog_content = "Meskipun begitu... Aku akan tetap bersamamu, apapun yang terjadi!",
  ui_story_5068_50681502_32_dialog_content = "Kamu ingin tempat yang nyaman dan tenang? Aku akan membantumu mencari satu! Setelah itu...",
  ui_story_5068_50681502_33_dialog_content = "Setelah itu, aku akan membuatkanmu mahkota bunga, seperti saat kita masih kecil... Aku akan membuatmu puluhan, tidak, ratusan mahkota bunga! Jadi tolong, Rebecca—",
  ui_story_5068_50681502_34_dialog_content = "Kamu harus melepaskan dia dulu, Isa. Jika tidak, kamu akan...",
  ui_story_5068_50681502_35_dialog_content = "Tidak! Aku sudah bilang aku tak akan melepaskannya, bahkan walaupun harus mati karenanya!",
  ui_story_5068_50681502_36_dialog_content = "Tunggu!",
  ui_story_5068_50681502_37_dialog_content = "... Racun Rebecca seharusnya bisa mengikis daging. Selama pertempuran kami, banyak dari kami yang terbakar oleh racunnya.",
  ui_story_5068_50681502_38_dialog_content = "Jadi bagaimana kamu bisa memegangnya dengan aman saat dia sepenuhnya tertutup racun?!",
  ui_story_5068_50681502_39_dialog_content = "... Apa yang kamu katakan?",
  ui_story_5068_50681502_40_dialog_content = "Tunggu, kamu benar! Kulit Rebecca terasa baik-baik saja, seperti biasa!",
  ui_story_5068_50681502_41_dialog_content = "Mungkin saja kamu benar-benar mewarisi salah satu kemampuan Keluarga Svanedona, Isa... Sebuah obat untuk racun Rebecca, yang dapat menetralisir efeknya!",
  ui_story_5068_50681502_42_dialog_content = "—!!",
  ui_story_5068_50681502_43_dialog_content = "Tidak ada waktu untuk disia-siakan! Cobalah melakukan sesuatu!",
  ui_story_5068_50681502_44_dialog_content = "Baiklah!",
  ui_story_5068_50681502_45_dialog_content = "...",
  ui_story_5068_50681502_46_dialog_content = "Sehat?",
  ui_story_5068_50681502_47_dialog_content = "Saya pikir itu hanya karena Isa memegang saya... Tapi rasa terbakar dari racun saya benar-benar terasa sedikit kurang intens...",
  ui_story_5068_50681502_48_dialog_content = "Apa itu artinya... berhasil?",
  ui_story_5068_50681502_49_dialog_content = "Ya!",
  ui_story_5068_50681502_50_dialog_content = "Oh, syukurlah! Aku tak akan pernah menduga...",
  ui_story_5068_50681502_51_dialog_content = "Kamu menghabiskan waktu untuk mengobati semua orang, tapi sekarang giliran saya untuk mengobati kamu! Tak peduli berapa lama, saya tidak akan berhenti sampai kamu benar-benar sembuh!",
  ui_story_5068_50681502_52_dialog_content = "Isa...",
  ui_story_5068_50681502_53_dialog_content = "Oh tunggu, itu mengingatkan saya.",
  ui_story_5068_50681502_54_dialog_content = "Aku menemukan ini lebih awal.",
  ui_story_5068_50681502_55_dialog_content = "Ini... adalah anting yang diberikan Eleanor padaku.",
  ui_story_5068_50681502_56_dialog_content = "... Mau aku bantu kamu memakainya?",
  ui_story_5068_50681502_57_dialog_content = "... Ya, silakan.",
  ui_story_5068_50681502_58_dialog_content = "Hmm... Sekarang aku pikirkan, anting-anting ini terlihat sangat cantik di kamu.",
  ui_story_5068_50681502_59_dialog_content = "...",
  ui_story_5068_50681502_60_dialog_content = "Eleanor... Terima kasih sudah menjaga adikku dengan baik. Mulai sekarang, aku berjanji akan melakukan hal yang sama.",
  ui_story_5068_50681601_1_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian</color>",
  ui_story_5068_50681601_2_dialog_content = "Ini hadiahmu seperti yang dijanjikan. Silakan periksa untuk memastikan semuanya ada.",
  ui_story_5068_50681601_3_dialog_content = "... Tugas itu terlalu berbahaya, tahu. Dan entah kenapa, aku tidak bisa menghubungimu bahkan saat situasi terburuk sekalipun...",
  ui_story_5068_50681601_4_dialog_content = "Dunia bisnis bisa kejam, tapi entah bagaimana kamu selalu berhasil membuat segalanya menjadi baik, bukan?",
  ui_story_5068_50681601_5_dialog_content = "Itulah mengapa, sebagai pemimpin yang rendah hati dari Cloudrover Guild, yang bisa saya minta hanyalah kesabaran dan pengertian Anda.",
  ui_story_5068_50681601_6_dialog_content = "Tentu, tapi... Aku hanya berpikir kompensasiku akan sedikit lebih besar setelah apa yang telah aku lalui.",
  ui_story_5068_50681601_7_dialog_content = "Heheh, kamu lebih tawar-menawar keras daripada Vice saat kamu mengambil alih. Aku harus lebih berhati-hati di sekitarmu mulai sekarang.",
  ui_story_5068_50681601_8_dialog_content = "Permisi, Nona Sheol!",
  ui_story_5068_50681601_9_dialog_content = "Oh, hai, PlayerName! Aku tidak tahu kamu ada di sini?",
  ui_story_5068_50681601_10_dialog_content = "Isa? Dan Rebecca juga?",
  ui_story_5068_50681601_11_dialog_content = "Sudah merasa lebih baik?",
  ui_story_5068_50681601_12_dialog_content = "Ya. Terima kasih kepada Isa, sekarang aku merasa jauh lebih baik.",
  ui_story_5068_50681601_13_dialog_content = "Tapi kamu masih memiliki jalan panjang sebelum benar-benar sembuh... Argh, kalau saja aku sedikit lebih kuat!",
  ui_story_5068_50681601_14_dialog_content = "Jangan bilang begitu, Isa! Aku bersyukur bisa bersama denganmu lagi.",
  ui_story_5068_50681601_15_dialog_content = "Saya bersyukur melihat bahwa \"dokter tanpa nama\" kita juga perlahan pulih.",
  ui_story_5068_50681601_16_dialog_content = "Tolong jangan bergurau seperti itu, Nona Sheol.",
  ui_story_5068_50681601_17_dialog_content = "Maaf, saya tidak bisa menahan diri setelah melihat kalian berdua seperti ini... Tapi sekarang semua orang yang terlibat ada di sini, saya ingin melaporkan temuan saya kepada kalian.",
  ui_story_5068_50681601_18_dialog_content = "Tentu saja, kamu berhak mengetahui apa yang terjadi pada Black Wolves setelah insiden itu.",
  ui_story_5068_50681601_19_dialog_content = "Tapi jika kamu lebih memilih untuk tidak mendengarnya...",
  ui_story_5068_50681601_20_dialog_content = "Tidak apa-apa, Nona Sheol. Tolong beri tahu kami.",
  ui_story_5068_50681601_21_dialog_content = "Tentu. Aku akan mencoba menjelaskannya secara singkat.",
  ui_story_5068_50681601_22_dialog_content = "Kami sudah mengumpulkan cukup bukti untuk menyalahkan Black Wolves dalam skema jahat mereka untuk menghasilkan kabut hitam. Sedangkan untuk Arte...",
  ui_story_5068_50681601_23_dialog_content = "Dia juga terkena kabut hitam pada malam itu. Di mana pun dia bersembunyi, aku ragu dia akan menimbulkan masalah lagi untuk kita mulai sekarang.",
  ui_story_5068_50681601_24_dialog_content = "Jadi, dia mendapatkan apa yang pantas dia terima! Bagus, sekarang aku bisa bernapas sedikit lebih lega.",
  ui_story_5068_50681601_25_dialog_content = "...",
  ui_story_5068_50681601_26_dialog_content = "Mengenai klinik Anda, saya lebih dari bersedia untuk membantu dalam rekonstruksinya.",
  ui_story_5068_50681601_27_dialog_content = "Terima kasih, tapi tidak usah, Lady Sheol. Kamu sudah melakukan lebih dari cukup untuk kami.",
  ui_story_5068_50681601_28_dialog_content = "Heheh, saya sudah menduga Rebecca akan menolakku, bukan kamu.",
  ui_story_5068_50681601_29_dialog_content = "Sebenarnya, kami datang untuk mengucapkan selamat tinggal hari ini, Ms. Sheol.",
  ui_story_5068_50681601_30_dialog_content = "Aku mengerti... Kamu yakin tidak ingin tinggal di sini? Aku tidak mencoba memaksamu bekerja untukku atau apa pun; aku hanya akan lebih bahagia jika kalian berdua tinggal bersama Cloudrover Guild.",
  ui_story_5068_50681601_31_dialog_content = "Kamu bilang begitu, tapi kamu tahu persis apa yang ada di pikiran kami saat kami masuk, bukan, Lady Sheol?",
  ui_story_5068_50681601_32_dialog_content = "Saya melihatnya di mata Anda, tepatnya... Jadi bukan hanya saya kehilangan Rebecca, tetapi juga salah satu asisten paling berguna saya. Oh, sayang sekali.",
  ui_story_5068_50681601_33_dialog_content = "Aku bahkan berencana meminta PlayerName untuk membantuku meyakinkanmu agar tetap tinggal, tapi kasihan anak itu tidak mengucapkan sepatah kata pun sejak kamu masuk. Aku harus bilang, aku kecewa padanya.",
  ui_story_5068_50681601_34_dialog_content = "Hah? A-Aku...",
  ui_story_5068_50681601_35_dialog_content = "Terima kasih atas tawaran murah hati Anda, Nona Sheol. Tapi keputusan kami sudah bulat.",
  ui_story_5068_50681601_36_dialog_content = "Dan... Terima kasih juga atas semua bantuanmu, PlayerName. Jika kamu tidak mempercayai saya dan tetap bersama saya sejak awal, saya tidak akan bisa...",
  ui_story_5068_50681601_37_dialog_content = "Jangan sungkan! Meskipun jika kamu pikirkan, aku sebenarnya tidak melakukan banyak hal...",
  ui_story_5068_50681601_38_dialog_content = "Jadi kalian berdua mau pergi ke mana selanjutnya? Sudah menentukan belum?",
  ui_story_5068_50681601_39_dialog_content = "Di Umbraton, lebih baik jangan bertanya terlalu banyak.",
  ui_story_5068_50681601_40_dialog_content = "Sepertinya para gadis memiliki rahasia yang harus dijaga.",
  ui_story_5068_50681601_41_dialog_content = "B-Begitu ya...? Lalu aku tidak akan bertanya lebih jauh. Tapi jika kamu punya waktu, kamu harus mengunjungi Eraveil suatu hari nanti. Cuaca yang baik dan pemandangan yang damai seharusnya membantu pemulihan Rebecca.",
  ui_story_5068_50681601_42_dialog_content = "Terima kasih atas undangannya, PlayerName. Saya punya firasat... Kita akan bertemu lagi cukup sebentar.",
  ui_story_5068_50681601_43_dialog_content = "Fiuh…",
  ui_story_5068_50681601_44_dialog_content = "Meskipun kita mengalami kekalahan lagi... Shadowlord seharusnya sangat puas dengan hasil kerja Guild Cloudrover.",
  ui_story_5068_50681601_45_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_5068_50681601_46_dialog_content = "Sudah selesai membersihkan, Isa? Dan apakah kamu melihat anting-antingku di mana-mana?",
  ui_story_5068_50681601_47_dialog_content = "Hah...? Apa yang kamu lihat?",
  ui_story_5068_50681601_48_dialog_content = "Hihihi...",
  ui_story_5068_50681601_49_dialog_content = "Apa itu... sebuah album foto? Kenapa isinya hanya foto-foto aku? Dan kapan kamu mengambil semua ini?",
  ui_story_5068_50681601_50_dialog_content = "Hah? R-Rebecca?! Apa kamu tidak pernah mengetuk sebelum masuk?!",
  ui_story_5068_50681601_51_dialog_content = "Tapi aku sudah mengetuk!",
  ui_story_5068_50681601_52_dialog_content = "L-Lalu seharusnya kau menunggu aku menjawab!",
  ui_story_5068_50681601_53_dialog_content = "Baik, aku paham.",
  ui_story_5068_50681601_54_dialog_content = "Tok, tok, tok. Halo Isa, bolehkah aku masuk?",
  ui_story_5068_50681601_55_dialog_content = "Oke, sekarang kau hanya menggoda saja! Tapi mari kita lihat bagaimana reaksimu dengan ini!",
  ui_story_5068_50681601_56_dialog_content = "Hahahaha—Berhenti, itu menggelitik! Maaf, Isa! Tolong berhenti, ya!",
  ui_story_5068_50681601_57_dialog_content = "Kamu tidak akan lolos begitu saja! Saatnya untuk serangan pamungkas ku!",
  ui_story_5068_50681601_58_dialog_content = "... Jadi apa maksud dari semua foto itu?",
  ui_story_5068_50681601_59_dialog_content = "Kamu benar-benar tidak tahu kapan harus berhenti, ya? Saya hanya ingin mendokumentasikan pemulihanmu, jadi saya memutuskan untuk mengambil beberapa foto!",
  ui_story_5068_50681601_60_dialog_content = "Begitu ya. Terima kasih sudah melakukannya untuk saya, Isa...",
  ui_story_5068_50681601_61_dialog_content = "Heeheehee! I-Itu bukan apa-apa, sungguh! Jadi, apa yang sebenarnya kamu butuhkan?",
  ui_story_5068_50681601_62_dialog_content = "Aku masih belum bisa menemukan anting-antingku...",
  ui_story_5068_50681601_63_dialog_content = "Jangan khawatir, mereka ada di sini! Lihat, aku sudah menjaga mereka dengan baik! Mau bantuan untuk memakainya?",
  ui_story_5068_50681601_64_dialog_content = "Isa... Apakah aku benar-benar melakukan sesuatu yang pantas membuat Eleanor mengorbankan hidupnya untukku?",
  ui_story_5068_50681601_65_dialog_content = "Entahlah. Tapi karena dia mau sampai sejauh itu, pasti kamu sudah melakukan sesuatu.",
  ui_story_5068_50681601_66_dialog_content = "Setidaknya itu yang saya pikirkan.",
  ui_story_5068_50681601_67_dialog_content = "...",
  ui_story_5068_50681601_68_dialog_content = "Oh, iya, hampir lupa! Sudahkah kamu menemukan nama untuk klinik baru itu?",
  ui_story_5068_50681601_69_dialog_content = "Belum... Tapi jujur saja, mengapa kita tidak menyebutnya \"Klinik Tanpa Nama\"?",
  ui_story_5068_50681601_70_dialog_content = "Hoot— Hoot—",
  ui_story_5068_50681601_71_dialog_content = "Nyonya... A-Aku tidak bisa bertahan lebih lama lagi... Tapi aku tahu kamu bisa menyelamatkanku...",
  ui_story_5068_50681601_72_dialog_content = "... Menyelamatkanmu? Aku tidak bisa memikirkan alasan untuk melakukan itu.",
  ui_story_5068_50681601_73_dialog_content = "A-Aku masih bisa berguna untukmu... Serigala Hitam, dan kabut hitam...",
  ui_story_5068_50681601_74_dialog_content = "Ya, kamu benar.",
  ui_story_5068_50681601_75_dialog_content = "Urgh—L-Lalu—",
  ui_story_5068_50681601_76_dialog_content = "Kesalahanmu terakhir kali adalah memilih bertarung dengan seseorang yang jauh di luar jangkauanmu.",
  ui_story_5068_50681601_77_dialog_content = "Y... Maksud kamu Sheol... Dan Cloudrover Guild?",
  ui_story_5068_50681601_78_dialog_content = "Kamu adalah anjing peliharaan yang setia, Arte. Tapi sepertinya kamu tidak puas hanya menjadi anjing peliharaan.",
  ui_story_5068_50681601_79_dialog_content = "T-Tentu saja, Nyonya! Saya akan melakukan apa pun yang Anda minta! Hanya tolong selamatkan saya—",
  ui_story_5068_50681601_80_dialog_content = "Nikmati momen terakhir yang menyakitkan dalam hidupmu yang menyedihkan ini. Kita tidak akan pernah bertemu lagi.",
  ui_story_5068_50681601_81_dialog_content = "Tolong, Nyonya! Jangan tinggalkan saya seperti ini! *batuk, batuk* Tolong... Selamatkan saya—",
  ui_story_5068_50681601_82_dialog_content = "Betapa tidak enak dipandang.",
  ui_story_5068_50681601_83_dialog_content = "Namun, itu semua tidak sia-sia...",
  ui_story_5068_50681601_84_dialog_content = "Setuju 'kan, Rebecca?"
}
return config
